local config = {
  ui_story_5071_50710101_1_dialog_content = "<size=45>Uraaagh—</size>",
  ui_story_5071_50710101_2_dialog_content = "<color=#e8d9bb>¡Wham!</color>",
  ui_story_5071_50710101_3_dialog_content = "...",
  ui_story_5071_50710101_4_dialog_content = "Urgh... *tos*",
  ui_story_5071_50710101_5_dialog_content = "No...",
  ui_story_5071_50710101_6_dialog_content = "¡Escuché que mató a todos!",
  ui_story_5071_50710101_7_dialog_content = "Él es el único que salió vivo de <color=#FFB400>el Pozo</color>. Debe ser cierto.",
  ui_story_5071_50710101_8_dialog_content = "No puedo creer lo que estoy escuchando. Incluso mató a su hermano más cercano para ganar poder...",
  ui_story_5071_50710101_9_dialog_content = "Nosotros... ¿Realmente podemos dejar el futuro de Umbraton en manos de una persona como esta?",
  ui_story_5071_50710101_10_dialog_content = "...",
  ui_story_5071_50710101_11_dialog_content = "Y ahora...",
  ui_story_5071_50710101_12_dialog_content = "Eres tú...",
  ui_story_5071_50710101_13_dialog_content = "<size=50>... ¿feliz?</size>",
  ui_story_5071_50710101_14_dialog_content = "<color=#e8d9bb>¡Toc, toc!</color>",
  ui_story_5071_50710101_15_dialog_content = "!",
  ui_story_5071_50710101_16_dialog_content = "Todos los que tomaron la forma de sombra corren el riesgo de ser devorados por la sombra.",
  ui_story_5071_50710101_17_dialog_content = "El pasado no es lo único que se esconde bajo la alfombra por la sombra, ¿verdad, mi hermano?",
  ui_story_5071_50710101_18_dialog_content = "<color=#e8d9bb>¡Toc, toc!</color>",
  ui_story_5071_50710101_19_dialog_content = "Papá, soy yo, Bethel.",
  ui_story_5071_50710101_20_dialog_content = "Pasa adelante...",
  ui_story_5071_50710101_21_dialog_content = "Padre, ya—",
  ui_story_5071_50710101_22_dialog_content = "...",
  ui_story_5071_50710101_23_dialog_content = "¿Estás bien, papá? Nunca te he visto tan agotado...",
  ui_story_5071_50710101_24_dialog_content = "Jaja, la moderación es la clave, no importa cuánto te guste el buen vino. Supongo que estoy en la edad en la que tengo que tener cuidado con esas cosas.",
  ui_story_5071_50710101_25_dialog_content = "Por favor, no lo tomes a la ligera de esa manera.",
  ui_story_5071_50710101_26_dialog_content = "Descarta eso como una broma entonces. Hablemos de ti.",
  ui_story_5071_50710101_27_dialog_content = "Por supuesto. Estoy preparado para el viaje.",
  ui_story_5071_50710101_28_dialog_content = "El camino a la Bahía de los Pabellones Gemelos ha sido reparado y asegurado lo suficiente como para que los avistamientos de Eclipsites sean raros.",
  ui_story_5071_50710101_29_dialog_content = "Pero mantén tus ojos abiertos para lo que nuestra Sombra no puede ver.",
  ui_story_5071_50710101_30_dialog_content = "Naturalmente, mi chica, creo que manejarás la reunión con los \"clientes\" allí perfectamente.",
  ui_story_5071_50710101_31_dialog_content = "No te defraudaré, papá.",
  ui_story_5071_50710101_32_dialog_content = "Bethel, como jefe del gremio, tu único deber es para Umbraton, no para alguien más.",
  ui_story_5071_50710101_33_dialog_content = "Padre...",
  ui_story_5071_50710101_34_dialog_content = "Está bien, también debería irme. Permíteme acompañarte a la salida.",
  ui_story_5071_50710101_35_dialog_content = "...",
  ui_story_5071_50710101_36_dialog_content = "Un gremio que surgió de las sombras para volar libremente por los cielos...",
  ui_story_5071_50710101_37_dialog_content = "<color=#FFB400>Tu sueño</color>... ¿Ya se ha hecho realidad?",
  ui_story_5071_50710101_38_dialog_content = "<color=#e8d9bb>¡Hacer clic!</color>",
  ui_story_5071_50710101_39_dialog_content = "¡No te equivoques, huelo chismes en el aire!",
  ui_story_5071_50710101_40_dialog_content = "¿Mmm?",
  ui_story_5071_50710101_41_dialog_content = "¡Hola, soy Brandy, reportero de The Daily Scoop!",
  ui_story_5071_50710101_42_dialog_content = "May ¿Qué opinas del <color=#FFB400>Dirigible Cloudrover</color> de tamaño extra grande construido por el Gremio de Explorador Nublar?",
  ui_story_5071_50710101_43_dialog_content = "Sin comentarios.",
  ui_story_5071_50710101_44_dialog_content = "Eso fue un rápido ponche. Estos magnates son tan duros como almejas para abrir.",
  ui_story_5071_50710101_45_dialog_content = "Pero mira quién está aquí—",
  ui_story_5071_50710101_46_dialog_content = "PlayerName! ¡Por aquí, por aquí!",
  ui_story_5071_50710101_47_dialog_content = "<color=#e8d9bb>¡Hacer clic!</color>",
  ui_story_5071_50710101_48_dialog_content = "¿Estás invitado al <color=#FFB400>lanzamiento inaugural</color> de hoy, PlayerName? ¿Qué te parece una palabra en la aeronave?",
  ui_story_5071_50710101_49_dialog_content = "Se siente familiar.",
  ui_story_5071_50710101_50_dialog_content = "Aunque la tecnología utilizada en este dirigible es diferente a la de los Colosos, sigue siendo un enorme buque capaz de volar.",
  ui_story_5071_50710101_51_dialog_content = "Se siente impresionante.",
  ui_story_5071_50710101_52_dialog_content = "Solo había visto aeronaves más pequeñas antes. No tenía idea de que Lady Sheol había construido una aeronave lo suficientemente grande como para llevar a toda su gremio...",
  ui_story_5071_50710101_53_dialog_content = "Este Dirigible Cloudrover es el pináculo de los dirigibles, pero no tan grande como tu Soroz, ¿verdad, PlayerName?",
  ui_story_5071_50710101_54_dialog_content = "No, pero... En términos de tamaño, probablemente sea tan grande como Eulogoz, donde realizaron ese concierto antes.",
  ui_story_5071_50710101_55_dialog_content = "¡Ah, ya veo el titular de mañana!",
  ui_story_5071_50710101_56_dialog_content = "\"Caelestite proclama: ¡La aeronave Cloudrover no es rival para Soroz!\"",
  ui_story_5071_50710101_57_dialog_content = "E-Espera, ¿por qué estás tergiversando mis palabras de esa manera?",
  ui_story_5071_50710101_58_dialog_content = "<color=#e8d9bb>Zzz—Zzz—</color>",
  ui_story_5071_50710101_59_dialog_content = "¡No temas al daño o al fracaso. ¡La persistencia se convertirá en suerte!",
  ui_story_5071_50710101_60_dialog_content = "¡Ha pasado mucho tiempo, mis queridos amigos! ¿Cómo están todos?",
  ui_story_5071_50710101_61_dialog_content = "¿No es esa... Goldie, la ídolo que actualmente es muy popular en Umbraton? ¡El Cloudrover Guild es tan impresionante como siempre si pueden conseguir que ella asista!",
  ui_story_5071_50710101_62_dialog_content = "¿No lo sabes? La Señora Sheol, la líder del Gremio de Explorador Nublar, es quien la hizo famosa!",
  ui_story_5071_50710101_63_dialog_content = "¿El Gremio de Explorador Nublar incluso ha metido sus manos en la industria del entretenimiento? ¿En cuántas industrias está involucrada Lady Sheol?",
  ui_story_5071_50710101_64_dialog_content = "¿A quién le importan los ídolos o las aeronaves? Todo eso son solo trucos... La única razón por la que estoy aquí es porque el Señor de las Sombras está presente.",
  ui_story_5071_50710101_65_dialog_content = "Por favor, tómenlo con calma, todos. ¡La ceremonia comenzará pronto!",
  ui_story_5071_50710101_66_dialog_content = "Hasta entonces, me gustaría interpretar un nuevo sencillo para ti—",
  ui_story_5071_50710101_67_dialog_content = "<size=45>¡Sueños al alcance!</size>",
  ui_story_5071_50710101_68_dialog_content = "¡Por favor, aspira a cabalgar el viento y tocar el cielo pronto conmigo!",
  ui_story_5071_50710101_69_dialog_content = "♪ En el cielo sin límites, las nubes manifiestan esperanza, mientras los sueños se elevan sobre el horizonte como el sol de la mañana ♪",
  ui_story_5071_50710101_70_dialog_content = "♪ Abre tus alas, vuela hacia el cielo y toca la luz brillante ♪",
  ui_story_5071_50710101_71_dialog_content = "(¿Eso es Goldie para ti, ¿verdad? Todo lo que se necesitó fue su canto para calmar a todos esos pasajeros enfadados. Incluso están asintiendo al ritmo de su canción ahora.)",
  ui_story_5071_50710101_72_dialog_content = "(Aún así... Si Goldie está aquí, entonces su club de fans chillones también debería estar aquí para reventar mis tímpanos, ¿verdad?)",
  ui_story_5071_50710101_73_dialog_content = "(No reconozco a ninguna de las personas que la Señorita Sheol invitó a bordo de la aeronave...)",
  ui_story_5071_50710101_74_dialog_content = "¡Está aquí! ¡Está aquí! ¡El Señor de las Sombras está aquí! Vamos para allá—",
  ui_story_5071_50710101_75_dialog_content = "(¿El Señor Sombrío también está aquí? Esto debe ser un evento especial después de todo...)",
  ui_story_5071_50710101_76_dialog_content = "Puntual como siempre, Señor de las Sombras. Un minuto más y te perderías el corte de cinta.",
  ui_story_5071_50710101_77_dialog_content = "Hacer una entrada en el momento adecuado cuando asisto a eventos como este es un secreto que aprendí de ti, Lady Sheol.",
  ui_story_5071_50710101_78_dialog_content = "¡Señor de las sombras! ¡Estoy tan feliz de verte en una ocasión tan alegre!",
  ui_story_5071_50710101_79_dialog_content = "Mi querido Señor de las Sombras, ¿todavía me recuerdas?",
  ui_story_5071_50710101_80_dialog_content = "Señor Sombrío, solicité una reunión privada contigo hace algún tiempo. ¿Has tenido tiempo de leer mi invitación ya?",
  ui_story_5071_50710101_81_dialog_content = "¡Señor de las Sombras! ¡No te olvides de mí! Señor de las Sombras—",
  ui_story_5071_50710101_82_dialog_content = "Damas y caballeros, el Señor de las Sombras ha decidido reunirse con cada uno de ustedes a bordo de la aeronave hoy.",
  ui_story_5071_50710101_83_dialog_content = "Por supuesto, solo aquellos que solicitaron una audiencia con él con suficiente antelación se les concede tal honor.",
  ui_story_5071_50710101_84_dialog_content = "Pero por ahora, dirijamos todos nuestra atención a nuestra maravillosa cantante y su animada actuación.",
  ui_story_5071_50710101_85_dialog_content = "Honestamente, nunca supe que reunirse con el Señor Sombrío requería tantas reglas.",
  ui_story_5071_50710101_86_dialog_content = "...",
  ui_story_5071_50710101_87_dialog_content = "Perdóname, no he tenido la oportunidad de presentarme correctamente. Soy Hanstie, líder del Gremio Continental. Esta es mi primera vez aquí y no estoy acostumbrado a las formalidades de Umbraton. Por favor, discúlpenme si interrumpí el disfrute de las festividades de alguien.",
  ui_story_5071_50710101_88_dialog_content = "Mira... ¿No es esa la señorita Hanstie de la Guilda Continental? Escuché que nunca se presenta a nada! La Señora Sheol seguro que es carismática... ¿o es este el carisma del Señor de las Sombras?",
  ui_story_5071_50710101_89_dialog_content = "¿El Gremio Continental? ¿Existe tal gremio en Umbraton?",
  ui_story_5071_50710101_90_dialog_content = "El Gremio Continental ha comenzado a hacer negocios en pequeñas ciudades fuera de Umbraton en los últimos años. Aunque acaba de establecer una base en Umbraton, ¡no se debe subestimar su impulso de desarrollo!",
  ui_story_5071_50710101_91_dialog_content = "Qué honor tenerla presente, señorita Hanstie.",
  ui_story_5071_50710101_92_dialog_content = "El Gremio Cloudrover ha invitado a todos los líderes de gremios respetables en Umbraton para este evento. ¿Cómo podría perder una oportunidad como esta?",
  ui_story_5071_50710101_93_dialog_content = "Además, cuando escuché que el famoso Señor Sombrío iba a hacer una aparición, supe que tenía que estar aquí.",
  ui_story_5071_50710101_94_dialog_content = "Ah, debes ser Lady Sheol, líder de la <color=#FFB400>Guild Cloudrover</color> y una figura a la que solo puedo admirar.",
  ui_story_5071_50710101_95_dialog_content = "Bromeas, señorita Hanstie.",
  ui_story_5071_50710101_96_dialog_content = "La red del <color=#FFB400>Gremio Continental</color> permea todo Astra. El cielo y la tierra pueden y coexisten.",
  ui_story_5071_50710101_97_dialog_content = "Tu dirigible es bastante impresionante, debo decir.",
  ui_story_5071_50710101_98_dialog_content = "Es un honor para el Gremio Cloudrover contar con el favor de la señorita Hanstie.",
  ui_story_5071_50710101_99_dialog_content = "Ahora bien, Señor de las Sombras, ¿puedo hablar contigo en privado?",
  ui_story_5071_50710101_100_dialog_content = "Perdóname, Sra. Hanstie—",
  ui_story_5071_50710101_101_dialog_content = "Estaba hablando con el Señor Sombrío, mi adorable pequeño pulpo.",
  ui_story_5071_50710101_102_dialog_content = "...",
  ui_story_5071_50710101_103_dialog_content = "Consideraré tu petición a fondo, Sra. Hanstie.",
  ui_story_5071_50710101_104_dialog_content = "Muy bien entonces. Espero ansiosamente tu respuesta.",
  ui_story_5071_50710101_105_dialog_content = "Programa una hora de reunión entre yo y la señora, Kleken.",
  ui_story_5071_50710101_106_dialog_content = "... Como desee, mi señor.",
  ui_story_5071_50710101_107_dialog_content = "(¿Espera, el Señor de las Sombras está rompiendo sus propias reglas por esa mujer extravagante?)",
  ui_story_5071_50710101_108_dialog_content = "¿Cuánto tiempo más vas a estar distraído en una esquina, PlayerName?",
  ui_story_5071_50710101_109_dialog_content = "¡S-Saludos, Señor de las Sombras! Todos estaban tan ocupados hace un momento que no tuve la oportunidad de saludarte antes.",
  ui_story_5071_50710101_110_dialog_content = "Ven, es nuestro turno de estar en el escenario.",
  ui_story_5071_50710101_111_dialog_content = "¿Ah?",
  ui_story_5071_50710101_112_dialog_content = "¡Espero que a todos les haya encantado esa canción! A continuación, damos la bienvenida a—",
  ui_story_5071_50710101_113_dialog_content = "Señor Sombrío Istvan, la líder del Gremio Cloudrover, Lady Sheol, y PlayerName, el invitado de honor de Astra, ¡quienes juntos cortarán la cinta!",
  ui_story_5071_50710101_114_dialog_content = "No sabía que tendrían ceremonias como esta...",
  ui_story_5071_50710101_115_dialog_content = "Está bien, querida, no estés nerviosa. Simplemente corta la cinta con las tijeras en la mano.",
  ui_story_5071_50710101_116_dialog_content = "<color=#e8d9bb>¡Corte!</color>",
  ui_story_5071_50710101_117_dialog_content = "El Dirigible Cloudrover es financiado y construido por Lady Sheol y su Gremio de Explorador Nublar, una super nave que combina turismo, compras, recreación y resorts, todo en uno.",
  ui_story_5071_50710101_118_dialog_content = "¡A partir de ahora, los Aurorians comunes como yo podemos jugar, comprar y vivir en el cielo como los Celestitas!",
  ui_story_5071_50710101_119_dialog_content = "Después del lanzamiento de hoy, el dirigible dará vueltas a Umbraton y realizará un espectáculo de fuegos artificiales sobre la ciudad por la noche. ¡Se vuelve más emocionante cuanto más lo pienso!",
  ui_story_5071_50710101_120_dialog_content = "¡Pero no te obsesiones solo con las vistas y olvides todos los eventos a bordo!",
  ui_story_5071_50710101_121_dialog_content = "Además del encuentro conmigo y la proyección especial de Alleywood de Umbraton, el dirigible también albergará la subasta aérea más transparente y conveniente que jamás haya existido!",
  ui_story_5071_50710101_122_dialog_content = "¡Así que, vamos a contar todos ahora!",
  ui_story_5071_50710101_123_dialog_content = "Tres-",
  ui_story_5071_50710101_124_dialog_content = "Dos-",
  ui_story_5071_50710101_125_dialog_content = "¡Uno!",
  ui_story_5071_50710101_126_dialog_content = "El Dirigible Cloudrover...",
  ui_story_5071_50710101_127_dialog_content = "<size=50>¡Despega!</size>",
  ui_story_5071_50710101_128_dialog_content = "¡Oh! Está volando ahora. ¡Realmente está volando!",
  ui_story_5071_50710101_129_dialog_content = "Te impresionas tan fácilmente. No es como si nunca hubieras estado en un dirigible antes. Cuando estaba en Lumopolis, veía esto suceder todos los días.",
  ui_story_5071_50710101_130_dialog_content = "Aunque Lumopolis es agradable, esa isla no puede moverse en absoluto. En cualquier caso, realmente admiro el agudo ojo para la inversión de Lady Sheol.",
  ui_story_5071_50710101_131_dialog_content = "Un ojo agudo, en efecto.",
  ui_story_5071_50710101_132_dialog_content = "Pero cualquier cosa que se eleve a los cielos...",
  ui_story_5071_50710101_X132_dialog_content = "Debe bajar eventualmente.",
  ui_story_5071_50710201_1_dialog_content = "<color=#e8d9bb>En la suite de lujo del Dirigible Explorador Nublar</color>",
  ui_story_5071_50710201_2_dialog_content = "Honorable Señor de las Sombras, estoy tan agradecido de que finalmente tengamos la oportunidad de encontrarnos hoy...",
  ui_story_5071_50710201_3_dialog_content = "¡Gracias a tu generosa ayuda, mi hijo finalmente realizó su deseo de asistir a la escuela en Lumopolis!",
  ui_story_5071_50710201_4_dialog_content = "Jaja, esas son noticias emocionantes.",
  ui_story_5071_50710201_5_dialog_content = "Tu hijo es muy inteligente y tiene sus propias ideas. Su duro trabajo condujo a esto.",
  ui_story_5071_50710201_6_dialog_content = "Sin embargo, ¿pareces preocupado?",
  ui_story_5071_50710201_7_dialog_content = "S-Simplemente me preocupo de que los nobles y sus hijos lo acosen debido a su estatus...",
  ui_story_5071_50710201_8_dialog_content = "Vaya, qué estoy diciendo... Señor de las Sombras, por favor perdóname por hablar tales tonterías.",
  ui_story_5071_50710201_9_dialog_content = "Es natural preocuparse por eso. Tu hijo es muy talentoso...",
  ui_story_5071_50710201_10_dialog_content = "Espero con ansias su regreso seguro y la fundación de una escuela en Umbraton más que nadie.",
  ui_story_5071_50710201_11_dialog_content = "Te prometo que todas tus preocupaciones nunca se harán realidad.",
  ui_story_5071_50710201_12_dialog_content = "Escucharte decir eso hace que mi corazón se sienta ligero como una pluma, ¡mi señor!",
  ui_story_5071_50710201_13_dialog_content = "He traído algunas botellas de vino de nuestro viñedo familiar. Por favor, acéptalas como muestra de nuestra gratitud, así como nuestra disculpa por tomar tanto de tu tiempo...",
  ui_story_5071_50710201_14_dialog_content = "No te preocupes. Adiós.",
  ui_story_5071_50710201_15_dialog_content = "<color=#e8d9bb>A bordo de la Aeronave Explorador Nublar, en el evento de apretón de manos de Goldie</color>",
  ui_story_5071_50710201_16_dialog_content = "¡Gracias por tu apoyo constante, PlayerName!",
  ui_story_5071_50710201_17_dialog_content = "¡No te defraudaré y seguiré haciendo buena música!",
  ui_story_5071_50710201_18_dialog_content = "¡No lo menciones! Realmente tienes una conexión especial con el cielo, ¿verdad? La canción de hoy también fue—",
  ui_story_5071_50710201_19_dialog_content = "¡Oye! ¿No se supone que solo debemos tener un minuto con Goldie? ¡Estás excediendo mucho tu tiempo!",
  ui_story_5071_50710201_20_dialog_content = "Lo siento, PlayerName. ¡No olvides visitarme en la oficina cuando tengas tiempo!",
  ui_story_5071_50710201_21_dialog_content = "¡Goldie! ¡Goldie! ¡También queremos charlar contigo un poco más!",
  ui_story_5071_50710201_22_dialog_content = "En poco tiempo, Goldie ha convertido a tantas personas en sus fans...",
  ui_story_5071_50710201_23_dialog_content = "Parece que todos mis viejos amigos están bastante ocupados ahora mismo... Supongo que tendré que pasear solo.",
  ui_story_5071_50710201_24_dialog_content = "Señor, ¿todavía me recuerda? Yo... yo solía vivir al lado de su casa!",
  ui_story_5071_50710201_25_dialog_content = "No estabas en casa cuando tus padres fallecieron... También contribuí para cubrir los gastos del funeral...",
  ui_story_5071_50710201_26_dialog_content = "Gracias por la generosa ayuda para darles un lugar de descanso pacífico.",
  ui_story_5071_50710201_27_dialog_content = "¡S-Sí, pero... pero necesito tu ayuda ahora más que nunca!",
  ui_story_5071_50710201_28_dialog_content = "Gracias a ti, pude abrir varias tiendas generales. Mi negocio no se compara con el Gremio de Explorador Nublar, pero se desempeña lo suficientemente bien por aquí.",
  ui_story_5071_50710201_29_dialog_content = "Desafortunadamente, las tiendas cercanas han estado trabajando juntas para sacarme del negocio últimamente. Ya estoy al borde de la bancarrota...",
  ui_story_5071_50710201_30_dialog_content = "No sé qué más hacer, mi señor. Por favor, ayúdame...",
  ui_story_5071_50710201_31_dialog_content = "¿Quieres que te ayude a deshacerte de ellos?",
  ui_story_5071_50710201_32_dialog_content = "¿E-Estaría eso aceptable?",
  ui_story_5071_50710201_33_dialog_content = "¿Por qué no unirse simplemente al gremio? Siempre y cuando operes de acuerdo con las regulaciones, te ofrecerán una protección sustancial.",
  ui_story_5071_50710201_34_dialog_content = "Yo... Me dijeron que unirse al gremio requiere una cuota de membresía considerable...",
  ui_story_5071_50710201_35_dialog_content = "¿Cómo lo sabrías si nunca cruzaste su puerta para descubrir la verdad?",
  ui_story_5071_50710201_36_dialog_content = "¡Lo sabía! ¡Esos sinvergüenzas me estaban mintiendo todo el tiempo!",
  ui_story_5071_50710201_37_dialog_content = "Entonces... ¿Podría unirme a tu gremio?",
  ui_story_5071_50710201_38_dialog_content = "No soy el líder del gremio, pero puedo decirte que su puerta siempre está abierta para cualquiera.",
  ui_story_5071_50710201_39_dialog_content = "Confía en mí. Solo te arrepentirás de no haberlo hecho antes.",
  ui_story_5071_50710201_40_dialog_content = "¡Oh, gracias! ¡Muchas gracias, Señor de las Sombras! A partir de ahora, siempre te brindaré mi apoyo... ¡y también a las decisiones del gremio!",
  ui_story_5071_50710201_41_dialog_content = "Las personas que enterraron a tus padres deberían haber dejado este mundo hace mucho tiempo. Parece que ese hombre y yo compartimos un \"hobby\" similar.",
  ui_story_5071_50710201_42_dialog_content = "Ese no es el punto, Kleken. Dile qué debería hacer a continuación.",
  ui_story_5071_50710201_43_dialog_content = "Muy bien, Señor Sombrío.",
  ui_story_5071_50710201_44_dialog_content = "<color=#e8d9bb>Fuera del cine de la aeronave Explorador Nublar</color>",
  ui_story_5071_50710201_45_dialog_content = "Hmm, \"Una historia juvenil basada en una historia real, 'Chasing Alleywood' está en cartelera con un boleto restante.\"",
  ui_story_5071_50710201_46_dialog_content = "¿Es esta la última obra de Lilica? Esto explicaría por qué no he tenido noticias de ella durante tanto tiempo...",
  ui_story_5071_50710201_47_dialog_content = "Bueno, no tengo nada mejor que hacer, así que podría mostrar algo de apoyo.",
  ui_story_5071_50710201_48_dialog_content = "¡Disculpe, me gustaría comprar el último boleto para \"Chasing Alleywood\", por favor!",
  ui_story_5071_50710201_49_dialog_content = "¿E-Eh? ¡Brandy se llevó el último boleto para ella misma!",
  ui_story_5071_50710201_50_dialog_content = "¿Qué le pasa a este niño? ¿Por qué no habla?",
  ui_story_5071_50710201_51_dialog_content = "¿Está perdido? ¿Por qué sus padres no lo buscan?",
  ui_story_5071_50710201_52_dialog_content = "¿De quién es este niño?",
  ui_story_5071_50710201_53_dialog_content = "¿Qué pasa con toda esa gente allá? ¿Otro evento?",
  ui_story_5071_50710201_54_dialog_content = "*resoplando*",
  ui_story_5071_50710201_55_dialog_content = "¿Eh? ¿Un niño pequeño?",
  ui_story_5071_50710201_56_dialog_content = "Waaah—",
  ui_story_5071_50710201_57_dialog_content = "¡H-Hey! ¿Por qué de repente se agarra a mí así?",
  ui_story_5071_50710201_58_dialog_content = "Deben ser familia... Ese pobre niño no dudó en correr hacia él.",
  ui_story_5071_50710201_59_dialog_content = "¿Eres el hermano mayor de este niño? ¿Cómo pudiste dejarlo solo así? ¡Solo mira su pobre rostro llorando!",
  ui_story_5071_50710201_60_dialog_content = "¡Deberías ser más cuidado a partir de ahora!",
  ui_story_5071_50710201_61_dialog_content = "...",
  ui_story_5071_50710201_62_dialog_content = "...",
  ui_story_5071_50710201_63_dialog_content = "Mmm... May ¿Puedo preguntar quién eres?",
  ui_story_5071_50710201_64_dialog_content = "<color=#e8d9bb>*gruñido estomacal*</color>",
  ui_story_5071_50710201_65_dialog_content = "Yo... tengo tanta hambre...",
  ui_story_5071_50710201_66_dialog_content = "¿Confío en que has estado bien, Señor de las Sombras?",
  ui_story_5071_50710201_67_dialog_content = "¿Marqués? Pensé que habías estado pasando todo tu tiempo leyendo con tu nieta en tu finca de Lumopolis últimamente.",
  ui_story_5071_50710201_68_dialog_content = "Jaja, si no hubiera venido, temo que un cierto grupo y sus llamadas \"reformas\" me habrían robado todo lo que poseo aquí en Umbraton.",
  ui_story_5071_50710201_69_dialog_content = "Dime, con las exorbitantes cuotas de membresía que cobra el gremio, ¿cómo podrían haber sido incapaces de comer hasta saciarse últimamente?",
  ui_story_5071_50710201_70_dialog_content = "Jaja, eso es una historia diferente, señor.",
  ui_story_5071_50710201_71_dialog_content = "Ese pequeño gremio tuyo fue cerrado debido a una violación de las regulaciones del gremio.",
  ui_story_5071_50710201_72_dialog_content = "Siempre que se hagan correcciones y se abandonen las... prácticas dudosas, se permite reabrir.",
  ui_story_5071_50710201_73_dialog_content = "Además, la mayoría de las cuotas de membresía pagadas se entregan a Lumopolis como \"impuesto a la propiedad\" según lo acordado.",
  ui_story_5071_50710201_74_dialog_content = "El resto se gasta en el mantenimiento regular del gremio—",
  ui_story_5071_50710201_75_dialog_content = "Tus palabras engañosas me recuerdan mucho a tu hija adoptiva. Si no supiera mejor, diría que podría pasar por una de las tuyas.",
  ui_story_5071_50710201_76_dialog_content = "¿Por qué te molestarías en verme cuando ya has escuchado la propuesta del líder del gremio entonces?",
  ui_story_5071_50710201_77_dialog_content = "Deja ya la farsa, Istvan...",
  ui_story_5071_50710201_78_dialog_content = "¿Sabes lo que Umbraton necesita para mantener su prosperidad actual, verdad?",
  ui_story_5071_50710201_79_dialog_content = "Es lo mismo que la Pandilla Istvan necesitaba en sus inicios, ¿recuerdas?",
  ui_story_5071_50710201_80_dialog_content = "Tus manos están mucho más sucias que las de cualquier otra persona a bordo de este dirigible. ¿Realmente crees que puedes lavar tus pecados?",
  ui_story_5071_50710201_81_dialog_content = "¡Estas \"reformas\" solo serán tu perdición!",
  ui_story_5071_50710201_82_dialog_content = "Jaja, ¿es eso así?",
  ui_story_5071_50710201_83_dialog_content = "Bueno, estoy un poco ansioso por averiguarlo...",
  ui_story_5071_50710201_84_dialog_content = "Cómo una reforma para poner a Umbraton en el camino correcto podría ser perjudicial para mí.",
  ui_story_5071_50710201_85_dialog_content = "Munch, munch, trago...",
  ui_story_5071_50710201_86_dialog_content = "¡Oye, más despacio o te vas a ahogar!",
  ui_story_5071_50710201_87_dialog_content = "Dos pollos asados, cuatro pizzas y cinco porciones de pastel... ¿Cuándo fue tu última comida?",
  ui_story_5071_50710201_88_dialog_content = "Munch, munch... H-Han pasado tres horas desde mi última comida... Estaba muriendo de hambre justo ahora...",
  ui_story_5071_50710201_89_dialog_content = "¿Estabas hambriento después de solo tres horas?",
  ui_story_5071_50710201_90_dialog_content = "Yo... Me pongo nervioso cuando estoy cerca de extraños... tan nervioso que agoto toda mi energía, así que...",
  ui_story_5071_50710201_91_dialog_content = "Um... ¡Seguro que te pagaré por la comida!",
  ui_story_5071_50710201_92_dialog_content = "P-Pero ¿podrías... ayudarme a encontrar a la Señora Sheol?",
  ui_story_5071_50710201_93_dialog_content = "Señora... Sheol?",
  ui_story_5071_50710201_94_dialog_content = "M-Mi nombre es Vergil. Soy uno de los empleados de la Señora Sheol...",
  ui_story_5071_50710201_95_dialog_content = "Yo... No me di cuenta de que Lady Sheol contrataba a niños para trabajar para ella.",
  ui_story_5071_50710201_96_dialog_content = "¡P-P-P-Por favor, no me malinterpretes! ¡Yo fui el que le pedí que me contratara!",
  ui_story_5071_50710201_97_dialog_content = "No sé exactamente qué está pasando, pero puedo sentir la presencia de la Señora Sheol cerca—",
  ui_story_5071_50710201_98_dialog_content = "¡Alto!",
  ui_story_5071_50710201_99_dialog_content = "¡Objetivo localizado!",
  ui_story_5071_50710201_100_dialog_content = "¡Los perros guardianes están aquí!",
  ui_story_5071_50710201_101_dialog_content = "¡Ataque de perros!",
  ui_story_5071_50710201_102_dialog_content = "¿No es eso... donde el Señor Sombrío se está reuniendo con la gente?",
  ui_story_5071_50710302_1_dialog_content = "¿Está bien, señora?",
  ui_story_5071_50710302_2_dialog_content = "Yo... Estoy bien. Gracias por tu ayuda.",
  ui_story_5071_50710302_3_dialog_content = "Patty, Patsy, ¿pueden decirme qué está pasando?",
  ui_story_5071_50710302_4_dialog_content = "¡Nosotros los perritos somos los mejores guardias!",
  ui_story_5071_50710302_5_dialog_content = "¡Nadie pasa de nosotros a menos que tenga una reserva!",
  ui_story_5071_50710302_6_dialog_content = "Seguro que son cachorros leales, pero no provoquemos una conmoción tan grande la próxima vez.",
  ui_story_5071_50710302_7_dialog_content = "Podrías caerte provocando un alboroto de esa manera.",
  ui_story_5071_50710302_8_dialog_content = "¡Los perros nunca muestran miedo!",
  ui_story_5071_50710302_9_dialog_content = "Pero no sería una buena idea interrumpir la reunión del Señor de las Sombras en el interior.",
  ui_story_5071_50710302_10_dialog_content = "No molestar al Señor de las Sombras... ¡Incluso nosotros sabemos eso!",
  ui_story_5071_50710302_11_dialog_content = "Entonces, señora, ¿con qué líder de gremio está usted? Por favor, perdóneme, pero no recuerdo haber enviado una invitación a alguien como usted.",
  ui_story_5071_50710302_12_dialog_content = "El parecido es increíble... Cuando miro más de cerca, eres casi exactamente igual...",
  ui_story_5071_50710302_13_dialog_content = "¿...?",
  ui_story_5071_50710302_14_dialog_content = "L... ¡Señora Sheol!",
  ui_story_5071_50710302_15_dialog_content = "¿Vergil? ¿Qué estás haciendo aquí? ¿No te dije que me esperaras en la subasta aérea?",
  ui_story_5071_50710302_16_dialog_content = "Yo... estaba muriendo de hambre hace un momento, así que salí a buscar algo de comida... Pero había tanta gente afuera que terminé perdiéndome.",
  ui_story_5071_50710302_17_dialog_content = "¡Pero esta buena persona me salvó, e incluso pagó por una gran y sabrosa comida para que yo comiera!",
  ui_story_5071_50710302_18_dialog_content = "Jaja... No fue nada.",
  ui_story_5071_50710302_19_dialog_content = "¿Ya te has hecho amigo de PlayerName? Pensé que el pequeño Vergil no hablaba con extraños.",
  ui_story_5071_50710302_20_dialog_content = "E-Eso es porque... PlayerName emana el aroma de antigüedades por alguna razón, y realmente me tranquiliza...",
  ui_story_5071_50710302_21_dialog_content = "Bueno, eso es cierto. Podrías llamar a PlayerName un antiguo recién acuñado.",
  ui_story_5071_50710302_22_dialog_content = "PlayerName... Espera, ¿no me digas que eres el legendario Caelestite?!",
  ui_story_5071_50710302_23_dialog_content = "Aún no ha respondido a mi pregunta, señora. ¿Quién es usted y qué hace aquí?",
  ui_story_5071_50710302_24_dialog_content = "Un recordatorio amigable, la seguridad de este barco no es más suave que los cachorros del Señor de las Sombras.",
  ui_story_5071_50710302_25_dialog_content = "Yo... Yo soy Yvonne, una escritora. La editorial Cross Street me invitó aquí como invitada especial.",
  ui_story_5071_50710302_26_dialog_content = "Por favor, perdóname por haber causado un escándalo hace un momento. No me di cuenta de que necesitaba una reserva para ver al Señor de las Sombras a bordo del dirigible hoy.",
  ui_story_5071_50710302_27_dialog_content = "Yvonne... Espera, ¿te refieres a LA Sra. Yvonne, la escritora mundialmente famosa?!",
  ui_story_5071_50710302_28_dialog_content = "... Me sorprende que alguien tan joven como tú esté familiarizado con mis obras, considerando que no he escrito nada nuevo en años.",
  ui_story_5071_50710302_29_dialog_content = "La escritura de la Sra. Yvonne es un testimonio del pasado de Umbraton. Cada persona alfabetizada en la ciudad ha leído su trabajo.",
  ui_story_5071_50710302_30_dialog_content = "Pero rara vez te muestras en público, entonces ¿por qué hoy...",
  ui_story_5071_50710302_31_dialog_content = "Era mucho más joven en aquel entonces, y siempre estaba preocupado o preocupado por una cosa u otra. Ahora que soy mayor, me he vuelto un poco más valiente que antes.",
  ui_story_5071_50710302_32_dialog_content = "Si no fuera por esto, nunca me habría subido solo a este dirigible por mi manuscrito inacabado.",
  ui_story_5071_50710302_33_dialog_content = "¿Manuscrito?",
  ui_story_5071_50710302_34_dialog_content = "Después de que mi último libro recibiera críticas tan horribles, estaba seguro de que nunca volvería a escribir.",
  ui_story_5071_50710302_35_dialog_content = "Pero no pasó mucho tiempo, conocí y me hice amigo de un cierto <color=#FFB400>artista</color> que compartió conmigo una serie de cuentos fascinantes.",
  ui_story_5071_50710302_36_dialog_content = "Estas historias, que se basaban en hechos reales, eran mucho más emocionantes que incluso la obra de ficción más cuidadosamente redactada. ¡Apenas podía dormir después de escucharlas!",
  ui_story_5071_50710302_37_dialog_content = "Pensé que estos cuentos merecían algo mejor que acumular polvo en el pasado olvidado de Umbraton. A instancias de mi amigo, volví a tomar mi pluma...",
  ui_story_5071_50710302_38_dialog_content = "La historia en la que estoy trabajando es maravillosa tal como está, pero temo que aún faltan ciertos detalles. Por esta razón, busqué entrevistar al Señor de las Sombras hoy.",
  ui_story_5071_50710302_39_dialog_content = "... Incluso a pesar del peligro, y mi incertidumbre sobre si compartirá o no su conocimiento con un escritor fracasado como yo.",
  ui_story_5071_50710302_40_dialog_content = "¿Peligro...? ¿Qué tiene de peligroso escribir historias?",
  ui_story_5071_50710302_41_dialog_content = "Si este libro se publicara, todos conocerían la razón detrás de ello.",
  ui_story_5071_50710302_42_dialog_content = "Veo que mantienes a tus lectores en suspenso, como lo haría un buen escritor.",
  ui_story_5071_50710302_43_dialog_content = "Lady Sheol, puede que esté sobrepasando mis límites al preguntar, pero ¿podrías presentarme al Señor de las Sombras? Prometo que no tomaré demasiado de su valioso tiempo!",
  ui_story_5071_50710302_44_dialog_content = "Bueno, si me negara a ayudar, los círculos literarios en Umbraton nos acusarían nuevamente a nosotros, los empresarios, de ser unos incultos acaparadores de dinero.",
  ui_story_5071_50710302_45_dialog_content = "No es que nunca me importara tal crítica... Sin embargo, ¡soy un gran fan de tus libros!",
  ui_story_5071_50710302_46_dialog_content = "Y no es la primera vez que el Señor de las Sombras hace una excepción hoy de todos modos. Por favor, dame un minuto.",
  ui_story_5071_50710302_47_dialog_content = "Ejem, ¿Señorita Yvonne? ¿Estaría bien si Vergil obtuviera un autógrafo suyo? Él está demasiado avergonzado para pedírtelo él mismo...",
  ui_story_5071_50710302_48_dialog_content = "¿Un autógrafo? ¡No hay nada de qué avergonzarse, pequeño! Estoy agradecido de que disfrutes tanto de mi trabajo. Solo tengo a mano papel en blanco, ¿será eso un problema?",
  ui_story_5071_50710302_49_dialog_content = "N... ¡¡Para nada!!",
  ui_story_5071_50710302_50_dialog_content = "Ahí, solo para ti. No es mucho, pero si tenemos la oportunidad de encontrarnos de nuevo, me encantaría presentarte una copia de...",
  ui_story_5071_50710302_51_dialog_content = "¡Eso me recuerda! ¿Cuál de mis libros te gusta más?",
  ui_story_5071_50710302_52_dialog_content = "¡R-r-r-realmente disfruté \"Señora Mercurio Rojo\"!",
  ui_story_5071_50710302_53_dialog_content = "Ese título...",
  ui_story_5071_50710302_54_option_content = "Suena familiar...",
  ui_story_5071_50710302_55_dialog_content = "¡Creo que tengo una copia de esa historia en el Colossus!",
  ui_story_5071_50710302_56_option_content = "Efectivamente, nunca lo había escuchado...",
  ui_story_5071_50710302_57_dialog_content = "La historia... Trata sobre una hermosa, pero fría y misteriosa líder de gremio llamada Sra. Mercurio Rojo.",
  ui_story_5071_50710302_58_dialog_content = "En nombre del amor, abandona su estatus noble sin dudarlo y viaja a Umbraton.",
  ui_story_5071_50710302_59_dialog_content = "Pero después de que muere su esposo, ella toma el control de varios pequeños gremios y venga silenciosamente a su amor caído.",
  ui_story_5071_50710302_60_dialog_content = "¿Estás hablando de \"La Sra. Mercurio Rojo\"? También me encanta ese libro.",
  ui_story_5071_50710302_61_dialog_content = "¿E-Es así? Estoy tan contento de que te haya gustado...",
  ui_story_5071_50710302_62_dialog_content = "He enviado palabras, Sra. Yvonne. Deberíamos tener noticias pronto.",
  ui_story_5071_50710302_63_dialog_content = "Esa es una noticia maravillosa... ¡Muchas gracias, Lady Sheol!",
  ui_story_5071_50710302_64_dialog_content = "El destino puede ser algo tan extraño, y no quería decir nada antes... Pero tienes un parecido sorprendente con la Señora <color=#FFB400>Melissa</color>.",
  ui_story_5071_50710302_65_dialog_content = "¿Conoces a Melissa? Así que el libro realmente era...",
  ui_story_5071_50710302_66_dialog_content = "Sí. El personaje de la Sra. Mercurio Rojo está basado en Lady Melissa, una persona real.",
  ui_story_5071_50710302_67_dialog_content = "¿Lady Melissa? ¿Quién es esa?",
  ui_story_5071_50710302_68_dialog_content = "Tampoco lo sabes, ¿eh? Si tuviera que adivinar... Esta Lady Melissa es alguien realmente importante para Lady Sheol.",
  ui_story_5071_50710302_69_dialog_content = "...",
  ui_story_5071_50710302_70_dialog_content = "Sra. Yvonne, estoy verdaderamente agradecido por su fiel descripción de ella en el libro, dándome la oportunidad de sentir su carisma.",
  ui_story_5071_50710302_71_dialog_content = "Me dijeron que el niño de Melissa fue secuestrado y envenenado por sus enemigos... Pero ahora veo que heredó la tenacidad de su mamá.",
  ui_story_5071_50710302_72_dialog_content = "No suelo arrepentirme de algo, pero ahora estoy reconsiderando no haber invertido nunca en el negocio editorial. Tal vez podría haberte conocido antes entonces.",
  ui_story_5071_50710302_73_dialog_content = "Estoy seguro de que tendremos muchas oportunidades de encontrarnos en el futuro, siempre y cuando no te importe que indague en el pasado.",
  ui_story_5071_50710302_74_dialog_content = "Amo las historias, especialmente cuando son sobre ella...",
  ui_story_5071_50710302_75_dialog_content = "Además, estoy muy interesado en publicar el libro que estás escribiendo ahora.",
  ui_story_5071_50710302_76_dialog_content = "E-Eso sería...",
  ui_story_5071_50710302_77_dialog_content = "No podría comenzar a imaginar la mirada de alegría radiante en el rostro de Lady Melissa si pudiera ver cuán exitosa se ha vuelto su hija.",
  ui_story_5071_50710302_78_dialog_content = "Tu generosidad con tus clientes es admirable, Lady Sheol. Solo desearía que supieras cuánto problema crea para tus asociados.",
  ui_story_5071_50710302_79_dialog_content = "¿Ya tenemos una respuesta?",
  ui_story_5071_50710302_80_dialog_content = "¿Así que esta es la ilustre Sra. Yvonne?",
  ui_story_5071_50710302_81_dialog_content = "El Señor de las Sombras ha accedido a una audiencia. Por aquí, por favor.",
  ui_story_5071_50710302_82_dialog_content = "(!!!)",
  ui_story_5071_50710302_83_dialog_content = "¡Estoy eternamente agradecido por tu ayuda, Lady Sheol!",
  ui_story_5071_50710302_84_dialog_content = "Tú mismo dijiste que es el destino. Espero hablar sobre tu trabajo pasado contigo después de tu reunión con el Señor Sombrío.",
  ui_story_5071_50710302_85_dialog_content = "Sería mi honor.",
  ui_story_5071_50710302_86_dialog_content = "...",
  ui_story_5071_50710302_87_dialog_content = "¿Por qué estás parado ahí, querido PlayerName?",
  ui_story_5071_50710302_88_dialog_content = "O...",
  ui_story_5071_50710302_89_dialog_content = "¿Has desarrollado un interés repentino en mi pasado?",
  ui_story_5071_50710401_1_dialog_content = "<color=#e8d9bb>Aproximadamente hace diez años</color>",
  ui_story_5071_50710401_2_dialog_content = "¡Mira! ¿Son esas personas de la coalición que terminó la Crisis de Darkover?",
  ui_story_5071_50710401_3_dialog_content = "Se están moviendo hacia Lumopolis... ¿Podrían ser caballeros de Lumopolis?!",
  ui_story_5071_50710401_4_dialog_content = "Todos los Caballeros de Lumopolis visten uniformes brillantes, mientras que estas personas lucen oscuros y grises. Es muy probable que sean de Umbraton.",
  ui_story_5071_50710401_5_dialog_content = "¿No arrasaron los Eclipsites Umbraton hace mucho tiempo? ¿Todavía vive gente allí?",
  ui_story_5071_50710401_6_dialog_content = "Escuché que muchos de ellos sobrevivieron gracias a la ayuda que recibieron de Lumopolis.",
  ui_story_5071_50710401_7_dialog_content = "Es tan agradable tener una fuerza tan poderosa cuidándolos. No importa cuán malas se pongan las cosas, su maestro les ayudará una vez que comiencen a mover la cola.",
  ui_story_5071_50710401_8_dialog_content = "¡Shhh! ¡Baja la voz! Estas personas pueden matar a un Eclipsite con una bofetada, así que más te vale tener cuidado.",
  ui_story_5071_50710401_9_dialog_content = "¡Espera! ¿No es ese Sheol? ¡Oye, qué estás haciendo?!",
  ui_story_5071_50710401_10_dialog_content = "En lugar de ser sarcástico, ¿por qué no vas y hablas con ellos? Después de todo, son héroes que vencieron a los Eclipsites.",
  ui_story_5071_50710401_11_dialog_content = "Sheol... Aunque nos has ayudado a ahuyentar a los Eclipsites muchas veces, estas personas podrían ser más peligrosas que los Eclipsites. ¡Ten cuidado e intenta no morir en el intento!",
  ui_story_5071_50710401_12_dialog_content = "Relájate. No creo que nadie tenga un problema con el dinero y aprovecharse, ¿verdad?",
  ui_story_5071_50710401_13_dialog_content = "¡Alto ahí! ¿Quién eres tú?",
  ui_story_5071_50710401_14_dialog_content = "No te alteres tanto. Mira, no soy un Eclipsite.",
  ui_story_5071_50710401_15_dialog_content = "Solo quiero recordarles a todos que hace calor y está seco aquí, así que si tienes sed, hay agua helada gratis en mi tienda!",
  ui_story_5071_50710401_16_dialog_content = "Desafortunadamente, en este mundo no existe algo como un almuerzo gratis.",
  ui_story_5071_50710401_17_dialog_content = "No hay almuerzo gratis pero el agua es gratuita. Por supuesto, si lo que quieres es almorzar, ¡eso también lo vendo!",
  ui_story_5071_50710401_18_dialog_content = "Cajas combinadas de auténtico escorpión del desierto asado, algo que no conseguirás en Umbraton.",
  ui_story_5071_50710401_19_dialog_content = "No te molestes. Deberíamos irnos.",
  ui_story_5071_50710401_20_dialog_content = "¿No deberías tomar un descanso después de venir hasta aquí? Puede que no estés cansado, pero ¿qué pasa con los soldados?",
  ui_story_5071_50710401_21_dialog_content = "Jejeje, dicen que las personas de aquí son conocidas por sus temperamentos explosivos, pero pareces ser una excepción.",
  ui_story_5071_50710401_22_dialog_content = "¡Todos los que quieran agua y una buena comida, síganme!",
  ui_story_5071_50710401_23_dialog_content = "<color=#e8d9bb>Sheol se quita un guante y comienza a agitarlo, haciendo todo lo posible para llamar la atención de todos a su alrededor.</color>",
  ui_story_5071_50710401_24_dialog_content = "<color=#e8d9bb>Bajo la brillante luz del sol, una delgada cicatriz en el antebrazo de Sheol emite un resplandor rojizo, pareciendo justo como la lengua parpadeante de un aperitivo.</color>",
  ui_story_5071_50710401_25_dialog_content = "<color=#e8d9bb>Istvan buscó el origen del sonido que escuchó y comenzó a observar cuidadosamente la apariencia de esta mujer.</color>",
  ui_story_5071_50710401_26_dialog_content = "¡Espera! ¿E-Eres tú, Melissa? No... Tú eres...",
  ui_story_5071_50710401_27_dialog_content = "¿Sheol?!",
  ui_story_5071_50710401_28_dialog_content = "No recuerdo haberte dicho mi nombre.",
  ui_story_5071_50710401_29_dialog_content = "Aunque soy un poco conocido por aquí. Entonces, ¿qué está pasando...",
  ui_story_5071_50710401_30_dialog_content = "¡Finalmente le encontré!",
  ui_story_5071_50710401_31_dialog_content = "Jaja, pensé que nunca tendría la oportunidad de cumplir esta promesa otra vez...",
  ui_story_5071_50710401_32_dialog_content = "¡Ven! Volvamos a Umbraton, ¡tu verdadero hogar!",
  ui_story_5071_50710401_33_dialog_content = "(Parece que los aldeanos tenían razón sobre lo caprichosas e irracionales que son las personas de Umbraton.)",
  ui_story_5071_50710401_34_dialog_content = "Bueno, sí quiero visitar Umbraton, pero todavía tengo una tienda que cuidar...",
  ui_story_5071_50710401_35_dialog_content = "Y mira la hora... ¡Debo volver allí ahora mismo!",
  ui_story_5071_50710401_36_dialog_content = "Por favor, no malinterpretes—",
  ui_story_5071_50710401_37_dialog_content = "¡Ni un centímetro más cerca!",
  ui_story_5071_50710402_1_dialog_content = "Jajaja, como se esperaba de la hija de Melissa! Incluso sin un entrenamiento adecuado, tus habilidades de combate no se pueden ignorar.",
  ui_story_5071_50710402_2_dialog_content = "¿Qué quieres? Solo soy un comerciante de poca monta, ¿qué valor tengo para ti?",
  ui_story_5071_50710402_3_dialog_content = "Perdóname por no explicar las cosas más claramente. La verdad es que estoy ayudando a una vieja amiga a encontrar a su hija perdida hace mucho tiempo.",
  ui_story_5071_50710402_4_dialog_content = "Crecí en el desierto. ¿Qué vínculos tengo con Umbraton?",
  ui_story_5071_50710402_5_dialog_content = "Si no me equivoco, tienes una pequeña marca en forma de serpiente en tu brazo. ¿Es eso correcto?",
  ui_story_5071_50710402_6_dialog_content = "Acabas de notar eso hace un segundo.",
  ui_story_5071_50710402_7_dialog_content = "Sí... Pero tu nombre estaba inscrito en la ropa que llevabas cuando desapareciste: \"Sheol\".",
  ui_story_5071_50710402_8_dialog_content = "A juzgar por tu reacción, parece que eso es lo que otros también te llaman.",
  ui_story_5071_50710402_9_dialog_content = "Dime, ¿de quién soy hija yo?",
  ui_story_5071_50710402_10_dialog_content = "Un viejo amigo mío llamado Dama Melissa.",
  ui_story_5071_50710402_11_dialog_content = "Si realmente era mi madre, ¿por qué no vino por mí misma?",
  ui_story_5071_50710402_12_dialog_content = "Porque ella... Murió de una enfermedad hace mucho tiempo.",
  ui_story_5071_50710402_13_dialog_content = "Qué conveniente.",
  ui_story_5071_50710402_14_dialog_content = "...",
  ui_story_5071_50710402_15_dialog_content = "He estado llevando esto todo el tiempo, con la esperanza de dártelo algún día.",
  ui_story_5071_50710402_16_dialog_content = "Es... ¿oro puro?",
  ui_story_5071_50710402_17_dialog_content = "Te lo dejó tu difunta madre. Si puedes usar Luminatics, entonces deberías saber cómo manejarlo.",
  ui_story_5071_50710402_18_dialog_content = "¿Y simplemente me lo vas a dar?",
  ui_story_5071_50710402_19_dialog_content = "Cuando hayas tenido suficiente tiempo para considerar las cosas, ven a buscarme en Umbraton.",
  ui_story_5071_50710402_20_dialog_content = "Puedes contar con que yo tome esto, pero no necesariamente con que vaya a verte.",
  ui_story_5071_50710402_21_dialog_content = "Estoy seguro de que lo harás.",
  ui_story_5071_50710402_22_dialog_content = "Qué tipo tan extraño.",
  ui_story_5071_50710402_23_dialog_content = "¿Pero realmente existe algo como un almuerzo gratis?",
  ui_story_5071_50710402_24_dialog_content = "<color=#e8d9bb>¡Toc, toc, toc. </color>",
  ui_story_5071_50710402_25_dialog_content = "Ingresar.",
  ui_story_5071_50710402_26_dialog_content = "<color=#e8d9bb>*Pasos*</color>",
  ui_story_5071_50710402_27_dialog_content = "¿Sheol?",
  ui_story_5071_50710402_28_dialog_content = "Jajaja, ¿no dije que vendrías a verme algún día? Aunque por lo que escucho, has estado en Umbraton durante bastante tiempo. ¿Te has adaptado a la vida en esta ciudad?",
  ui_story_5071_50710402_29_dialog_content = "<color=#e8d9bb>Bofetada...</color>",
  ui_story_5071_50710402_30_dialog_content = "Por favor, echa un vistazo.",
  ui_story_5071_50710402_31_dialog_content = "¿Mmm?",
  ui_story_5071_50710402_32_dialog_content = "Veo que la gran Pandilla Istvan ahora está incursionando en las mercancías.",
  ui_story_5071_50710402_33_dialog_content = "El problema es que no tienes idea de la calidad de lo que estás comprando.",
  ui_story_5071_50710402_34_dialog_content = "El Gremio Firefox que te abastece tuvo la audacia de defraudar a los nobles en Lumopolis... En cuanto a los detalles específicos, están resumidos en este archivo.",
  ui_story_5071_50710402_35_dialog_content = "Incluso yo pude rastrearlo bastante fácilmente, así que imagino que los Guardias Lumo lo sabían.",
  ui_story_5071_50710402_36_dialog_content = "Solo es cuestión de días antes de que ese proveedor \"confiable\" tuyo sea arrojado a pudrirse en la cárcel.",
  ui_story_5071_50710402_37_dialog_content = "Cuando Firefox ya no exista, no solo perderás a tu proveedor, sino que también tendrás que lidiar con clientes enfadados.",
  ui_story_5071_50710402_38_dialog_content = "¿Es por esto que viniste aquí hoy?",
  ui_story_5071_50710402_39_dialog_content = "No nos pongamos tensos, Señor Sombrío.",
  ui_story_5071_50710402_40_dialog_content = "No estoy aquí para patearte cuando estás caído, sino para ofrecer un ganar-ganar.",
  ui_story_5071_50710402_41_dialog_content = "Si no te importa que lo diga, ustedes gángsters necesitan ayuda profesional en negocios.",
  ui_story_5071_50710402_42_dialog_content = "Por supuesto, tengo una oferta especial exclusiva con tu nombre en ella.",
  ui_story_5071_50710402_43_dialog_content = "(Entiendo. Ella no tenía intención de venir a mí en busca de ayuda, e incluso comenzó un pequeño gremio con sus propias manos aquí en Umbraton...)",
  ui_story_5071_50710402_44_dialog_content = "(No quiere que subestime sus habilidades, así que vino a mí con una propuesta de negocio que nos pondría en igualdad de condiciones. ¿Es eso?)",
  ui_story_5071_50710402_45_dialog_content = "¡Jajajaja! Muy bien entonces, dejaré este envío en tus capaces manos, Señora Sheol.",
  ui_story_5071_50710402_46_dialog_content = "Pero ahora te debo un favor. Dime qué deseas y prometo hacértelo realidad.",
  ui_story_5071_50710402_47_dialog_content = "Siempre creo que el único que puede cumplir mi propio deseo soy yo mismo.",
  ui_story_5071_50710402_48_dialog_content = "Entiendo, entonces seguiré guardando este deseo para ti. Si alguna vez cambias de opinión, todo lo que tienes que hacer es decirlo.",
  ui_story_5071_50710402_49_dialog_content = "Agradezco la oferta, pero espero nunca tener que hacerla efectiva.",
  ui_story_5071_50710402_50_dialog_content = "Incluso yo estoy sorprendido por tu parecido con tu madre, y no solo en términos de apariencia...",
  ui_story_5071_50710402_51_dialog_content = "¿Cómo... era ella?",
  ui_story_5071_50710402_52_dialog_content = "Al igual que tú, ella era una líder de gremio decidida y prudente. No tengo más que el máximo respeto por ella.",
  ui_story_5071_50710402_53_dialog_content = "Desafortunadamente, ninguna cantidad de elogios podría coalescer en una imagen clara. Todavía no puedo entenderla...",
  ui_story_5071_50710402_54_dialog_content = "¡Perdona la intrusión, Señor de las Sombras!",
  ui_story_5071_50710402_55_dialog_content = "Como predijiste, ¡el Gremio Firefox no estaba dispuesto a pagar por nuestras mercancías desde el principio! ¡Es toda nuestra culpa por no investigarlos más a fondo!",
  ui_story_5071_50710402_56_dialog_content = "Su presidente acaba de ser arrestado por las autoridades de Lumopolis... Lo que significa que probablemente perdamos nuestra inversión en este trato.",
  ui_story_5071_50710402_57_dialog_content = "Nuestra gente ha comenzado a contactar a otros gremios con solicitudes urgentes. ¿Deberíamos preparar contratos para ellos?",
  ui_story_5071_50710402_58_dialog_content = "No. Ya he encontrado un socio comercial perfectamente adecuado para el trabajo. Diles que esperen más instrucciones.",
  ui_story_5071_50710402_59_dialog_content = "¡Si mi señor!",
  ui_story_5071_50710402_60_dialog_content = "Espera, ¿el plan tonto fue culpa de ustedes? Pensándolo bien, eso significa que sabían lo que Firefox estaba haciendo todo el tiempo...",
  ui_story_5071_50710402_61_dialog_content = "Ya no es necesario detenernos en el pasado. Deberíamos estar celebrando nuestra nueva colaboración comercial, ¿no crees?",
  ui_story_5071_50710402_62_dialog_content = "Pero si te encontraron otro gremio, ¿por qué me elegiste a mí? ¿Es por mi madre...",
  ui_story_5071_50710402_63_dialog_content = "Porque tú, Lady Sheol, eres mucho más prudente y cooperativa que otros líderes de gremios que afirman poder liderar el Gremio Umbraton.",
  ui_story_5071_50710402_64_dialog_content = "La perspectiva de trabajar con alguien como tú me trae mucha alegría.",
  ui_story_5071_50710402_65_dialog_content = "Entonces, por una feliz asociación.",
  ui_story_5071_50710402_66_dialog_content = "Ahora bien, ¿cómo debo dirigirme a su gremio?",
  ui_story_5071_50710402_67_dialog_content = "El Gremio de Explorador Nublar.",
  ui_story_5071_50710402_68_dialog_content = "... Parece que también anhelas esa isla flotante en el cielo.",
  ui_story_5071_50710402_69_dialog_content = "¿Lumopolis? Esa es realmente una isla atractiva, pero prefiero una versión más libre.",
  ui_story_5071_50710402_70_dialog_content = "Vagar por cualquier lugar, comerciar libremente... ¿Qué, no crees que eso sea realista?",
  ui_story_5071_50710402_71_dialog_content = "Ni siquiera en lo más mínimo. Todo lo que deseo decir—",
  ui_story_5071_50710402_72_dialog_content = "Es que espero con interés trabajar contigo.",
  ui_story_5071_50710402_73_dialog_content = "(Accidentalmente eché un vistazo a los recuerdos de la Señorita Sheol. Nunca la había visto tan emocional antes...)",
  ui_story_5071_50710402_74_dialog_content = "¿Por qué estás parado ahí, querido PlayerName?",
  ui_story_5071_50710402_75_dialog_content = "O...",
  ui_story_5071_50710402_76_dialog_content = "¿Has desarrollado un interés repentino en mi pasado?",
  ui_story_5071_50710402_77_dialog_content = "Yo...",
  ui_story_5071_50710402_78_dialog_content = "Puedo ver por qué estás tan sorprendido. ¡Esta es también mi primera vez viendo a la Señora Sheol tan feliz!",
  ui_story_5071_50710402_79_dialog_content = "Ya que te gusta tanto la señorita Yvonne, Vergil...",
  ui_story_5071_50710402_80_dialog_content = "¿Por qué no invierto dinero en una editorial y la contrato en exclusiva?",
  ui_story_5071_50710402_81_dialog_content = "¿Eh? ¿E-Está realmente bien?",
  ui_story_5071_50710402_82_dialog_content = "Bajo la condición de que primero tienes que escribirme un libro sobre antigüedades.",
  ui_story_5071_50710402_83_dialog_content = "Yo-Yo... Haré lo mejor que pueda...",
  ui_story_5071_50710402_84_dialog_content = "¿Eh? Virgilio, tú en realidad—",
  ui_story_5071_50710402_85_dialog_content = "Vergil puede ser un niño, pero es un experto en antigüedades de verdad que puede tasar cualquier cosa!",
  ui_story_5071_50710402_86_dialog_content = "N-No es realmente tan impresionante...",
  ui_story_5071_50710402_87_dialog_content = "¡Momento perfecto! Recogí un montón de papeles de manuscrito antes. ¿Podrías decirnos a quién pertenecen, Vergil?",
  ui_story_5071_50710402_88_dialog_content = "Este es el tipo de papel de escritura que todos usan hoy en día—",
  ui_story_5071_50710402_89_dialog_content = "¿Eh? ¡Espera un minuto! Esto es...",
  ui_story_5071_50710501_1_dialog_content = "¿Estás seguro de que este es el manuscrito de la señorita Yvonne?",
  ui_story_5071_50710501_2_dialog_content = "¡Lo es! Hasta donde yo sé, esta es una historia completamente nueva que nunca ha sido publicada antes!",
  ui_story_5071_50710501_3_dialog_content = "Pero estas páginas se ven tan viejas. ¿Por qué aún no se ha publicado?",
  ui_story_5071_50710501_4_dialog_content = "Hay muchas razones por las que los autores no pueden publicar su trabajo a tiempo. Además, echa un vistazo a las últimas páginas de este manuscrito: ¡todavía son bastante nuevas!",
  ui_story_5071_50710501_5_dialog_content = "¡Este puede ser un manuscrito perdido para la nueva historia de la Sra. Yvonne! Ahhh, no puedo esperar para leerlo...",
  ui_story_5071_50710501_6_dialog_content = "¿No crees que deberíamos devolverlo primero a su legítimo dueño, Vergil?",
  ui_story_5071_50710501_7_dialog_content = "¡Ahhh, solo la primera línea de este manuscrito es suficiente para traer lágrimas a mis ojos! La última vez que leí una de las obras de la Sra. Yvonne, no era más alto que un taburete de la antigua Longzhou!",
  ui_story_5071_50710501_8_dialog_content = "¿Es realmente tan bueno? Déjame echar un vistazo...",
  ui_story_5071_50710501_9_dialog_content = "Fuera de las puertas de un puesto de Lumopolis hay un camino pavimentado con innumerables ladrillos verdes. En un campo abierto, se puede ver un montón de piedras blancas.",
  ui_story_5071_50710501_10_dialog_content = "Los niños locales que vienen aquí con frecuencia para jugar al escondite a menudo se enfrentan a un transeúnte entrometido.",
  ui_story_5071_50710501_11_dialog_content = "\"¿Qué creen que están haciendo, pequeños monstruos? ¿No saben lo que solía ser este lugar?!\"",
  ui_story_5071_50710501_12_dialog_content = "Con su barriga sobresaliendo, un niño responde sin miedo, \"¿No se llamaba 'El Pozo'?\"",
  ui_story_5071_50710501_13_dialog_content = "\"Sí, y fue muy diferente a los clubes de lucha en la ciudad. ¿Tienes alguna idea de cuántas personas han muerto aquí?\"",
  ui_story_5071_50710501_14_dialog_content = "Al ver a los niños caer repentinamente en silencio, el entrometido se emocionó aún más. \"Cien personas entrarían, ¡pero solo una sobreviviría!\"",
  ui_story_5071_50710501_15_dialog_content = "Esos entrometidos tienen razón. El Pozo siempre ha sido un lugar donde los nobles se entretienen con las muertes de los demás.",
  ui_story_5071_50710501_16_dialog_content = "Atan a todo tipo de criminales con cadenas de hierro tan gruesas como un tazón, como si fueran animales, y los arrojan al Pozo para luchar.",
  ui_story_5071_50710501_17_dialog_content = "Por supuesto, hay quienes entran valientemente al Pozo de forma voluntaria solo para ganar un bocado para comer o para ser notados por un noble.",
  ui_story_5071_50710501_18_dialog_content = "Sin embargo, también hay quienes han sido engañados para entrar en The Pit...",
  ui_story_5071_50710501_19_dialog_content = "Si pudiera hacerle saber al Juez de Lumopolis que el Sheriff de Umbraton está confabulado con las pandillas...",
  ui_story_5071_50710501_20_dialog_content = "¡Seguramente se ocuparía de la escoria que solo le importaba ganar dinero a costa de las vidas de los demás!",
  ui_story_5071_50710501_21_dialog_content = "¿Pero está realmente aquí el Juez?",
  ui_story_5071_50710501_22_dialog_content = "No, no—",
  ui_story_5071_50710501_23_dialog_content = "¡Detente!",
  ui_story_5071_50710501_24_dialog_content = "¡Por favor, abran paso para que pueda pasar!",
  ui_story_5071_50710501_25_dialog_content = "Pero los guardias te buscan. ¿Eres un criminal?",
  ui_story_5071_50710501_26_dialog_content = "No, yo no soy... Pareces que también eres de Umbraton, ¡así que por favor ayúdame!",
  ui_story_5071_50710501_27_dialog_content = "Vine a presentar una demanda en el Lumo Hall of Justice sobre los tratos sucios que algunos nobles están haciendo en Umbraton, solo para que ellos me persigan a cambio.",
  ui_story_5071_50710501_28_dialog_content = "No me importaba ir a la cárcel, ¡pero querían echarme en El Pozo! Querían matarme...",
  ui_story_5071_50710501_29_dialog_content = "¡No puedo creer que me hayas ganado de mano! ¿Entonces el Salón de Justicia también está corrupto? ¿O tal vez todo Lumopolis...",
  ui_story_5071_50710501_30_dialog_content = "¡¿A dónde crees que vas?!",
  ui_story_5071_50710501_31_dialog_content = "¡Están aquí! Supongo que estoy acabado.",
  ui_story_5071_50710501_32_dialog_content = "No hables demasiado pronto.",
  ui_story_5071_50710501_33_dialog_content = "¡Oye! Sí, te estoy hablando a ti. ¡Muévete del camino!",
  ui_story_5071_50710501_34_dialog_content = "Este tipo no puede pelear ni un frijol, entonces, ¿qué ha hecho tan mal para enviarlo a su muerte?",
  ui_story_5071_50710501_35_dialog_content = "No tiene que luchar. Solo necesitamos asegurarnos de que haya suficientes personas. ¿Tomarás su lugar?",
  ui_story_5071_50710501_36_dialog_content = "¡Qué absurdo! No planean dejarme con vida.",
  ui_story_5071_50710501_37_dialog_content = "Olvídalo. Esto es el final. De todos modos, a mi padre nunca le caí bien, ni fuera de la casa...",
  ui_story_5071_50710501_38_dialog_content = "Tomaré su lugar.",
  ui_story_5071_50710501_39_dialog_content = "¿Qué? ¿Ni siquiera me conoces y morirías por mí?",
  ui_story_5071_50710501_40_dialog_content = "Sé lo que estoy haciendo.",
  ui_story_5071_50710501_41_dialog_content = "Pareces muy educado y sabes mejor que yo cómo salvar a Umbraton. Si no puedo volver, prométeme...",
  ui_story_5071_50710501_42_dialog_content = "Mantén a Umbraton vivo.",
  ui_story_5071_50710501_43_dialog_content = "...",
  ui_story_5071_50710501_44_dialog_content = "¡Parece que un guerrero más se ha ofrecido voluntariamente para luchar por nosotros hoy!",
  ui_story_5071_50710501_45_dialog_content = "¡Hoy es tu día de suerte, luchadores! Si alguno de ustedes puede vencerlo y vivir para contarlo, ¡uno de estos nobles caballeros ha acordado duplicar la recompensa!",
  ui_story_5071_50710501_46_dialog_content = "Ajajajaja—",
  ui_story_5071_50710501_47_dialog_content = "¡Agarra a ese monstruo con cuernos!",
  ui_story_5071_50710501_48_dialog_content = "...",
  ui_story_5071_50710501_49_dialog_content = "¡Mátalo—!",
  ui_story_5071_50710501_50_dialog_content = "Las personas que han sido arrojadas al Pozo ya han vendido sus almas a los demonios.",
  ui_story_5071_50710501_51_dialog_content = "¡Consíguelos! ¡Apresúrate, tú inútiles tontos!",
  ui_story_5071_50710501_52_dialog_content = "Está claro que solo están siendo utilizados por esos nobles sedientos de sangre...",
  ui_story_5071_50710501_53_dialog_content = "¡Mátalo! Si lo haces, dividiremos el dinero del premio.",
  ui_story_5071_50710501_54_dialog_content = "Pero solo uno de ellos puede vivir, ¿verdad?",
  ui_story_5071_50710501_55_dialog_content = "¡No me importa siempre y cuando no sea ese demonio con cuernos!",
  ui_story_5071_50710501_56_dialog_content = "Entonces no perdamos más tiempo. ¡Ven a mí!",
  ui_story_5071_50710502_1_dialog_content = "Cada golpe salvaje fue recibido con rugidos y gritos de la multitud. Uno tras otro, los guerreros en El Pozo comenzaron a caer.",
  ui_story_5071_50710502_2_dialog_content = "Algunos espectadores se cubrieron las caras o se retiraron a la fila más lejana en las gradas, temiendo que el próximo puño azul en llamas los alcanzara.",
  ui_story_5071_50710502_3_dialog_content = "El joven que era tan fornido como una bestia y tan feroz como un demonio finalmente se detuvo después de derribar a sus últimos oponentes. Después de eso, los espectadores finalmente suspiraron aliviados.",
  ui_story_5071_50710502_4_dialog_content = "¡Ganó! ¡Realmente ganó aunque todos en el Pozo lo estaban atacando!",
  ui_story_5071_50710502_5_dialog_content = "Sus heridas son bastante graves. Esas personas escondieron armas e hicieron muchos cortes en su cuerpo...",
  ui_story_5071_50710502_6_dialog_content = "Conté, ¡él recibió más de mil cortes!",
  ui_story_5071_50710502_7_dialog_content = "¿Mil heridas?!",
  ui_story_5071_50710502_8_dialog_content = "...",
  ui_story_5071_50710502_9_dialog_content = "¿Podemos irnos ahora?",
  ui_story_5071_50710502_10_dialog_content = "La persona a la que protegiste puede irse. En cuanto a ti...",
  ui_story_5071_50710502_11_dialog_content = "Escucha...",
  ui_story_5071_50710502_12_dialog_content = "¿Estás escuchando?",
  ui_story_5071_50710502_13_dialog_content = "¡Ahhh! ¡¿Q-Qué...?!",
  ui_story_5071_50710502_14_dialog_content = "Están tan inmersos, que se han olvidado completamente de mí.",
  ui_story_5071_50710502_15_dialog_content = "Por mucho que me encantaría unirme a ti, tengo asuntos urgentes que atender.",
  ui_story_5071_50710502_16_dialog_content = "Aun así, deberías devolvérselo a la señorita Yvonne tan pronto como puedas.",
  ui_story_5071_50710502_17_dialog_content = "Oh, y Vergil, no pierdas tu tarea de subasta.",
  ui_story_5071_50710502_18_dialog_content = "¡No lo haré!",
  ui_story_5071_50710502_19_dialog_content = "La Sra. Yvonne debería estar reuniéndose con el Señor de las Sombras en este momento. ¿Por qué no vamos a buscarla allí?",
  ui_story_5071_50710502_20_dialog_content = "P-Pero estaba llegando a la parte emocionante...",
  ui_story_5071_50710502_21_dialog_content = "¿P-Puedo leer un poco más?",
  ui_story_5071_50710502_22_dialog_content = "E-Ejem, bien... Pero sólo un poco más, ¿okay?",
  ui_story_5071_50710502_23_dialog_content = "¡Vale! ¡Un poco más no hará daño!",
  ui_story_5071_50710601_1_dialog_content = "<color=#e8d9bb>En la suite de lujo del Dirigible Explorador Nublar</color>",
  ui_story_5071_50710601_2_dialog_content = "Gracias por concederme una audiencia, honorable Señor de las Sombras. Te ofrezco el máximo respeto en nombre del Gremio Continental.",
  ui_story_5071_50710601_3_dialog_content = "Eres la Sra. Hanstie, la enigmática líder del Gremio Continental? Recuerdo que ese no era tu apellido.",
  ui_story_5071_50710601_4_dialog_content = "Ya somos dos.",
  ui_story_5071_50710601_5_dialog_content = "... Has cambiado mucho.",
  ui_story_5071_50710601_6_dialog_content = "¿Lo crees? Oh, ¿te refieres a mi pierna?",
  ui_story_5071_50710601_7_dialog_content = "Aunque gasté mucho dinero en escapar cuando el Darkover abrumó a Umbraton, aún me encontré con Eclipsites en el camino...",
  ui_story_5071_50710601_8_dialog_content = "Pero está bien, ya que de otra manera no me daría cuenta de los beneficios de una pierna cibernética.",
  ui_story_5071_50710601_9_dialog_content = "Jaja, eres diferente de hecho, más optimista y resistente que antes.",
  ui_story_5071_50710601_10_dialog_content = "Está destinado a suceder, dado por todo lo que pasé.",
  ui_story_5071_50710601_11_dialog_content = "Tu gremio también es bastante impresionante e inconvencional en cómo a menudo realiza inversiones arriesgadas prohibidas por el Gremio Umbraton.",
  ui_story_5071_50710601_12_dialog_content = "Jeje, veo que la sombra ha estado observándome.",
  ui_story_5071_50710601_13_dialog_content = "Pero ciertamente no me estás tratando como a un viejo amigo. Aquí estoy visitándote con buenas intenciones, solo para que intentes rebajarme.",
  ui_story_5071_50710601_14_dialog_content = "Somos viejos amigos, es por eso que quiero lo mejor para ti.",
  ui_story_5071_50710601_15_dialog_content = "Aunque no lo entiendo del todo, ¿no es <color=#FFB400>tu Umbraton</color> un pueblo libre y tolerante?",
  ui_story_5071_50710601_16_dialog_content = "Obviamente puedes traer grandes casinos para generar más ganancias para Umbraton e incluso pagar fácilmente el considerable \"impuesto a la propiedad\" a Lumopolis, ¿entonces por qué no lo haces?",
  ui_story_5071_50710601_17_dialog_content = "No comenzaste adorando el dinero. En aquel entonces, estabas interesado en las artes y la literatura, siempre con un bolígrafo o pincel en la mano—",
  ui_story_5071_50710601_18_dialog_content = "No soy el único que ha cambiado.",
  ui_story_5071_50710601_19_dialog_content = "No puedo creer que ese tipo pobre que conocía pudiera agarrar el Bastón del Pastor y convertirse en <color=#FFB400>Istvan</color>.",
  ui_story_5071_50710601_20_dialog_content = "...",
  ui_story_5071_50710601_21_dialog_content = "Tienes razón. Nada permanece igual para siempre. Umbraton está pasando por una reforma ahora.",
  ui_story_5071_50710601_22_dialog_content = "Este no es tu Umbraton ni el mío.",
  ui_story_5071_50710601_23_dialog_content = "Aquí, puedes comerciar libremente, excepto por la variedad subterránea y criminal, ese también era el sueño de <color=#FFB400>Valon</color>.",
  ui_story_5071_50710601_24_dialog_content = "Acaso...",
  ui_story_5071_50710601_25_dialog_content = "Qué trágico... ¿Por qué tiene que pasarle esto al protagonista?",
  ui_story_5071_50710601_26_dialog_content = "Entonces, ¿incluso después de recibir una audiencia con el Señor de la Ciudad, todavía fue incriminado por los nobles y arrojado a la cárcel?",
  ui_story_5071_50710601_27_dialog_content = "El Señor de la Ciudad de Lumopolis nunca quiso escuchar los pensamientos del protagonista sobre Umbraton. Solo veía la ciudad como una mascota que podía luchar... Una vez que no le servía para nada, perdió el interés.",
  ui_story_5071_50710601_28_dialog_content = "La historia de este libro es mucho más complicada que las anteriores... Me pregunto qué hará el protagonista una vez que salga de la cárcel?",
  ui_story_5071_50710601_29_dialog_content = "¿Quizás deberíamos... leer un poco más?",
  ui_story_5071_50710601_30_dialog_content = "¡Sí, sólo un poco más!",
  ui_story_5071_50710601_31_dialog_content = "El aire en el cementerio se sentía aún más frío que en la ciudad, posiblemente porque había pasado mucho tiempo de pie allí.",
  ui_story_5071_50710601_32_dialog_content = "Cuando dejó su hogar, las únicas palabras que dijo a sus padres fueron \"Me voy ahora\". Ahora, después de tantos años, no pudo reunir ni siquiera la frase más simple: \"He vuelto\".",
  ui_story_5071_50710601_33_dialog_content = "Los pasos se acercaron lentamente a él desde detrás de su espalda. \"Declara tu propósito\", dijo fríamente al visitante sin volverse.",
  ui_story_5071_50710601_34_dialog_content = "Pronto el visitante respondió: \"Kade... Por fin has vuelto.\"",
  ui_story_5071_50710601_35_dialog_content = "Kade giró su cabeza hacia la persona, un rostro vagamente familiar. \"¿Te conozco?\"",
  ui_story_5071_50710601_36_dialog_content = "Salvaste a una cierta persona en el Pozo hace todos esos años... Y esa persona era yo.",
  ui_story_5071_50710601_37_dialog_content = "Sufriste muchos años por mi culpa. No puedo simplemente darte la espalda.",
  ui_story_5071_50710601_38_dialog_content = "Si no tienes un lugar al que regresar, ¿quizás puedas venir a casa conmigo? Te trataré como a mi propio hermano.",
  ui_story_5071_50710601_39_dialog_content = "Pero ni siquiera sé tu nombre...",
  ui_story_5071_50710601_40_dialog_content = "Valon. Solo llámame Valon.",
  ui_story_5071_50710601_41_dialog_content = "Pronto, los dos jóvenes descubrieron un interés común...",
  ui_story_5071_50710601_42_dialog_content = "... He estado practicando desde que volví del Pozo.",
  ui_story_5071_50710601_43_dialog_content = "¿Practicando cómo jugar al ajedrez?",
  ui_story_5071_50710601_44_dialog_content = "Luminatics. Espero ser tan poderoso como tú algún día, para poder dominar también el campo de batalla.",
  ui_story_5071_50710601_45_dialog_content = "Si ese es el caso, entonces quiero ser tan hábil como tú cuando se trata de ajedrez.",
  ui_story_5071_50710601_46_dialog_content = "Jaja, nunca supe que también te gustaba el ajedrez. ¿Quién te enseñó a jugar?",
  ui_story_5071_50710601_47_dialog_content = "Mi padre...",
  ui_story_5071_50710601_48_dialog_content = "Lo siento, no debería haber preguntado... Pero de ahora en adelante, mi padre también puede ser tu padre!",
  ui_story_5071_50710601_49_dialog_content = "¡Estoy seguro de que a papá le gustas lo suficiente como para adoptarte! ¡De esa manera, podemos convertirnos en verdaderos hermanos!",
  ui_story_5071_50710601_50_dialog_content = "...",
  ui_story_5071_50710601_51_dialog_content = "Así que por favor no te niegues, al igual que yo no me negué cuando tomaste mi lugar en la Arena Mortal.",
  ui_story_5071_50710601_52_dialog_content = "Solo estoy preocupado. Nada sobre Umbraton ha cambiado desde la última vez que estuve aquí. Nada en absoluto.",
  ui_story_5071_50710601_53_dialog_content = "... También he pensado en eso. Si Umbraton sigue esperando la ayuda de Lumopolis, nunca cambiará.",
  ui_story_5071_50710601_54_dialog_content = "Necesitamos confiar en nuestra propia fuerza si queremos exterminar los insectos chupasangres que están drenando la vida de nuestra ciudad.",
  ui_story_5071_50710601_55_dialog_content = "Me pregunto quién eligió el nombre \"Umbraton\" para este lugar. ¿Quiénes eran ellos para decidir que siempre deberíamos vivir en las sombras? ¡El futuro es nuestro para decidir!",
  ui_story_5071_50710601_56_dialog_content = "El futuro... Sí, el futuro de este pueblo debería ser uno libre y unificado, un futuro donde nadie pueda controlarnos más!",
  ui_story_5071_50710601_57_dialog_content = "Deseo lo mismo, pero liberarnos de la oscuridad de nuestro pasado no es algo que se pueda hacer de la noche a la mañana...",
  ui_story_5071_50710601_58_dialog_content = "Quizás tengamos que aprender a vivir en paz con ellos, incluso llegar a ser parte de ellos durante bastante tiempo...",
  ui_story_5071_50710601_59_dialog_content = "No. Necesitamos deshacernos de su nefasta influencia, ¡y tiene que ser pronto! Sin compromisos.",
  ui_story_5071_50710601_60_dialog_content = "¿Ah?",
  ui_story_5071_50710601_61_dialog_content = "¿Qué es?",
  ui_story_5071_50710601_62_dialog_content = "Alguien está escuchando en la puerta... ¿Deberíamos hacer algo al respecto?",
  ui_story_5071_50710601_63_dialog_content = "Ah... Esa es simplemente <color=#FFB400>Ava</color>, la hija de uno de los amigos de mi papá. No te preocupes, ella también es mi amiga.",
  ui_story_5071_50710601_64_dialog_content = "¡No somos solo amigos, tú sabes!",
  ui_story_5071_50710601_65_dialog_content = "Kade siempre estaba impresionado por la iniciativa de Valon. Un día, Valon decidió acercarse a su padre, el líder de un gremio de comerciantes, en busca de apoyo...",
  ui_story_5071_50710601_66_dialog_content = "¡Nunca!",
  ui_story_5071_50710601_67_dialog_content = "¿Pero por qué no? ¡Estamos tratando de hacer lo correcto!",
  ui_story_5071_50710601_68_dialog_content = "Esas pandillas sedientas de sangre y las gremios que no se comportan mejor que ellas... ¡Son un cáncer para todo Umbraton!",
  ui_story_5071_50710601_69_dialog_content = "¡Si actuamos rápido y con decisión, podemos eliminarlos a todos uno por uno!",
  ui_story_5071_50710601_70_dialog_content = "Si pudieran ser erradicados tan fácilmente, alguien lo habría hecho hace mucho tiempo. A pesar de su naturaleza caótica, Umbraton mantiene un cierto equilibrio que no debe ser derrocado.",
  ui_story_5071_50710601_71_dialog_content = "¿Cuántas veces te he advertido sobre ser tan ingenuo? ¿No aprendiste nada de tu última lección?",
  ui_story_5071_50710601_72_dialog_content = "Solo sobreviviste porque Kade estaba allí, ¿pero qué pasará la próxima vez?",
  ui_story_5071_50710601_73_dialog_content = "Tú y Kade no serán los únicos que sufrirán por tus errores. ¡Nuestra familia entera estará en riesgo!",
  ui_story_5071_50710601_74_dialog_content = "¡Padre!",
  ui_story_5071_50710601_75_dialog_content = "Valon y su padre siempre habían estado en constante desacuerdo. Afortunadamente, ahora Kade estaba allí para apoyarlo...",
  ui_story_5071_50710601_76_dialog_content = "Papá ni siquiera está dispuesto a escuchar mi estrategia para el futuro de Umbraton.",
  ui_story_5071_50710601_77_dialog_content = "Pero lo estoy. Adelante, cuéntame.",
  ui_story_5071_50710601_78_dialog_content = "Dime, ¿sabes por qué nuestros gremios sufren tanto a manos de las pandillas estos días? Es porque todos solo están cuidando de sí mismos.",
  ui_story_5071_50710601_79_dialog_content = "Creo que cada gremio debería unirse y formar un solo cuerpo donde puedan disfrutar de beneficios y protecciones compartidos. Podemos llamarlo—",
  ui_story_5071_50710601_80_dialog_content = "¿El Gremio Umbraton?",
  ui_story_5071_50710601_81_dialog_content = "¡Sí, lo llamaremos el Gremio Umbraton! ¡Solo cuando los intereses de todos sean compartidos podemos ayudarnos mutuamente a derrotar al enemigo común!",
  ui_story_5071_50710601_82_dialog_content = "Pandillas y gremios amigables con las pandillas, mercenarios depredadores... ¡Incluso Lumopolis no tendría oportunidad!",
  ui_story_5071_50710601_83_dialog_content = "Una vez que eliminemos estas plagas de Umbraton, se convertirá en un paraíso puro para todo tipo de negocios.",
  ui_story_5071_50710601_84_dialog_content = "Y entonces... ¡Guiaré mi propio gremio a tierras aún más lejanas!",
  ui_story_5071_50710601_85_dialog_content = "¿Y cómo harías eso?",
  ui_story_5071_50710601_86_dialog_content = "Con vehículos, supongo... ¡O espera, aún mejor! ¡Compraré un Colossus de Eraveil y estableceré mi gremio en la cima de él!",
  ui_story_5071_50710601_87_dialog_content = "¡Juntos, navegaremos por los cielos con el viento en nuestras caras, viajando y comerciando libremente por todo el continente!",
  ui_story_5071_50710601_88_dialog_content = "Mi gremio no discrimina en base a la riqueza o el estatus. Cualquiera puede unirse y prosperar, siempre y cuando estén dispuestos a trabajar duro para ello!",
  ui_story_5071_50710601_89_dialog_content = "...",
  ui_story_5071_50710601_90_dialog_content = "¿Qué pasa, Kade? ¿Dije algo malo?",
  ui_story_5071_50710601_91_dialog_content = "Para nada, Valon, es un sueño hermoso. Quizás la única forma de liberarse realmente de las sombras... es volar hacia el cielo.",
  ui_story_5071_50710601_92_dialog_content = "Haré lo que sea necesario para hacer realidad ese sueño.",
  ui_story_5071_50710601_93_dialog_content = "¡Yo también haré lo mismo!",
  ui_story_5071_50710601_94_dialog_content = "¿Pero pensé que no te importaban los negocios?",
  ui_story_5071_50710601_95_dialog_content = "Hmm... Dibujo bastante bien. ¿Por qué no diseño un hermoso Coloso para tu gremio en su lugar?",
  ui_story_5071_50710601_96_dialog_content = "Jaja, no creo que diseñar el Colossus dependa de nosotros.",
  ui_story_5071_50710601_97_dialog_content = "Lamentablemente, esta atmósfera pacífica no estaba destinada a durar...",
  ui_story_5071_50710601_98_dialog_content = "¿Por qué te ves tan molesto?",
  ui_story_5071_50710601_99_dialog_content = "Papá tuvo una reunión con un socio de negocios hoy y me llevó con él.",
  ui_story_5071_50710601_100_dialog_content = "Eso es algo bueno. Significa que finalmente está dispuesto a enseñarte sobre asuntos del gremio. Esto nos acercará un paso más a la realización de nuestro sueño.",
  ui_story_5071_50710601_101_dialog_content = "T-Tú no entiendes... La persona a la que él me presentó...",
  ui_story_5071_50710601_102_dialog_content = "... era un vendedor de veneno. Si papá se está reuniendo con él, solo puede significar—",
  ui_story_5071_50710601_103_dialog_content = "Mi familia tampoco es inocente, lo que explica por qué papá sigue intentando detenerme.",
  ui_story_5071_50710601_104_dialog_content = "No sé cómo se supone que debo enfrentar a mi padre ahora. ¿Qué debería hacer...",
  ui_story_5071_50710601_X104_dialog_content = "Siempre podemos utilizar los recursos de tu padre para hacer realidad nuestros sueños.",
  ui_story_5071_50710601_105_dialog_content = "¿Usar ese tipo de recurso...? No, debes estar bromeando, Kade...",
  ui_story_5071_50710601_106_dialog_content = "... No me di cuenta de que te sentías de esa manera.",
  ui_story_5071_50710601_107_dialog_content = "Siempre estarás a mi lado pase lo que pase, ¿verdad?",
  ui_story_5071_50710601_108_dialog_content = "...",
  ui_story_5071_50710601_109_dialog_content = "Sigamos jugando. Esta vez puedes ser blanco, y yo seré negro.",
  ui_story_5071_50710601_110_dialog_content = "Lo que Valon no sabía era que Kade ya había hecho el primer movimiento.",
  ui_story_5071_50710601_111_dialog_content = "¡Quema cada gota de veneno!",
  ui_story_5071_50710601_112_dialog_content = "¡Entendido!",
  ui_story_5071_50710601_113_dialog_content = "Ay—",
  ui_story_5071_50710601_114_dialog_content = "¡No te muevas!",
  ui_story_5071_50710601_115_dialog_content = "¿Por qué me haces esto? ¿Cuándo te he hecho algo malo?",
  ui_story_5071_50710601_116_dialog_content = "Si vendieras todo este veneno, no se puede saber cuántas familias perecerían a causa de ello.",
  ui_story_5071_50710601_117_dialog_content = "¡Ja! ¡Ni siquiera el Salón de Justicia de Lumopolis se preocuparía por esto!",
  ui_story_5071_50710601_118_dialog_content = "... ¿Quién eres exactamente?",
  ui_story_5071_50710601_119_dialog_content = "¿Yo? Solo soy... una sombra errante que pasa por la ciudad, eso es todo.",
  ui_story_5071_50710601_120_dialog_content = "No mucho después y para sorpresa de todos, el padre de Valon convenció a Kade para que se convirtiera en su hijo adoptivo. Sin embargo, Valon no estuvo presente durante la ceremonia de juramento de Kade.",
  ui_story_5071_50710601_121_dialog_content = "Kade se negó a mostrar cualquier indicio de preocupación en su rostro. Con sus dos cuernos negros alzados orgullosamente en el aire, hizo sus votos lo suficientemente fuertes para que todos los escucharan—",
  ui_story_5071_50710601_122_dialog_content = "\"... Juro solemnemente que no haré daño a mi propia familia.\"",
  ui_story_5071_50710601_123_dialog_content = "\"Tampoco haré daño a los intereses de mi familia...\"",
  ui_story_5071_50710701_1_dialog_content = "¿Los sueños de Valon? ¿Tienes el descaro de mencionarlo?",
  ui_story_5071_50710701_2_dialog_content = "Tú eres el que lo destruyó todo—",
  ui_story_5071_50710701_3_dialog_content = "Lo siento mucho, Sra. Hanstie...",
  ui_story_5071_50710701_4_dialog_content = "Pero aún te daré un consejo... sobre cómo elegir al socio correcto.",
  ui_story_5071_50710701_5_dialog_content = "Admito que sé muy poco sobre cómo dirigir un negocio.",
  ui_story_5071_50710701_6_dialog_content = "Pero si estás interesado en ganar dinero legalmente en Umbraton, consulta a Lady Sheol.",
  ui_story_5071_50710701_7_dialog_content = "Puedo prometer que haré todo lo que pueda para ayudarte.",
  ui_story_5071_50710701_8_dialog_content = "No necesito tu promesa, así que guárdatela, Señor Sombrío.",
  ui_story_5071_50710701_9_dialog_content = "Creo que tienes una idea equivocada sobre mí.",
  ui_story_5071_50710701_10_dialog_content = "Quizás podamos sentarnos y hablar de los viejos tiempos más tarde cuando tengamos la oportunidad.",
  ui_story_5071_50710701_11_dialog_content = "Señor Sombrío, es hora de la próxima reunión...",
  ui_story_5071_50710701_12_dialog_content = "Entiendo.",
  ui_story_5071_50710701_13_dialog_content = "Estoy muy contento de verte de nuevo, Sra. Hanstie.",
  ui_story_5071_50710701_14_dialog_content = "Espero que seas consciente al tratar con aquellos en las \"sombras\" y evites problemas innecesarios.",
  ui_story_5071_50710701_15_dialog_content = "Gracias por el recordatorio, Señor Sombrío. Sé lo que estoy haciendo.",
  ui_story_5071_50710701_16_dialog_content = "A diferencia de algunas personas que solo hablan todo el tiempo sobre el sueño de cierto otro.",
  ui_story_5071_50710701_17_dialog_content = "Sin medir realmente...",
  ui_story_5071_50710701_18_dialog_content = "¿Cuánto ha hecho él por todo esto todos estos años?",
  ui_story_5071_50710701_19_dialog_content = "...",
  ui_story_5071_50710701_20_dialog_content = "Extraño, ¿dónde fue mi manuscrito...",
  ui_story_5071_50710701_21_dialog_content = "¿Podría haberlo dejado en la habitación?",
  ui_story_5071_50710701_22_dialog_content = "¡Es tu turno, Sra. Yvonne!",
  ui_story_5071_50710701_23_dialog_content = "Sra. Hanstie, por favor sígame.",
  ui_story_5071_50710701_24_dialog_content = "Sí, ya voy... ¿Hmm?",
  ui_story_5071_50710701_25_dialog_content = "Mi dama... Aunque claramente eres aún muy joven, tus ojos ya han contemplado las vicisitudes de la vida.",
  ui_story_5071_50710701_26_dialog_content = "Tu pierna... Mis disculpas, un resultado de mi ocupación, me temo. Perdóname si te he ofendido de alguna manera.",
  ui_story_5071_50710701_27_dialog_content = "Está bien. no me importa",
  ui_story_5071_50710701_28_dialog_content = "Me das la impresión de ser alguien con muchas historias que contar. Me encuentro profundamente curioso por saber más sobre ti.",
  ui_story_5071_50710701_29_dialog_content = "Además... Ese rico aroma de lirios—",
  ui_story_5071_50710701_30_dialog_content = "Me recuerda a una persona en particular. Ella solía usar una fragancia hechizante igual que esta.",
  ui_story_5071_50710701_31_dialog_content = "Jejeje. Estoy muy feliz de oírte decir eso, porque idolatro a la Sra. Mercurio Rojo.",
  ui_story_5071_50710701_32_dialog_content = "Me encanta cómo la retratas: misteriosa, fuerte, desinhibida.",
  ui_story_5071_50710701_33_dialog_content = "Mi admiración por su papel de guardiana silenciosa es la razón por la que amo tanto los lirios.",
  ui_story_5071_50710701_34_dialog_content = "Recuerdos eternos, amor insuperable y bendiciones profundas. Eso es lo que simbolizan los lirios, ¿verdad?",
  ui_story_5071_50710701_35_dialog_content = "Pero no me gusta lo que le sucedió a la Sra. Mercurio Rojo en las secuelas. Ella merecía un final mejor.",
  ui_story_5071_50710701_36_dialog_content = "... ¿Nos hemos visto antes?",
  ui_story_5071_50710701_37_dialog_content = "No me parece.",
  ui_story_5071_50710701_38_dialog_content = "Sra. Yvonne—",
  ui_story_5071_50710701_39_dialog_content = "¿Alguien está llamando mi nombre?",
  ui_story_5071_50710701_40_dialog_content = "Sra. Yvonne, por favor no haga esperar al Señor Sombrío demasiado tiempo.",
  ui_story_5071_50710701_41_dialog_content = "¡Ay! Mis disculpas, estaré allí enseguida.",
  ui_story_5071_50710701_42_dialog_content = "Llegué demasiado tarde y no pude devolverle el manuscrito.",
  ui_story_5071_50710701_43_dialog_content = "¡Los perros guardianes están aquí!",
  ui_story_5071_50710701_44_dialog_content = "¡No escuches a escondidas!",
  ui_story_5071_50710701_45_dialog_content = "¿Podrías ayudarnos a darle este montón de papeles a la Sra. Yvonne?",
  ui_story_5071_50710701_46_dialog_content = "¡Los buenos perros no deben molestar al Señor de las Sombras!",
  ui_story_5071_50710701_47_dialog_content = "¡Qué terco...",
  ui_story_5071_50710701_48_dialog_content = "Supongo que tendré que esperar a que ella salga.",
  ui_story_5071_50710701_49_dialog_content = "¿Deberíamos...",
  ui_story_5071_50710701_X49_dialog_content = "¿Lees solo un poquito más?",
  ui_story_5071_50710701_50_dialog_content = "...",
  ui_story_5071_50710701_51_dialog_content = "Aunque el tablero de ajedrez entre los dos hombres está impecable, un espeso aroma de sangre y batalla se cierne pesadamente en el aire.",
  ui_story_5071_50710701_52_dialog_content = "Valon hace su próximo movimiento con total confianza, y el juego queda decidido. \"Mate\", dice triunfante.",
  ui_story_5071_50710701_53_dialog_content = "\"Has perdido contra mí una vez más\", añade mientras Kade recoge silenciosamente las piezas de ajedrez.",
  ui_story_5071_50710701_54_dialog_content = "Valon nota el lirio en la mano de su amigo y aprovecha la oportunidad para hacerle una pregunta. \"¿Escuché que tu imperio de sombras ha acogido a unas cuantas personas más?\"",
  ui_story_5071_50710701_55_dialog_content = "La gente de Lady Melissa no tenía a dónde ir después de que ella falleció. Simplemente los acogí.",
  ui_story_5071_50710701_56_dialog_content = "¿Por qué no me hablaste de esto antes?",
  ui_story_5071_50710701_57_dialog_content = "No pensé que te interesaría saber.",
  ui_story_5071_50710701_58_dialog_content = "El joven demi-humano continúa reiniciando el tablero de ajedrez. La cara de Valon aún no revela la soledad que siente en su corazón.",
  ui_story_5071_50710701_59_dialog_content = "Juegan al ajedrez en silencio, y parece que las cosas están bien entre ellos.",
  ui_story_5071_50710701_60_dialog_content = "No he tenido la oportunidad de contarte cómo han sido las cosas últimamente. Después de todo este tiempo lejos de casa, finalmente he hecho algún progreso.",
  ui_story_5071_50710701_61_dialog_content = "Logré unificar todos los pequeños negocios en el área circundante, y parece que la gente pobre de aquí realmente nos apoya ahora. A este ritmo, no pasará mucho tiempo antes de que realice mi sueño de tener un gremio poderoso.",
  ui_story_5071_50710701_62_dialog_content = "Felicidades.",
  ui_story_5071_50710701_63_dialog_content = "... ¿Cómo ha estado papá?",
  ui_story_5071_50710701_64_dialog_content = "Está bien, supongo... Pero él todavía te extraña mucho.",
  ui_story_5071_50710701_65_dialog_content = "Jaja, no puedo evitar sentirme un poco extraño cuando pregunto sobre nuestro padre. Supongo que eso te hace un mejor hijo de la familia Istvan que yo.",
  ui_story_5071_50710701_66_dialog_content = "...",
  ui_story_5071_50710701_67_dialog_content = "Ahora me doy cuenta de que no puedo hacerlo solo, Kade... Necesito el Bastón de Pastor de papá.",
  ui_story_5071_50710701_68_dialog_content = "Es un símbolo de autoridad que ha estado en nuestra familia durante generaciones. Con él, finalmente puedo tomar control de los activos de nuestra familia.",
  ui_story_5071_50710701_69_dialog_content = "Solo entonces podré consolidar mi poder y reunir a los jefes de Umbraton... para poder eliminarlos a todos.",
  ui_story_5071_50710701_70_dialog_content = "El joven de cabello azul recoge otra pieza y murmura suavemente, \"¡Mate!\"",
  ui_story_5071_50710701_71_dialog_content = "Kade mira la pizarra durante unos momentos antes de dirigir su mirada hacia arriba. \"Tus métodos son demasiado extremos.\"",
  ui_story_5071_50710701_72_dialog_content = "Por el bien de Umbraton y por el bien de los débiles, no debemos comprometernos. Ni siquiera quedará un grano de polvo.",
  ui_story_5071_50710701_73_dialog_content = "Esto no es justo para esas personas.",
  ui_story_5071_50710701_74_dialog_content = "Recuérdame de nuevo tu promesa, Kade.",
  ui_story_5071_50710701_75_dialog_content = "Dijiste que nunca me traicionarías, ¿verdad? ¿Que siempre me apoyarías y estarías a mi lado?",
  ui_story_5071_50710701_76_dialog_content = "El joven semi-humano duda por un momento mientras el viento aúlla afuera. En esa breve pausa, llega un mensajero con un mensaje ominoso:",
  ui_story_5071_50710701_77_dialog_content = "\"Una gran horda de Eclipsites se ha reunido y está marchando directamente hacia Umbraton.\"",
  ui_story_5071_50710701_78_dialog_content = "En respuesta a la amenaza inminente, Lumopolis ha comenzado a discutir si asistir o no a Umbraton. Algunos creen que esta es una oportunidad para finalmente incorporar la ciudad como parte de la suya.",
  ui_story_5071_50710701_79_dialog_content = "Los jugadores de ajedrez han comenzado a hacer sus movimientos... Supongo que es natural. Hasta que escapemos de la sombra de Lumopolis, este seguirá siendo el destino de nuestro pueblo.",
  ui_story_5071_50710701_80_dialog_content = "Siempre hay una opción alternativa... Si desean negociar, entonces deberíamos acercarnos a ellos.",
  ui_story_5071_50710701_81_dialog_content = "Seré tu torre y continuaré allanando el camino, así que mantén tu confianza, rey.",
  ui_story_5071_50710701_X81_dialog_content = "Un fuerte clac señaló otro nuevo juego.",
  ui_story_5071_50710701_X82_dialog_content = "Era una torre negra, sin embargo, luchó por el rey blanco.",
  ui_story_5071_50710701_82_dialog_content = "¡Eructo! ¿Es esta la habitación de la señorita Goldie?",
  ui_story_5071_50710701_83_dialog_content = "Señorita Goldie, ¿puedo tener su autógrafo?",
  ui_story_5071_50710701_84_dialog_content = "¡Los perros guardianes están aquí!",
  ui_story_5071_50710701_85_dialog_content = "¡Listo para atacar!",
  ui_story_5071_50710701_86_dialog_content = "¡E-E-Espera! Sólo déjanos encargarnos de esto...",
  ui_story_5071_50710701_87_dialog_content = "No podemos causar más problemas de los que ya hemos causado...",
  ui_story_5071_50710701_88_dialog_content = "¿Quién eres?",
  ui_story_5071_50710701_89_dialog_content = "¡Quiero a la señorita Goldie! ¡Señorita Goldie!",
  ui_story_5071_50710702_1_dialog_content = "Estas personas están locas... Trabajar en seguridad aquí es realmente duro...",
  ui_story_5071_50710702_2_dialog_content = "Hay demasiados de ellos. Ya está fuera de nuestras manos, ¡así que sigamos leyendo!",
  ui_story_5071_50710702_3_dialog_content = "Después de muchos años, finalmente encontré la voluntad para continuar escribiendo esta biografía.",
  ui_story_5071_50710702_4_dialog_content = "Al principio, consideré que mi escritura anterior era demasiado halagadora y posiblemente una mala interpretación de la verdad objetiva. Junto con las malas críticas de mis trabajos anteriores, sentí la necesidad de dejar de escribir indefinidamente.",
  ui_story_5071_50710702_5_dialog_content = "Sin embargo, el relato de un amigo sobre el pasado me sumergió en un torrente de inspiración. Considerando la mala recepción de las secuelas de \"La Sra. Mercurio Rojo\", decidí basar la mayoría de mis escritos en la historia original en lugar de en pura ficción.",
  ui_story_5071_50710702_6_dialog_content = "Quizás el final no es lo que mis lectores una vez imaginaron, pero una verdad tan trágica merece ser contada de todos modos—",
  ui_story_5071_50710702_7_dialog_content = "¿Esto se toma directamente de la verdadera historia detrás de la Sra. Mercurio Rojo?",
  ui_story_5071_50710702_8_dialog_content = "¡Ahora estoy aún más emocionado de leerlo!",
  ui_story_5071_50710702_9_dialog_content = "Con una espada como una estrella fugaz, Melissa golpeó con gracia al semi-humano que estaba frente a ella.",
  ui_story_5071_50710702_10_dialog_content = "\"Ríndete\", ordenó fríamente. \"Sé que eres la sombra que ha estado causando estragos en Umbraton.\"",
  ui_story_5071_50710702_11_dialog_content = "¡Por secuestrar y vender niños, no se te mostrará piedad!",
  ui_story_5071_50710702_12_dialog_content = "El hijo de Melissa era como una joya perdida para ella, a la que se había aferrado durante muchos años.",
  ui_story_5071_50710702_13_dialog_content = "Silenciosamente, su oponente paró la lluvia de espadas. Parecía que tenía sus razones para mantener su obstinado silencio también.",
  ui_story_5071_50710702_14_dialog_content = "Aunque Melissa no encontró a su hija perdida aquí, no tenía intención de dejar libre a este secuestrador.",
  ui_story_5071_50710702_15_dialog_content = "Entre las espadas barridas y las sombras, el semi-humano pronto se encontró acorralado en una esquina de la habitación. De repente, se escuchó un alboroto cercano.",
  ui_story_5071_50710702_16_dialog_content = "Papá—",
  ui_story_5071_50710702_17_dialog_content = "¡Cuidado!",
  ui_story_5071_50710702_18_dialog_content = "Una multitud de niños asustados corrió frente a los dos combatientes. Sorprendida, Melissa bajó lentamente su arma.",
  ui_story_5071_50710702_19_dialog_content = "Al darse cuenta de que le habían dado información incorrecta, Melissa guardó su espada con una mirada de decepción en su rostro.",
  ui_story_5071_50710702_20_dialog_content = "\"Yo puedo ayudarte a encontrar a tu hija\", dijo el semi-humano conocido como Kade, después de escuchar su historia.",
  ui_story_5071_50710702_21_dialog_content = "Pero a cambio, por favor mantente al margen de mis asuntos. No hagas nada para impedirme derrotar a las pandillas aquí.",
  ui_story_5071_50710702_22_dialog_content = "Casi todas las personas en este pueblo están corruptas de una forma u otra. ¿Por qué molestarse con todo esto?",
  ui_story_5071_50710702_23_dialog_content = "Para que estos niños puedan crecer sanos y fuertes, incluso si ya no estamos allí para protegerlos.",
  ui_story_5071_50710702_24_dialog_content = "Eso... suena mucho como la historia de la madre de Lady Sheol.",
  ui_story_5071_50710702_25_dialog_content = "Pero ¿no sigue siendo una obra de ficción? Quizás deberíamos... ¿leer un poco más?",
  ui_story_5071_50710702_26_dialog_content = "Cuando Kade vio a Melissa por última vez, ella ya había caído gravemente enferma.",
  ui_story_5071_50710702_27_dialog_content = "Su enfermedad le había robado su belleza y la había dejado en un estado triste y demacrado.",
  ui_story_5071_50710702_28_dialog_content = "Cuando sus ojos finalmente se encontraron una vez más, Kade vio vulnerabilidad en la mirada de esta mujer que una vez fue poderosa.",
  ui_story_5071_50710702_29_dialog_content = "\"Por favor, ayúdame a encontrar a mi hija.\"",
  ui_story_5071_50710702_30_dialog_content = "Fue su última y única petición. A cambio, cerró todos sus negocios que se dedicaban a tratos oscuros.",
  ui_story_5071_50710702_31_dialog_content = "Sé que cumplirás tu promesa.",
  ui_story_5071_50710702_32_dialog_content = "Kade se quedó en silencio frente a ella. Detrás de su espalda, una daga afilada en su mano brillaba con una frialdad pálida.",
  ui_story_5071_50710702_33_dialog_content = "Descansa tranquilo, haré todo lo que pueda por ella.",
  ui_story_5071_50710702_34_dialog_content = "Liberada de todas sus preocupaciones, Melissa soltó un largo suspiro de alivio.",
  ui_story_5071_50710702_35_dialog_content = "\"Una última cosa\", dijo de repente. \"¿Qué estás sosteniendo detrás de tu espalda?\"",
  ui_story_5071_50710702_36_dialog_content = "\"Nada\", dijo Kade mientras se acercaba lentamente a ella, su rostro oculto por las sombras. \"Solo un pequeño regalo de despedida.\"",
  ui_story_5071_50710702_37_dialog_content = "<color=#e8d9bb>El texto termina abruptamente aquí. La tinta aún está fresca, por lo que parece haber sido escrito no hace mucho tiempo.</color>",
  ui_story_5071_50710702_38_dialog_content = "¿Eh? ¿Pero cómo?",
  ui_story_5071_50710702_39_dialog_content = "Bueno.",
  ui_story_5071_50710702_40_dialog_content = "¿Qué está pasando con ustedes dos niños?",
  ui_story_5071_50710702_41_dialog_content = "Es hora de la subasta. Deberías ir a ver si hay algo que quieras comprar, PlayerName querido.",
  ui_story_5071_50710702_42_dialog_content = "Mi subasta es diferente a las de Umbraton. Es transparente y abierta. ¡Deberías echarle un vistazo!",
  ui_story_5071_50710702_43_dialog_content = "El Señor Sombrío y yo trabajamos muy duro para hacer esto posible.",
  ui_story_5071_50710702_44_dialog_content = "Todo lo bueno desaparecerá si no te mueves rápidamente.",
  ui_story_5071_50710702_45_dialog_content = "Pero no tengo mucho dinero para gastar... ¡Espera, eso no es importante! Mira esto, Señora Sheol!",
  ui_story_5071_50710702_46_dialog_content = "Hay una mujer en el manuscrito de la Sra. Yvonne que tiene el mismo nombre que tu madre...",
  ui_story_5071_50710702_47_dialog_content = "¿Qué? Déjame ver... La Sra. Yvonne siempre ha basado sus historias en Umbraton. Esto no es nada nuevo.",
  ui_story_5071_50710702_48_dialog_content = "Es un asesinato... Pero las ficciones no son reales. Las descripciones en una novela suelen ser inventadas.",
  ui_story_5071_50710702_49_dialog_content = "Pero entonces, ¿por qué usaría ella un nombre real?",
  ui_story_5071_50710702_50_dialog_content = "No leas demasiado en ello, querido. Puedes preguntarle a la Sra. Yvonne después de que termine la subasta.",
  ui_story_5071_50710702_51_dialog_content = "Lo importante es que la subasta está a punto de comenzar. No puedes quedarte aquí...",
  ui_story_5071_50710702_52_dialog_content = "¡Al menos no Vergil, él todavía tiene que evaluar objetos para mí!",
  ui_story_5071_50710702_53_dialog_content = "Quizás pueda conseguir el tesoro a bajo precio...",
  ui_story_5071_50710702_54_dialog_content = "¡Espera por mí, Señora Sheol!",
  ui_story_5071_50710801_1_dialog_content = "No tengo ninguna otra solicitud excepto una, Señor Sombrío. Solo deseo publicar una biografía sobre ti.",
  ui_story_5071_50710801_2_dialog_content = "Está bien. No tienes que obtener mi permiso.",
  ui_story_5071_50710801_3_dialog_content = "Umbraton da la bienvenida a la libertad creativa.",
  ui_story_5071_50710801_4_dialog_content = "Entiendo... Y me alivia escucharte decir eso, pero aún deseo preguntarte sobre ciertos detalles de aquel entonces...",
  ui_story_5071_50710801_5_dialog_content = "<color=#e8d9bb>En la escena de la subasta en la aeronave Cloudrover</color>",
  ui_story_5071_50710801_6_dialog_content = "Ejem... El artículo que trajimos para la subasta es \"Un Rincón del Desierto de Rediesel\", una obra del Maestro Finch en su viaje.",
  ui_story_5071_50710801_7_dialog_content = "El maestro Finch es un reconocido artista viajero con muchas obras de arte famosas a su crédito, esta entre ellas.",
  ui_story_5071_50710801_8_dialog_content = "Como podemos ver, el Maestro Finch retrató el desierto bajo un sol brillante en capas a través de su único estilo romántico.",
  ui_story_5071_50710801_9_dialog_content = "Destacó de manera poco convencional la arena en azul para hacerla parecer como olas del océano—",
  ui_story_5071_50710801_10_dialog_content = "¿Eh? ¿Pensé que el Gremio de Explorador Nublar estaba a cargo de organizar subastas?",
  ui_story_5071_50710801_11_dialog_content = "Abogamos por el comercio libre y la igualdad de transparencia, por lo que todos tienen la oportunidad de presentar lo suyo.",
  ui_story_5071_50710801_12_dialog_content = "Mucha gente en Umbraton organizaba subastas clandestinas en el pasado. Pero el origen de los bienes siempre estaba en duda, y el precio a menudo era irrazonable.",
  ui_story_5071_50710801_13_dialog_content = "Somos diferentes, sin embargo. Puedes comprar o vender en nuestras subastas de manera segura, con valoraciones gratuitas para arrancar.",
  ui_story_5071_50710801_14_dialog_content = "Disculpe, pero esta pintura es una falsificación... Venderla como si fuera auténtica sería un fraude.",
  ui_story_5071_50710801_15_dialog_content = "(Este pequeño parece una persona totalmente diferente cuando habla de su profesión.)",
  ui_story_5071_50710801_16_dialog_content = "*sonidos ruidosos*",
  ui_story_5071_50710801_17_dialog_content = "¡Todos, por favor cálmense! ¿Qué prueba tienen para llamar a esto una falsificación?",
  ui_story_5071_50710801_18_dialog_content = "Exactamente, ¿tus sentidos son más agudos que los nuestros?",
  ui_story_5071_50710801_19_dialog_content = "Bueno, ahora es bastante obvio quién es el vendedor...",
  ui_story_5071_50710801_20_dialog_content = "El Maestro Finch es famoso por sus representaciones de las costumbres locales que vio durante sus viajes...",
  ui_story_5071_50710801_21_dialog_content = "Como resultado... Todas sus obras de arte utilizan pinturas y pigmentos de origen local.",
  ui_story_5071_50710801_22_dialog_content = "Pero el esquema de color en esta pintura sí parece rudo y salvaje.",
  ui_story_5071_50710801_23_dialog_content = "Los aspectos más destacados de \"Un rincón en el desierto de Rediesel\" deberían haber sido pintados con pigmentos azules brillantes extraídos de las capas subterráneas del desierto—",
  ui_story_5071_50710801_24_dialog_content = "Pero esta pintura utiliza gemas trituradas, un lujo poco común en el desierto de Rediesel.",
  ui_story_5071_50710801_25_dialog_content = "El falsificador no tuvo en cuenta las propiedades absorbentes de la arena cuando se usa para extraer pigmentos...",
  ui_story_5071_50710801_26_dialog_content = "Además, la arena en la pintura original creó un tono más claro, ya que el Maestro Finch quería que se pareciera a las olas del océano.",
  ui_story_5071_50710801_27_dialog_content = "El lienzo utilizado para esta falsificación fue horneado para replicar la textura del original. Al hacerlo, los colores se oscurecieron accidentalmente...",
  ui_story_5071_50710801_28_dialog_content = "¡Todo es tu culpa! ¿No dije que te mantuvieras alejado de todos los trucos elegantes—",
  ui_story_5071_50710801_29_dialog_content = "¿A quién estás culpando? ¡No podrías hacer una copia decente sin mí!",
  ui_story_5071_50710801_30_dialog_content = "Seguridad, por favor escoltelos fuera, ah, y asegúrese de que se lleven su pintura con ellos.",
  ui_story_5071_50710801_31_dialog_content = "¡Vaya, Virgilio... Realmente sabes tus cosas!",
  ui_story_5071_50710801_32_dialog_content = "¿Crees eso? Es solo algo que realmente me apasiona, eso es todo...",
  ui_story_5071_50710801_33_dialog_content = "Por supuesto que sí. La profesionalidad de mi pequeño empleado nunca está en duda.",
  ui_story_5071_50710801_34_dialog_content = "Y esto ciertamente está más allá del nivel de un niño, querido.",
  ui_story_5071_50710801_35_dialog_content = "Mmm...",
  ui_story_5071_50710801_36_dialog_content = "Hola a todos, y bienvenidos a la subasta. Les mostraré el próximo artículo.",
  ui_story_5071_50710801_37_dialog_content = "Esta es una pintura al óleo de un cliente mío anónimo. El artista también es desconocido.",
  ui_story_5071_50710801_38_dialog_content = "Esta es una obra maestra desde un punto de vista técnico. Espero que a todos les guste.",
  ui_story_5071_50710801_39_dialog_content = "¡Este cuadro se llama—\"La muerte de la dama\"!",
  ui_story_5071_50710801_40_dialog_content = "Dado que el valor no puede determinarse, la subasta comenzará en cincuenta cien mil.",
  ui_story_5071_50710801_41_dialog_content = "¿Es esa... la Sra. Red Mercury en la pintura? Y el asesino que está al lado parece que...",
  ui_story_5071_50710801_42_dialog_content = "No, parece ser Lady Melissa...",
  ui_story_5071_50710801_43_dialog_content = "¿Qué es esto? ¿Por qué se parece a la espalda del Señor Sombrío?",
  ui_story_5071_50710801_44_dialog_content = "Esa pintura... Pero, ¿cómo puede ser esto?",
  ui_story_5071_50710801_45_dialog_content = "PlayerName cariño, ¿podrías hacer una oferta por ese cuadro para mí?",
  ui_story_5071_50710801_46_dialog_content = "No sé de quién es la solicitud, pero no puedo pujar como líder del gremio, así que por favor... Solo di el precio.",
  ui_story_5071_50710801_47_dialog_content = "Sesenta cien mil.",
  ui_story_5071_50710801_48_dialog_content = "Un millón.",
  ui_story_5071_50710801_49_dialog_content = "¡Haz una jugada, cariño!",
  ui_story_5071_50710801_50_dialog_content = "¡Dos millones!",
  ui_story_5071_50710801_51_dialog_content = "¡Un millón cuatro!",
  ui_story_5071_50710801_52_dialog_content = "*charla*",
  ui_story_5071_50710801_53_dialog_content = "Bueno.",
  ui_story_5071_50710801_54_dialog_content = "(¿Cuánto tiempo me llevará ahorrar de nuevo?)",
  ui_story_5071_50710801_55_dialog_content = "No te quedes ahí sentada, cariño. ¡Haz una oferta, el dinero no es problema!",
  ui_story_5071_50710801_56_dialog_content = "T-Dos millones!",
  ui_story_5071_50710801_57_dialog_content = "*silencio*",
  ui_story_5071_50710801_58_dialog_content = "Dos millones a la una... ¿Alguna otra oferta? ¡Dos millones a las dos!",
  ui_story_5071_50710801_59_dialog_content = "Dos millones tres veces... ¡Vendido al Celestita!",
  ui_story_5071_50710801_60_dialog_content = "Definitivamente me sorprende que una obra desconocida pueda alcanzar tal precio. Aplaudamos a Caelestite por tener un ojo tan perspicaz.",
  ui_story_5071_50710801_61_dialog_content = "La Señora Sheol tiene buen gusto de hecho.",
  ui_story_5071_50710801_62_dialog_content = "No esperaba que te interesara tanto la pintura como para romper las reglas y conseguir un intermediario.",
  ui_story_5071_50710801_63_dialog_content = "Quizás tenemos mucho más en común de lo que nos dimos cuenta. No es de extrañar que el Señor de las Sombras te recomendara conmigo.",
  ui_story_5071_50710801_64_dialog_content = "Estoy halagado. Eres realmente impresionante por fundar un gremio trans-Astra fuera de Umbraton.",
  ui_story_5071_50710801_65_dialog_content = "Y veo que también tienes vínculos con el Señor de las Sombras. Debería ser yo el que te siga.",
  ui_story_5071_50710801_66_dialog_content = "... Me gustas, tanto que no me importa perder la pintura contigo.",
  ui_story_5071_50710801_67_dialog_content = "Bueno, gracias, Sra. Hanstie.",
  ui_story_5071_50710801_68_dialog_content = "D-Deberíamos ir a pagar por la pintura ahora, Señora Sheol.",
  ui_story_5071_50710801_69_dialog_content = "¿Pensaste que te dejaría colgado, PlayerName? Vamos, veamos la pintura.",
  ui_story_5071_50710801_70_dialog_content = "May ¿Vengo contigo, Señora Sheol?",
  ui_story_5071_50710801_71_dialog_content = "Por supuesto.",
  ui_story_5071_50710801_72_dialog_content = "¿Eh? Mmm... huelo algo—",
  ui_story_5071_50710801_73_dialog_content = "Ese aroma tenue...",
  ui_story_5071_50710801_74_dialog_content = "Señora Sheol... Creo que esta falsificación fue hecha por \"A\", mi falsificador favorito.",
  ui_story_5071_50710801_75_dialog_content = "¡Esta es la primera vez que veo una de sus obras originales después de conocerlas durante tanto tiempo!",
  ui_story_5071_50710801_76_dialog_content = "¿Oh? Veo que el equipo de subastas que contraté esta vez no es tan profesional como tú.",
  ui_story_5071_50710801_77_dialog_content = "El origen de esta pintura es desconocido, entonces, ¿cómo dedujiste quién es el artista, mi niño?",
  ui_story_5071_50710801_78_dialog_content = "Bueno... suelo trabajar con muchos productos falsos, así que me he familiarizado bastante con el trabajo de muchos falsificadores hábiles.",
  ui_story_5071_50710801_79_dialog_content = "Pero el más grande entre ellos es un artista conocido como \"A.\"",
  ui_story_5071_50710801_80_dialog_content = "Además de sus habilidades inigualables, también les gusta esconder una pequeña letra \"A\" en alguna parte de sus falsificaciones. Es como una marca registrada de su trabajo.",
  ui_story_5071_50710801_81_dialog_content = "A veces está en el cabello de una persona o en sus ojos, esta vez, está en el cuello de la camisa de una persona.",
  ui_story_5071_50710801_82_dialog_content = "... ¿Notaste todo eso? Debes gustarte mucho A.",
  ui_story_5071_50710801_83_dialog_content = "Por mucho que me guste \"A\", creo que son bastante egocéntricos. Quiero decir, ¿por qué más elegirían dejar una señal de su presencia en una falsificación?",
  ui_story_5071_50710801_84_dialog_content = "\"A\" me parece una persona que nunca se rendirá en su búsqueda para alcanzar sus objetivos.",
  ui_story_5071_50710801_85_dialog_content = "¿En serio? Eso es bastante... interesante.",
  ui_story_5071_50710801_86_dialog_content = "¿Ah?",
  ui_story_5071_50710801_87_dialog_content = "U-Un extraño...",
  ui_story_5071_50710801_88_dialog_content = "No creo que tenga sentido esconderse detrás de mí ahora...",
  ui_story_5071_50710801_89_dialog_content = "No tengas miedo. Te aprecio mucho, mi niño.",
  ui_story_5071_50710801_90_dialog_content = "Puedo ver que tienes un gran potencial. ¿Te interesaría trabajar para mí?",
  ui_story_5071_50710801_91_dialog_content = "Lo siento, Sra. Hanstie, pero Virgilio trabaja para mí.",
  ui_story_5071_50710801_92_dialog_content = "Oh, eso es desafortunado. Parece que Lady Sheol siempre me gana de mano.",
  ui_story_5071_50710801_93_dialog_content = "No, estás exagerando. Pero, ¿qué tal una obra de arte de tu elección de mi colección privada como compensación?",
  ui_story_5071_50710801_94_dialog_content = "Eso no es necesario. No quiero privar a otros de sus posesiones preciadas—",
  ui_story_5071_50710801_95_dialog_content = "Por cierto, tú tampoco sabías quién pintó esto, ¿entonces por qué la afinidad?",
  ui_story_5071_50710801_96_dialog_content = "Dudo que pagarías un precio tan exorbitante simplemente por la técnica artística.",
  ui_story_5071_50710801_97_dialog_content = "Bueno, digamos que quería ayudar a un viejo amigo.",
  ui_story_5071_50710801_98_dialog_content = "Si este cuadro llegara a Umbraton, probablemente causaría un gran daño a la reputación que ha estado construyendo.",
  ui_story_5071_50710801_99_dialog_content = "Pero como tú lo compraste para él, ya terminé aquí.",
  ui_story_5071_50710801_100_dialog_content = "Hasta luego, todos.",
  ui_story_5071_50710801_101_dialog_content = "Espera, Sra. Hanstie, tengo una pregunta más para ti.",
  ui_story_5071_50710801_102_dialog_content = "¿Conoces al Señor de las Sombras desde hace mucho tiempo?",
  ui_story_5071_50710801_103_dialog_content = "Jeje... ¿Te refieres a la persona real? Probablemente más tiempo del que piensas.",
  ui_story_5071_50710801_104_dialog_content = "Mmm—",
  ui_story_5071_50710801_105_dialog_content = "¿Qué te pasa? Mirándola así... ¿Estás pensando en su propuesta?",
  ui_story_5071_50710801_106_dialog_content = "¡N-N-En absoluto! Es solo...",
  ui_story_5071_50710801_107_dialog_content = "Vergil... También crees que es demasiado extraño para ser solo una coincidencia, ¿verdad?",
  ui_story_5071_50710801_108_dialog_content = "Esta pintura es como la parte de la historia que leímos en ese manuscrito...",
  ui_story_5071_50710801_109_dialog_content = "¿Podría ser que el amigo artista de la Sra. Yvonne no es otro que \"A\"?",
  ui_story_5071_50710801_110_dialog_content = "Ella sí dijo que comenzó a escribir de nuevo después de hacerse amiga de un cierto artista...",
  ui_story_5071_50710801_111_dialog_content = "Tienes razón, cariño, es demasiado para ser solo una coincidencia.",
  ui_story_5071_50710801_112_dialog_content = "Como si hubiera sido escenificado para que lo viéramos.",
  ui_story_5071_50710801_113_dialog_content = "No lo entiendo, Señorita Sheol... ¿Cuál podría ser el punto de todo esto?",
  ui_story_5071_50710801_114_dialog_content = "Solo dos explicaciones para esta cadena de eventos—",
  ui_story_5071_50710801_115_dialog_content = "Si no es para decirme la verdad, solo puede ser...",
  ui_story_5071_50710801_116_dialog_content = "¿Cuál es el seguimiento para este manuscrito, querida?",
  ui_story_5071_50710801_117_dialog_content = "Echa un vistazo a lo que viene después—",
  ui_story_5071_50710901_1_dialog_content = "Con un bastón dorado en la mano, el semi-humano se encontraba en el centro del Pozo. Una multitud gritando liderada por un viejo amigo lo rodeaba por todos lados.",
  ui_story_5071_50710901_2_dialog_content = "\"¡Traidor!\" gritaron. \"¿Por qué llevarías el ejército de Lumopolis justo a la puerta de Umbraton?\"",
  ui_story_5071_50710901_3_dialog_content = "El demi-humano permaneció en silencio, su mirada de acero se centró en el rostro de un solo hombre. Debajo de sus mechones azules, los ojos de Valon estaban llenos de dolor y tristeza.",
  ui_story_5071_50710901_4_dialog_content = "Después de un largo rato, Valon finalmente abrió la boca para hablar. \"Kade... ¿Por qué? ¿Por qué mataste a nuestro papá y robaste el Bastón del Pastor?\"",
  ui_story_5071_50710901_5_dialog_content = "¿Has dado la espalda a nuestro sueño? ¿Por qué obedecerías la voluntad de Lumopolis?",
  ui_story_5071_50710901_6_dialog_content = "El Pozo... Enfrenté a tantos enemigos en tu lugar hace tantos años. ¿De verdad crees que puedes detenerme con tan pocas personas?",
  ui_story_5071_50710901_7_dialog_content = "Una sola pregunta fue suficiente para enviar el pánico a través de toda la multitud.",
  ui_story_5071_50710901_8_dialog_content = "¿Qué... Pero pensé que eran mejores amigos?",
  ui_story_5071_50710901_9_dialog_content = "... Sigue leyendo.",
  ui_story_5071_50710901_10_dialog_content = "\"¡Eres demasiado débil! ¡Por eso tengo que reemplazarte!\"",
  ui_story_5071_50710901_11_dialog_content = "Con un rugido, Kade se lanzó hacia adelante y atravesó el pecho de su amigo con el bastón. Su rostro enloquecido y retorcido ya no era reconocible, ni siquiera para su propio hermano.",
  ui_story_5071_50710901_12_dialog_content = "¿P-Por qué...",
  ui_story_5071_50710901_13_dialog_content = "Me niego a ser la sombra de nadie.",
  ui_story_5071_50710901_14_dialog_content = "Con su rostro aún congelado por el shock, el joven de cabello azul se desplomó al suelo. Pronto, la multitud se llenó de desesperación.",
  ui_story_5071_50710901_15_dialog_content = "En su dolor y furia, se lanzaron a la refriega—",
  ui_story_5071_50710901_16_dialog_content = "¡F-Voltea a la siguiente página!",
  ui_story_5071_50710901_17_dialog_content = "La brutal furia de Kade finalmente se había desatado. Por interponerse en su camino, rápidamente destrozó a sus conciudadanos de Umbraton.",
  ui_story_5071_50710901_18_dialog_content = "Para erradicar toda disidencia, bañó Umbraton en un infierno azur, asegurándose de que nadie se librara de su ira.",
  ui_story_5071_50710901_19_dialog_content = "De manera perentoria, finalmente tomó la autoridad absoluta en sus manos.",
  ui_story_5071_50710901_20_dialog_content = "Para tomar el control de Umbraton, traicionó su sueño y entregó su hogar a Lumopolis.",
  ui_story_5071_50710901_21_dialog_content = "Con ese fin, tomó la vida y el apellido de su hermano, y usurpó el prominente estatus de su familia—",
  ui_story_5071_50710901_22_dialog_content = "Eligió seguir un camino de maldad y perversidad. A medida que ascendía al poder, ocultó su pasado y la existencia de Valon, su antiguo hermano.",
  ui_story_5071_50710901_23_dialog_content = "Cuando Umbraton finalmente cae bajo su completo control, nadie recuerda ninguna parte de su cruel pasado.",
  ui_story_5071_50710901_24_dialog_content = "Todo lo que saben es que comanda su pandilla con un bastón manchado de sangre.",
  ui_story_5071_50710901_25_dialog_content = "Istvan, el Señor de las Sombras de Umbraton.",
  ui_story_5071_50710901_26_dialog_content = "¿Q-Qué?",
  ui_story_5071_50710901_27_dialog_content = "Este tipo Kade... ¿Era el Señor de las Sombras todo el tiempo?",
  ui_story_5071_50710901_28_dialog_content = "¡Eso no puede ser correcto! ¡El Señor de las Sombras nunca traicionaría a Umbraton de esa manera!",
  ui_story_5071_50710901_29_dialog_content = "(Siempre he sentido algo peligroso oculto en el corazón del Señor Sombrío, pero la historia en este manuscrito...)",
  ui_story_5071_50710901_30_dialog_content = "...",
  ui_story_5071_50710901_31_dialog_content = "Señora Sheol, la Señora de las Sombras...",
  ui_story_5071_50710901_32_dialog_content = "La gente es reservada. No podemos simplemente creer lo que dicen pero—",
  ui_story_5071_50710901_33_dialog_content = "<color=#e8d9bb>Auge-</color>",
  ui_story_5071_50710901_34_dialog_content = "¿Qué está pasando? ¿De dónde vino esa explosión?",
  ui_story_5071_50710901_35_dialog_content = "¡Lady Sheol! P-Por alguna razón, ¡los guardias de Lumopolis a bordo nos atacaron de repente!",
  ui_story_5071_50710901_36_dialog_content = "¿Por qué nos atacarían los guardias de Lumopolis?",
  ui_story_5071_50710901_37_dialog_content = "¿He ofendido a alguien?",
  ui_story_5071_50710901_38_dialog_content = "¡Para! ¿Qué crees que estás haciendo con el dirigible de la Señora Sheol?",
  ui_story_5071_50710901_39_dialog_content = "¡Todavía estamos en el aire! Si sigues dañando el dirigible, todos a bordo morirán—",
  ui_story_5071_50710901_40_dialog_content = "¡Enseñemos a estos tontos una dura lección!",
  ui_story_5071_50710901_41_dialog_content = "¡Detente! No hagas esto...",
  ui_story_5071_50710901_42_dialog_content = "¡Esto pondrá a todos en grave peligro!",
  ui_story_5071_50710901_43_dialog_content = "¡Deja de jugar con mi territorio!",
  ui_story_5071_50710901_X43_dialog_content = "¡¿E-Eh?!",
  ui_story_5071_50710901_X44_dialog_content = "¿Por qué sois unos ignorantes...",
  ui_story_5071_50710901_X45_dialog_content = "¡Cómo te atreves a intentar destruir mi dirigible!",
  ui_story_5071_50710901_X46_dialog_content = "¡Eek!",
  ui_story_5071_50710901_X47_dialog_content = "¡Q-Qué increíble patada voladora!",
  ui_story_5071_50710901_X48_dialog_content = "¡No puedo creer que ese sea mi jefe!",
  ui_story_5071_50710901_X49_dialog_content = "¡E-Esta es la primera vez que la veo pelear!",
  ui_story_5071_50710901_44_dialog_content = "¿Q-Qué increíble patada voladora—",
  ui_story_5071_50710901_45_dialog_content = "Señorita Sheol...",
  ui_story_5071_50710901_46_dialog_content = "Señor Sombrío, parece que hay un alboroto afuera. Alguien parece haberse colado.",
  ui_story_5071_50710901_47_dialog_content = "¿Oh?",
  ui_story_5071_50710901_48_dialog_content = "Veo que el \"invitado\" se está volviendo impaciente. Interesante.",
  ui_story_5071_50710901_49_dialog_content = "?",
  ui_story_5071_50711001_1_dialog_content = "¿Qué está pasando?",
  ui_story_5071_50711001_2_dialog_content = "¡Señor de las Sombras! ¡Finalmente estás aquí! Estos—",
  ui_story_5071_50711001_3_dialog_content = "Señor de las Sombras, ¿por qué haces esto? ¿No nos ordenaste hacer esto?",
  ui_story_5071_50711001_4_dialog_content = "Nos ordenaste eliminar a estos alborotadores, entonces ¿por qué tú...",
  ui_story_5071_50711001_5_dialog_content = "!",
  ui_story_5071_50711001_6_dialog_content = "¿Así que el Señor Sombrío está detrás de esto?",
  ui_story_5071_50711001_7_dialog_content = "No es de extrañar que estos guardias de Lumopolis sean...",
  ui_story_5071_50711001_8_dialog_content = "¿Por qué nos tratan así...",
  ui_story_5071_50711001_9_dialog_content = "Cállate. La situación no es—",
  ui_story_5071_50711001_10_dialog_content = "<color=#e8d9bb>Innumerables pedazos de papel vuelan repentinamente por el aire y caen como copos de nieve. Estos son—</color>",
  ui_story_5071_50711001_11_dialog_content = "¿Los manuscritos de la Sra. Yvonne?",
  ui_story_5071_50711001_12_dialog_content = "¡Todas las páginas se han esparcido por todas partes! ¿Quién podría haber...",
  ui_story_5071_50711001_13_dialog_content = "Espera, estas páginas del manuscrito son todas iguales. Echa un vistazo.",
  ui_story_5071_50711001_14_dialog_content = "Después de muchos años, finalmente regresé a este lugar. Istvan es ahora el gobernante de Umbraton, y el sueño de Valon de la Guilda de Umbraton se ha convertido en una herramienta de su autoridad.",
  ui_story_5071_50711001_15_dialog_content = "¿Debería seguir escribiendo por el bien de la verdad? ¿O debería mantener estas historias enterradas profundamente en mi corazón?",
  ui_story_5071_50711001_16_dialog_content = "Siempre he observado cómo se desarrollaban eventos malvados ante mí, desgastando mi conciencia. Al principio, pensé que me había acostumbrado a ello.",
  ui_story_5071_50711001_17_dialog_content = "Si no hubiera descubierto la verdad de sus últimas ambiciones, podría haber seguido observando desde la distancia—",
  ui_story_5071_50711001_18_dialog_content = "Por pura casualidad, aprendí de la insaciable codicia de Istvan a través de sus subordinados. Aunque se sienta firmemente en la cima, aún desea más.",
  ui_story_5071_50711001_19_dialog_content = "Aunque se presenta como un gobernante generoso, secretamente está insatisfecho con las pandillas y gremios neutrales.",
  ui_story_5071_50711001_20_dialog_content = "Aquellos que operan fuera del control de su gremio lo han puesto nervioso... No tolerará ninguna clase de rebelión.",
  ui_story_5071_50711001_21_dialog_content = "Por esta razón, planea usar el Gremio Cloudrover para reunir a su oposición y destruirlos de una vez por todas. Al hacerlo, obtendrá lo que siempre ha buscado: control absoluto sobre Umbraton.",
  ui_story_5071_50711001_22_dialog_content = "Con el poco tiempo que me queda en este mundo, deseo hacer justicia a un hombre cuyo pasado ha sido olvidado.",
  ui_story_5071_50711001_23_dialog_content = "—Firmado, Yvonne.",
  ui_story_5071_50711001_24_dialog_content = "¿Es verdad?",
  ui_story_5071_50711001_25_dialog_content = "La señorita Yvonne y el Señor Sombrío acaban de tener una reunión, ¿verdad?",
  ui_story_5071_50711001_26_dialog_content = "¡Cálmate! Hay algo raro en este manuscrito.",
  ui_story_5071_50711001_27_dialog_content = "Dado que el Señor Sombrío está aquí, ¿no significa eso que la señorita Yvonne está...",
  ui_story_5071_50711001_28_dialog_content = "Esto es demasiado unilateral...",
  ui_story_5071_50711001_29_dialog_content = "¿Seremos todos silenciados?",
  ui_story_5071_50711001_30_dialog_content = "¿Tienes más? ¡Muéstranos!",
  ui_story_5071_50711001_31_dialog_content = "H-Espera!",
  ui_story_5071_50711001_32_dialog_content = "Por favor, mantengan la compostura, todos.",
  ui_story_5071_50711001_33_dialog_content = "Es... Es un...",
  ui_story_5071_50711001_34_dialog_content = "¿Es esto cierto? ¿Es realmente un relato del pasado del Señor de las Sombras?",
  ui_story_5071_50711001_35_dialog_content = "*suspiro* No están escuchando en absoluto—",
  ui_story_5071_50711001_36_dialog_content = "¿Esos rumores eran realmente ciertos? ¿Y ahora quiere matarnos?",
  ui_story_5071_50711001_37_dialog_content = "Deja de discutir. Esto es solo una novela. ¿De verdad crees que es cierto?",
  ui_story_5071_50711001_38_dialog_content = "Pero coincide perfectamente con los rumores...",
  ui_story_5071_50711001_39_dialog_content = "Dado que sabes que esos son rumores, ¿qué tan creíbles crees que son?",
  ui_story_5071_50711001_40_dialog_content = "Pero el Gremio Umbraton realmente controla nuestras rutas comerciales. ¿Cómo sabes que no nos está utilizando para hacerse más poderoso?",
  ui_story_5071_50711001_41_dialog_content = "Todo nuestro dinero está depositado en el Gremio Umbraton... Si realmente decide matarnos y tomar nuestro dinero...",
  ui_story_5071_50711001_42_dialog_content = "¡Comerciantes estúpidos, malos comerciantes! ¿Por qué crees todo lo que escuchas?",
  ui_story_5071_50711001_43_dialog_content = "¡El jefe no es ese tipo de persona!",
  ui_story_5071_50711001_44_dialog_content = "¡Es solo una adaptación!",
  ui_story_5071_50711001_45_dialog_content = "¿No vas a explicar, Señor Sombrío?",
  ui_story_5071_50711001_46_dialog_content = "(¿Señor de las sombras?)",
  ui_story_5071_50711001_47_dialog_content = "(¿Él... los está observando?)",
  ui_story_5071_50711001_48_dialog_content = "Parece que el líder del Gremio del Pantera Roja tiene algo que decir... El Gremio del Loro Gris, también...",
  ui_story_5071_50711001_49_dialog_content = "(No, no es eso...)",
  ui_story_5071_50711001_50_dialog_content = "La pandilla Rusted Falcon, también... Ya veo.",
  ui_story_5071_50711001_51_dialog_content = "(Él está evaluando a su presa.)",
  ui_story_5071_50711001_52_dialog_content = "¡Informando! Esto es malo, Señora Sheol!",
  ui_story_5071_50711001_53_dialog_content = "Sra. Yvonne es...",
  ui_story_5071_50711001_54_dialog_content = "<size=45>¡La señora Yvonne está muerta en la sala de recepción temporal!</size>",
  ui_story_5071_50711101_1_dialog_content = "El limpiador responsable de limpiar esta sala de recepción temporal es quien hizo el descubrimiento.",
  ui_story_5071_50711101_2_dialog_content = "Todo está ordenado y limpio en la escena. No hubo lucha entre la víctima y el asesino.",
  ui_story_5071_50711101_3_dialog_content = "Lo único que encontramos fue algo de cabello en la alfombra donde estaba acostada la señora Yvonne.",
  ui_story_5071_50711101_4_dialog_content = "Este no es el cabello de un Aurorian ordinario. De hecho, parece más el cabello de una bestia, pero se ha mantenido en excelente estado...",
  ui_story_5071_50711101_5_dialog_content = "Señor de las Sombras, esta sala de recepción temporal te fue prestada... ¿Verdad?",
  ui_story_5071_50711101_6_dialog_content = "¿Nos recuerda dónde estaba justo ahora, mi señor?",
  ui_story_5071_50711101_7_dialog_content = "Cuida lo que dices. ¿Estás dudando de mi jefe?",
  ui_story_5071_50711101_8_dialog_content = "Seleucid.",
  ui_story_5071_50711101_9_dialog_content = "Pero jefe...",
  ui_story_5071_50711101_10_dialog_content = "Deberías ser más considerado si solo fue una conjetura y no una acusación directa.",
  ui_story_5071_50711101_11_dialog_content = "Hasta hace un momento, estaba discutiendo los libros de la Sra. Yvonne con ella.",
  ui_story_5071_50711101_12_dialog_content = "Solo vine a ver qué era la conmoción.",
  ui_story_5071_50711101_13_dialog_content = "Pero la Sra. Yvonne estaba emocionada en ese momento, afirmó que acababa de tener una inspiración.",
  ui_story_5071_50711101_14_dialog_content = "Así que la dejé sola, sin querer molestarla.",
  ui_story_5071_50711101_15_dialog_content = "Y la señorita Yvonne murió aquí más tarde. ¿Cómo es eso posible?",
  ui_story_5071_50711101_16_dialog_content = "Acabamos de escuchar que la señorita Yvonne tiene material comprometedor sobre el pasado del Señor de las Sombras.",
  ui_story_5071_50711101_17_dialog_content = "Es sospechoso cómo murió...",
  ui_story_5071_50711101_18_dialog_content = "Todos, por favor no propaguen rumores entre la multitud.",
  ui_story_5071_50711101_19_dialog_content = "¿Quién es? ¿Quién está empezando rumores? ¡Muéstrate!",
  ui_story_5071_50711101_20_dialog_content = "Quizás también seremos devorados por las sombras, justo como ella.",
  ui_story_5071_50711101_21_dialog_content = "May ¿Pregunto quién eres, señor? Parece que realmente deseas <color=#FFB400>expresar tus pensamientos</color>, ¿por qué no te acercas un poco más para que todos podamos escuchar?",
  ui_story_5071_50711101_22_dialog_content = "Basta, Kleken.",
  ui_story_5071_50711101_23_dialog_content = "No arruines el día importante de Sheol.",
  ui_story_5071_50711101_24_dialog_content = "Ah... ¿Cómo podría ser esto...",
  ui_story_5071_50711101_25_dialog_content = "Sra. Yvonne...",
  ui_story_5071_50711101_26_dialog_content = "Se ve tan tranquila con esa sonrisa en su rostro, como si simplemente estuviera durmiendo...",
  ui_story_5071_50711101_27_dialog_content = "Ella no tiene ninguna herida, así que podemos descartar una emboscada...",
  ui_story_5071_50711101_28_dialog_content = "¿Es posible... que haya sido envenenada?",
  ui_story_5071_50711101_29_dialog_content = "<color=#e8d9bb>Auge-</color>",
  ui_story_5071_50711101_30_dialog_content = "¡El-El dirigible está temblando!",
  ui_story_5071_50711101_31_dialog_content = "Probablemente se deba al ataque de hace un momento... No entren en pánico, todos.",
  ui_story_5071_50711101_32_dialog_content = "Este dirigible es robusto y confiable—",
  ui_story_5071_50711101_33_dialog_content = "<color=#e8d9bb>Auge-</color>",
  ui_story_5071_50711101_34_dialog_content = "... Contacta al jefe de ingeniería y dile que revise si hay daños.",
  ui_story_5071_50711101_35_dialog_content = "¡Sí, señora!",
  ui_story_5071_50711101_36_dialog_content = "Todos, por favor manténganse tranquilos y escúchenme.",
  ui_story_5071_50711101_37_dialog_content = "Hoy es un día importante para mi amiga. Estoy aquí estrictamente para celebrar que su sueño se haga realidad.",
  ui_story_5071_50711101_38_dialog_content = "No sabotearé esta alegre ocasión, ni toleraré que nadie lo haga.",
  ui_story_5071_50711101_39_dialog_content = "Los Guardianes abordarán e investigarán tan pronto como aterricemos.",
  ui_story_5071_50711101_40_dialog_content = "Por supuesto, también me escrutarán. Acepto todas las consecuencias si me encuentran involucrado de alguna manera.",
  ui_story_5071_50711101_41_dialog_content = "Pero recuerdo que los Guardianes siguen las órdenes del Gremio Umbraton...",
  ui_story_5071_50711101_42_dialog_content = "Y todos son de la Pandilla Istvan.",
  ui_story_5071_50711101_43_dialog_content = "¿No es tu hija la jefa del Gremio Umbraton?",
  ui_story_5071_50711101_44_dialog_content = "No te conozco en absoluto, pero parece que tienes una fuerte opinión sobre mí.",
  ui_story_5071_50711101_45_dialog_content = "¿Es eso una amenaza?",
  ui_story_5071_50711101_46_dialog_content = "Hay algo que realmente me intriga, Señor de las Sombras. ¿Realmente serás castigado?",
  ui_story_5071_50711101_47_dialog_content = "La llamada Regulación de Seguridad de Umbraton acaba de ser anunciada. ¡Tu promesa es demasiado vacía!",
  ui_story_5071_50711101_48_dialog_content = "Nunca esperé la muerte de la señorita Yvonne. Qué lástima...",
  ui_story_5071_50711101_49_dialog_content = "Como tu viejo amigo, pensé que podrías haber cambiado.",
  ui_story_5071_50711101_50_dialog_content = "Incluso después de todos estos años, parece que tú y Umbraton aún no han olvidado las cicatrices del pasado.",
  ui_story_5071_50711101_51_dialog_content = "Istvan... no, <color=#FFB400>Kade</color>, ¿de verdad no nos vas a dejar vivir?",
  ui_story_5071_50711101_52_dialog_content = "¿Harás lo que hiciste hace tantos años atrás...",
  ui_story_5071_50711101_53_dialog_content = "¿Y destruir a todos los que te desobedecen una vez más?",
  ui_story_5071_50711101_54_dialog_content = "...",
  ui_story_5071_50711101_55_dialog_content = "*susurra*",
  ui_story_5071_50711101_56_dialog_content = "Escuché que el Señor Sombrío eliminó a todos los que se opusieron a él para...",
  ui_story_5071_50711101_57_dialog_content = "Estás hablando sobre ese incidente del Pozo en los manuscritos, ¿verdad?",
  ui_story_5071_50711101_58_dialog_content = "El Pozo estaba lleno de líderes de Umbraton antes de que nos golpeara la Crisis de Darkover. Escuché que el Señor de las Sombras luchó allí uno contra cien.",
  ui_story_5071_50711101_59_dialog_content = "Así es. Eran como nosotros. También eran líderes de Umbraton...",
  ui_story_5071_50711101_60_dialog_content = "Es tan poderoso. Por eso es el Señor de las Sombras.",
  ui_story_5071_50711101_61_dialog_content = "¿Escuchas eso, <color=#FFB400>Kade</color>? Tu pasado no ha sido completamente oscurecido.",
  ui_story_5071_50711101_62_dialog_content = "¡Asesinaste a tu amigo y a tu padre adoptivo, y sé que no soy el único que lo recuerda!",
  ui_story_5071_50711101_63_dialog_content = "Entonces el contenido de esos manuscritos es...",
  ui_story_5071_50711101_64_dialog_content = "Temo que el pasado sea mucho más cruel de lo que está documentado. Es posible que haya adoptado medios aún más desvergonzados e inescrupulosos para llegar a donde está ahora—",
  ui_story_5071_50711101_65_dialog_content = "¡Definitivamente es capaz de hacer algo así!",
  ui_story_5071_50711101_66_dialog_content = "Sus métodos son totalmente inaceptables. ¿Todavía podemos confiar en él?",
  ui_story_5071_50711101_67_dialog_content = "Escuché hace mucho tiempo que traicionó a su amigo y se rindió a Lumopolis para alcanzar su estado actual...",
  ui_story_5071_50711101_68_dialog_content = "Él es el legendario hijo demoníaco...",
  ui_story_5071_50711101_69_dialog_content = "Todas estas supuestas reformas ignoran completamente nuestros intereses. ¿Qué pretenden hacer...",
  ui_story_5071_50711101_70_dialog_content = "¿Realmente quiere eliminarnos a todos?",
  ui_story_5071_50711101_71_dialog_content = "Estoy realmente feliz de verte de nuevo hoy... <color=#FFB400>Ava</color>.",
  ui_story_5071_50711101_72_dialog_content = "Pero incluso ahora no entiendo por qué elegirías este momento para aparecer.",
  ui_story_5071_50711101_73_dialog_content = "Por un breve segundo, esperaba sinceramente que estuvieras aquí por sus sueños.",
  ui_story_5071_50711101_74_dialog_content = "Pero este es tu verdadero propósito, ya veo.",
  ui_story_5071_50711101_75_dialog_content = "Tú y yo no somos iguales. Soy el único que realmente recuerda sus sueños.",
  ui_story_5071_50711101_76_dialog_content = "Señorita Sheol, deberíamos aterrizar una vez que el personal de ingeniería termine con la inspección.",
  ui_story_5071_50711101_77_dialog_content = "Los Guardianes deberían estar en camino y se encargarán del resto.",
  ui_story_5071_50711101_78_dialog_content = "Pero ahora solo hay naturaleza debajo de nosotros.",
  ui_story_5071_50711101_79_dialog_content = "Tampoco estamos lejos del territorio de los Eclipsites.",
  ui_story_5071_50711101_80_dialog_content = "Ese hombre... podría no dejarnos ir así.",
  ui_story_5071_50711101_81_dialog_content = "¿Es posible que por el bien de la reforma, él incluso...",
  ui_story_5071_50711101_82_dialog_content = "¡No hay necesidad de temer, todos!",
  ui_story_5071_50711101_83_dialog_content = "Mi gremio tiene una serie de dirigibles más pequeños estacionados cerca. Si están dispuestos a confiar en mí, estaré encantado de transportarlos a todos de regreso a Umbraton.",
  ui_story_5071_50711101_84_dialog_content = "¡Llévame! ¡Me iré contigo!",
  ui_story_5071_50711101_85_dialog_content = "Nada sucederá aún ya que todavía hay mucha gente aquí, pero si continuamos quedándonos en este dirigible...",
  ui_story_5071_50711101_86_dialog_content = "¡Tengo una familia. No quiero morir!",
  ui_story_5071_50711101_87_dialog_content = "*susurra*",
  ui_story_5071_50711101_88_dialog_content = "T-También iré contigo.",
  ui_story_5071_50711101_89_dialog_content = "¡Yo también!",
  ui_story_5071_50711101_90_dialog_content = "Salgamos de aquí ahora. No quiero quedarme aquí.",
  ui_story_5071_50711101_91_dialog_content = "Vamos, ¿por qué nos tratas como si fuéramos algún tipo de villanos?",
  ui_story_5071_50711101_92_dialog_content = "Ustedes son los que nos han estado lamiendo las botas todo el tiempo—",
  ui_story_5071_50711101_93_dialog_content = "Oye, también podrías ser los que estén en problemas si sigues siguiéndola.",
  ui_story_5071_50711101_94_dialog_content = "Después de todo, no podemos garantizar que no haremos algo similar si te quedas.",
  ui_story_5071_50711101_95_dialog_content = "¡Corre corre!",
  ui_story_5071_50711101_96_dialog_content = "Déjalos ir.",
  ui_story_5071_50711101_97_dialog_content = "Creo que la señorita Hanstie tiene su propio plan.",
  ui_story_5071_50711101_98_dialog_content = "Y para ese fin, definitivamente ella no hará daño a su preciada audiencia.",
  ui_story_5071_50711101_99_dialog_content = "Pero seguramente nos difamarán si los dejamos ir—",
  ui_story_5071_50711101_100_dialog_content = "Síguelos en un pequeño dirigible.",
  ui_story_5071_50711101_101_dialog_content = "Solo mantén tu distancia y asegúrate de que las personas estén seguras.",
  ui_story_5071_50711101_102_dialog_content = "<color=#e8d9bb>Auge-</color>",
  ui_story_5071_50711101_103_dialog_content = "Parece que este dirigible realmente está condenado. Debería advertirles a todos—",
  ui_story_5071_50711101_104_dialog_content = "Continuar al lado de ese hombre solo te pondrá en peligro mortal.",
  ui_story_5071_50711101_105_dialog_content = "Por favor, no hables así del Señor de las Sombras, especialmente porque aún no ha hecho nada.",
  ui_story_5071_50711101_106_dialog_content = "Puede que se mantenga oculto en las sombras todo el tiempo, pero yo conozco su verdadera identidad.",
  ui_story_5071_50711101_107_dialog_content = "Es un hombre que asesinó a su hermano y despojó a su padre adoptivo de todo. No solo eso, hizo todo lo posible para asegurarse de que nadie los recordara en absoluto.",
  ui_story_5071_50711101_108_dialog_content = "Un hombre que abandonaría su propio nombre, todo por beneficio personal.",
  ui_story_5071_50711101_109_dialog_content = "No es más que un demonio que pisotea a cualquiera que se interponga entre él y el trono que busca.",
  ui_story_5071_50711101_X109_dialog_content = "¡No estás apto para sostener el <color=#FFB400>Bastón de Shepherd</color>, Kade!",
  ui_story_5071_50711101_110_dialog_content = "...",
  ui_story_5071_50711101_111_dialog_content = "... No importa lo que digas, aún elijo creer en el Señor de las Sombras que siempre he conocido.",
  ui_story_5071_50711101_112_dialog_content = "Bien dicho, pero discúlpeme, Sra. Hanstie, puede irse primero.",
  ui_story_5071_50711101_113_dialog_content = "Discrepo. Creo que es mejor que me quede aquí.",
  ui_story_5071_50711101_114_dialog_content = "Huelo noticias de última hora, así que tampoco me voy.",
  ui_story_5071_50711101_115_dialog_content = "...",
  ui_story_5071_50711101_116_dialog_content = "Vivirás para lamentarlo, cada uno de vosotros.",
  ui_story_5071_50711101_117_dialog_content = "Estoy seguro de que todos son conscientes de su capacidad para la tiranía, ¿entonces por qué hacer la vista gorda a ello?",
  ui_story_5071_50711101_118_dialog_content = "Lamentable... Todos sois tan lamentables.",
  ui_story_5071_50711101_119_dialog_content = "Adiós, \"Sra. Hanstie.\"",
  ui_story_5071_50711101_120_dialog_content = "Bueno, tú también deberías...",
  ui_story_5071_50711101_121_dialog_content = "¡Siento enemigos!",
  ui_story_5071_50711101_122_dialog_content = "¡Señora Sheol, cuidado! Esos soldados—",
  ui_story_5071_50711101_123_dialog_content = "¡Tienen cómplices! Ellos—",
  ui_story_5071_50711101_124_dialog_content = "¡Cállate!",
  ui_story_5071_50711101_125_dialog_content = "Recuerda lo que dijo el jefe. No dejes sobrevivientes.",
  ui_story_5071_50711101_126_dialog_content = "¡Esto no es bueno! <size=45>¡Todos, prepárense para la batalla!</size>",
  ui_story_5071_50711102_1_dialog_content = "El personal de seguridad está todo...",
  ui_story_5071_50711102_2_dialog_content = "Parece que todos fueron masacrados. *suspiro*",
  ui_story_5071_50711102_3_dialog_content = "Es bueno que estemos de este lado...",
  ui_story_5071_50711102_4_dialog_content = "¿Estás bien, jefe? ¡Mira por la ventana, estoy aquí!",
  ui_story_5071_50711102_5_dialog_content = "Te envié para asegurarme de que la gente esté a salvo. ¿Qué haces de vuelta aquí?",
  ui_story_5071_50711102_6_dialog_content = "Noté a los malos actuando sospechosamente y me preocupé por ti.",
  ui_story_5071_50711102_7_dialog_content = "Entonces, ¿tienes todo bajo control, jefe?",
  ui_story_5071_50711102_8_dialog_content = "... Ven y saca a la gente de aquí.",
  ui_story_5071_50711102_9_dialog_content = "No voy a mencionar a PlayerName, pero ¿por qué te quedas, Vergil?",
  ui_story_5071_50711102_10_dialog_content = "¿Eh? Esta es tu nave, ¿no es así, jefe?",
  ui_story_5071_50711102_11_dialog_content = "¿Cuál es el problema? Todavía estoy en el reloj, así que debería comportarme lo mejor posible, ¿verdad?",
  ui_story_5071_50711102_12_dialog_content = "...",
  ui_story_5071_50711102_13_dialog_content = "Acabo de revisar esos manuscritos, Señor Sombrío.",
  ui_story_5071_50711102_14_dialog_content = "La historia escrita en ellos es muy parecida a la tuya, pero aún así no la creo.",
  ui_story_5071_50711102_15_dialog_content = "Así que tengo que preguntar, ¿realmente hiciste todas esas cosas? ¿A Lady Melissa—?",
  ui_story_5071_50711102_16_dialog_content = "¡PlayerName!",
  ui_story_5071_50711102_17_dialog_content = "Es incorrecto de tu parte eludirme y hacer responsable al culpable.",
  ui_story_5071_50711102_18_dialog_content = "L-Lo siento...",
  ui_story_5071_50711102_19_dialog_content = "Aunque ahora no es el momento de discutirlo.",
  ui_story_5071_50711102_20_dialog_content = "Todavía estamos en el dirigible, y tenemos que lidiar con la avería primero.",
  ui_story_5071_50711102_21_dialog_content = "Cuando esto termine, puedes apostar que conseguiré mi venganza con intereses.",
  ui_story_5071_50711102_22_dialog_content = "Te esperaré.",
  ui_story_5071_50711102_23_dialog_content = "Por cierto, eres una persona generosa, ¿no es así, Señor de las Sombras?",
  ui_story_5071_50711102_24_dialog_content = "Obviamente, te esforzaste mucho e hiciste muchos favores por ellos.",
  ui_story_5071_50711102_25_dialog_content = "Solo para que te abandonen y huyan ante el más mínimo estímulo.",
  ui_story_5071_50711102_26_dialog_content = "¡Oye! ¿Por qué también estás siendo críptica, Señora Sheol?",
  ui_story_5071_50711102_27_dialog_content = "¡Basta ya! Este no es el momento para pelear entre nosotros. Tenemos que unirnos.",
  ui_story_5071_50711102_28_dialog_content = "Me encantaría entrevistar al Señor de las Sombras ahora, pero no siento que sea el momento adecuado...",
  ui_story_5071_50711102_29_dialog_content = "Señor Sombrío, ¿qué deberíamos hacer ahora?",
  ui_story_5071_50711102_30_dialog_content = "Aprecio a todos ustedes por mantener la fe en mí.",
  ui_story_5071_50711102_31_dialog_content = "Mi gente te devolverá de manera segura al suelo.",
  ui_story_5071_50711102_32_dialog_content = "Seleucid, envía aeronaves para evacuar a los pasajeros.",
  ui_story_5071_50711102_33_dialog_content = "Esas sombras del pasado me persiguen.",
  ui_story_5071_50711102_34_dialog_content = "Acompañarás a los pasajeros a desembarcar de este barco.",
  ui_story_5071_50711102_35_dialog_content = "Jefe...",
  ui_story_5071_50711102_36_dialog_content = "Es una orden.",
  ui_story_5071_50711102_37_dialog_content = "Entiendo...",
  ui_story_5071_50711102_38_dialog_content = "Este es Bethel. Entra.",
  ui_story_5071_50711102_39_dialog_content = "Papá, vimos sospechosos en la carretera de carga hacia Twin Pavilions Bay.",
  ui_story_5071_50711102_40_dialog_content = "Estaban enviando armas y mercenarios a Umbraton y han sido detenidos.",
  ui_story_5071_50711102_41_dialog_content = "¿Cómo va todo por tu parte? ¿El lanzamiento de la doncella se realizó sin problemas?",
  ui_story_5071_50711102_42_dialog_content = "Todo está bien por aquí, no te preocupes.",
  ui_story_5071_50711102_43_dialog_content = "Bethel, probablemente nuestros \"invitados\" traviesos volverán a casa.",
  ui_story_5071_50711102_44_dialog_content = "Como anfitrión, confío en que sabes cómo saludarlos.",
  ui_story_5071_50711102_45_dialog_content = "Entendido. Por favor, cuídate, padre.",
  ui_story_5071_50711102_46_dialog_content = "<color=#e8d9bb>Auge-</color>",
  ui_story_5071_50711102_47_dialog_content = "Esto es malo... El dirigible aún no ha recuperado su equilibrio.",
  ui_story_5071_50711102_48_dialog_content = "Todo el barco está temblando, y parece que estamos perdiendo impulso...",
  ui_story_5071_50711102_49_dialog_content = "Eres un piloto experimentado de Colossus, así que por favor no me asustes así, querido.",
  ui_story_5071_50711102_50_dialog_content = "Esto no debería estar sucediendo si las reparaciones ya están completas.",
  ui_story_5071_50711102_51_dialog_content = "Si la condición del dirigible sigue deteriorándose, vamos a seguir perdiendo altitud... ¡y nos estrellaremos en Umbraton!",
  ui_story_5071_50711102_52_dialog_content = "¡Señora Sheol! ¡Señora Sheol! Terribles noticias—",
  ui_story_5071_50711102_53_dialog_content = "Encontramos a nuestro equipo de ingeniería abajo. Todos han estado...",
  ui_story_5071_50711102_54_dialog_content = "¿Qué?",
  ui_story_5071_50711201_1_dialog_content = "Oh no, tenemos que ir a la sala de control principal ahora.",
  ui_story_5071_50711201_2_dialog_content = "¡Los pilotos todavía están allí!",
  ui_story_5071_50711201_3_dialog_content = "Este es-",
  ui_story_5071_50711201_4_dialog_content = "Llegamos demasiado tarde. Los pilotos están todos... y los paneles de control están destruidos.",
  ui_story_5071_50711201_5_dialog_content = "Esto va demasiado lejos...",
  ui_story_5071_50711201_6_dialog_content = "Debemos pensar en una forma de dar la vuelta a este dirigible.",
  ui_story_5071_50711201_7_dialog_content = "Un paso atrás de nuevo...",
  ui_story_5071_50711201_8_dialog_content = "...",
  ui_story_5071_50711201_9_dialog_content = "Espera, ¿qué es esto?",
  ui_story_5071_50711201_10_dialog_content = "¿Realmente hiciste que pareciera Soroz aquí?",
  ui_story_5071_50711201_11_dialog_content = "Pensé que solo estabas bromeando en ese momento...",
  ui_story_5071_50711201_12_dialog_content = "Si vienes a la ceremonia como mi invitado especial de honor...",
  ui_story_5071_50711201_13_dialog_content = "¡Haré que la sala de control sea un duplicado de la del Colossus!",
  ui_story_5071_50711201_14_dialog_content = "Entonces, ¿vienes?",
  ui_story_5071_50711201_X11_dialog_content = "No es difícil para mí en absoluto.",
  ui_story_5071_50711201_15_dialog_content = "Por supuesto, eres el truco principal en la promoción, después de todo.",
  ui_story_5071_50711201_16_dialog_content = "Entonces, ¿tal vez puedo pilotarlo?",
  ui_story_5071_50711201_17_dialog_content = "¡Eso es cierto! Eres el experto, así que haz lo que quieras.",
  ui_story_5071_50711201_18_dialog_content = "Solo necesito empezar a jugar, y debería funcionar como siempre—",
  ui_story_5071_50711201_19_dialog_content = "Eh—",
  ui_story_5071_50711201_20_dialog_content = "¡No hay respuesta!",
  ui_story_5071_50711201_21_dialog_content = "¡Estos sistemas de control son completamente diferentes a los de Soroz!",
  ui_story_5071_50711201_X21_dialog_content = "No tengo ni idea de cómo arreglarlo.",
  ui_story_5071_50711201_X22_dialog_content = "Es cierto, el panel no es de origen Caelestite sino una antigüedad que compré.",
  ui_story_5071_50711201_22_dialog_content = "También están reventados.",
  ui_story_5071_50711201_23_dialog_content = "Eso es porque es solo un truco... No funciona, ya veo.",
  ui_story_5071_50711201_24_dialog_content = "Pero cómo...",
  ui_story_5071_50711201_25_dialog_content = "¿Antigüedad, dijiste?",
  ui_story_5071_50711201_26_dialog_content = "¡Y he visto este tipo de panel de control antiguo antes, a todos!",
  ui_story_5071_50711201_27_dialog_content = "¿Sabes cómo funciona? ¿Puedes arreglarlo?",
  ui_story_5071_50711201_28_dialog_content = "Dame algo de tiempo, y debería poder restaurarlo.",
  ui_story_5071_50711201_29_dialog_content = "¿Todavía tenemos tiempo?",
  ui_story_5071_50711201_30_dialog_content = "Parece que estamos cayendo más y más rápido.",
  ui_story_5071_50711201_31_dialog_content = "¡Espera! Si este dirigible realmente es una réplica del Coloso, entonces su estructura...",
  ui_story_5071_50711201_32_dialog_content = "¡Tengo una idea, todos!",
  ui_story_5071_50711201_33_dialog_content = "Si podemos cambiar la orientación de las alas desde el exterior, deberíamos poder reducir nuestra velocidad de descenso y realizar un aterrizaje de emergencia.",
  ui_story_5071_50711201_34_dialog_content = "¿Qué debemos hacer?",
  ui_story_5071_50711201_35_dialog_content = "¡Por favor ven conmigo!",
  ui_story_5071_50711201_36_dialog_content = "¡Toma esto, PlayerName!",
  ui_story_5071_50711201_37_dialog_content = "Es un manual abreviado para presentarte los esquemas del barco.",
  ui_story_5071_50711201_38_dialog_content = "Me quedaré aquí para proteger a Vergil y te dejaré a cargo del barco.",
  ui_story_5071_50711201_39_dialog_content = "Vamos.",
  ui_story_5071_50711201_40_dialog_content = "Espera, hay un problema más... Las alas del dirigible están expuestas. ¡Necesitaremos una lanzadera para acercarnos!",
  ui_story_5071_50711201_41_dialog_content = "¡Vamos a revisar la cubierta superior!",
  ui_story_5071_50711201_42_dialog_content = "PlayerName, Señor Sombrío, por favor...",
  ui_story_5071_50711201_X42_dialog_content = "¡Qué suerte, todavía queda una lanzadera!",
  ui_story_5071_50711201_44_dialog_content = "Veo que Seleucid ha dejado uno atrás.",
  ui_story_5071_50711201_45_dialog_content = "Levántate y dime qué hacer.",
  ui_story_5071_50711201_46_dialog_content = "Déjame echar un vistazo primero a los esquemas estructurales... ¡Ahí está!",
  ui_story_5071_50711201_47_dialog_content = "Tanto los dirigibles como los Colosos tienen alas. Aunque sus estructuras son diferentes, la lógica detrás de ellos es exactamente la misma.",
  ui_story_5071_50711201_48_dialog_content = "Al ajustar la articulación justo detrás del ala, podemos alterar la trayectoria del barco y hacer que gire.",
  ui_story_5071_50711201_49_dialog_content = "¡Espera!",
  ui_story_5071_50711201_50_dialog_content = "Ah—",
  ui_story_5071_50711201_51_dialog_content = "¿Es esta la \"ala\" de la que estabas hablando?",
  ui_story_5071_50711201_52_dialog_content = "Jaja, seguro que es más grande de lo que necesita ser.",
  ui_story_5071_50711201_53_dialog_content = "¿Estás seguro de que puedes cambiar la dirección?",
  ui_story_5071_50711201_54_dialog_content = "Intenta volarnos un poco más cerca para que pueda echar un vistazo más de cerca al mecanismo, ¡Señor Sombrío!",
  ui_story_5071_50711201_55_dialog_content = "Este es-",
  ui_story_5071_50711201_56_dialog_content = "¡Oh no, este mecanismo es mucho más rudimentario que los de los Colossus!",
  ui_story_5071_50711201_57_dialog_content = "Para crear alas que pudieran ser alimentadas por energía, abandonaron el diseño original. Estas alas no pueden ser ajustadas manualmente en absoluto...",
  ui_story_5071_50711201_58_dialog_content = "¡Jaja! Despreocupado y aspirante, ahora este es el <color=#FFB400>sueño</color> que todo joven debería tener!",
  ui_story_5071_50711201_59_dialog_content = "Comprensible—",
  ui_story_5071_50711201_60_dialog_content = "¡Las alas que llevan un sueño no cederán fácilmente!",
  ui_story_5071_50711201_61_dialog_content = "No te acerques más, o nos absorberá—",
  ui_story_5071_50711201_62_dialog_content = "¿Cómo voy a cambiar de dirección sin acercarme?",
  ui_story_5071_50711201_63_dialog_content = "¿Señor de las sombras?",
  ui_story_5071_50711201_64_dialog_content = "Tú, toma el control del pilotaje.",
  ui_story_5071_50711201_65_dialog_content = "¡Urgh!",
  ui_story_5071_50711201_66_dialog_content = "¡Estás siendo demasiado imprudente! Si metes tu mano en esos engranajes gigantes, tú—",
  ui_story_5071_50711201_67_dialog_content = "¡Dime hacia dónde girar, PlayerName!",
  ui_story_5071_50711201_68_dialog_content = "Tú—",
  ui_story_5071_50711201_69_dialog_content = "<color=#e8d9bb>Crujido—</color>",
  ui_story_5071_50711201_70_dialog_content = "(¡Increíble! De alguna manera, el Señor de las Sombras está soportando el peso de todo el ala...)",
  ui_story_5071_50711201_71_dialog_content = "¡Hacia tu izquierda! ¡Gira ese mecanismo y moverá el resto del ala!",
  ui_story_5071_50711201_72_dialog_content = "¡Haaaah!",
  ui_story_5071_50711201_73_dialog_content = "¡Intenta no caer—tan apresuradamente!",
  ui_story_5071_50711201_74_dialog_content = "Crujir—Crujir—",
  ui_story_5071_50711201_75_dialog_content = "(¡Se está moviendo—esa ala gigantesca realmente se está moviendo!)",
  ui_story_5071_50711201_76_dialog_content = "¡Lo hiciste, Señor de las Sombras! ¡Estamos cambiando de rumbo!",
  ui_story_5071_50711201_77_dialog_content = "Todavía no es suficiente—",
  ui_story_5071_50711201_78_dialog_content = "Tengo que alejarlo de Umbraton—",
  ui_story_5071_50711201_79_dialog_content = "¡Muévanse!",
  ui_story_5071_50711201_80_dialog_content = "Auge—",
  ui_story_5071_50711201_81_dialog_content = "¡Oh, no! ¡El motor trasero explotó!",
  ui_story_5071_50711201_82_dialog_content = "(¡A este ritmo, no podremos cambiar completamente de dirección antes de estrellarnos!)",
  ui_story_5071_50711201_83_dialog_content = "No es suficiente. Aún se estrellará en el borde de Umbraton...",
  ui_story_5071_50711201_84_dialog_content = "¡Regresa, Señor Sombrío! Si sigues así, tú—",
  ui_story_5071_50711201_85_dialog_content = "¡Levántate contra el viento!",
  ui_story_5071_50711201_86_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5071_50711201_87_dialog_content = "F-Fuegos artificiales?",
  ui_story_5071_50711201_88_dialog_content = "¿Quién diablos está lanzando fuegos artificiales en el dirigible ahora mismo...",
  ui_story_5071_50711201_89_dialog_content = "¡Oye, mira eso!",
  ui_story_5071_50711201_90_dialog_content = "¡El dirigible del gremio Cloudrover está volando hacia aquí!",
  ui_story_5071_50711201_91_dialog_content = "Esta es una de las celebraciones por el vuelo inaugural... ¡Simplemente no esperaba que estuviera tan cerca de nosotros!",
  ui_story_5071_50711201_92_dialog_content = "¡Qué maravillosos fuegos artificiales! Ese dirigible también es realmente espectacular.",
  ui_story_5071_50711201_93_dialog_content = "¡La Señora Sheol debe querer que también disfrutemos del evento!",
  ui_story_5071_50711201_94_dialog_content = "¡Oye, idiotas! ¿Por qué están parados ahí?",
  ui_story_5071_50711201_95_dialog_content = "¡Apúrate y sal de aquí! ¡El dirigible está a punto de estrellarse!",
  ui_story_5071_50711201_96_dialog_content = "¿Por qué la Pandilla Istvan es tan amenazante?",
  ui_story_5071_50711201_97_dialog_content = "¡Corre! ¡Escuché que el Señor de las Sombras inició una masacre y aniquiló a todos en la aeronave!",
  ui_story_5071_50711201_98_dialog_content = "¡Quieren estrellar el Dirigible Cloudrover en nuestros barrios bajos!",
  ui_story_5071_50711201_99_dialog_content = "¡Síguenos! Necesitamos refugiarnos fuera de la ciudad—",
  ui_story_5071_50711201_100_dialog_content = "¡Mantente lejos de nosotros! ¡No te hemos ofendido de ninguna manera!",
  ui_story_5071_50711201_101_dialog_content = "¡Vamos a empezar a atacar si te acercas más!",
  ui_story_5071_50711201_102_dialog_content = "¿Por qué estás tan paranoico con nosotros? ¡Oye, deja de tirar piedras a la gente!",
  ui_story_5071_50711201_103_dialog_content = "¡La pandilla Istvan está atacando a los civiles!",
  ui_story_5071_50711201_104_dialog_content = "<size=45>¡Oye!</size>",
  ui_story_5071_50711201_105_dialog_content = "Cálmense, todos... Ataquen una vez más y no tendremos más remedio que contraatacar.",
  ui_story_5071_50711201_106_dialog_content = "¿Por qué estos idiotas de repente...",
  ui_story_5071_50711201_107_dialog_content = "¡Debe ser la mujer que intentó causar problemas en el dirigible!",
  ui_story_5071_50711201_108_dialog_content = "¡Alto ahí!",
  ui_story_5071_50711201_109_dialog_content = "*suspiro* Tan imprudente como siempre, veo. Esto no será fácil de manejar ahora.",
  ui_story_5071_50711201_110_dialog_content = "Este es-",
  ui_story_5071_50711201_111_dialog_content = "¿Está cambiando de dirección el dirigible?",
  ui_story_5071_50711201_112_dialog_content = "Parecería que arreglaron el panel de control.",
  ui_story_5071_50711201_113_dialog_content = "Regresemos.",
  ui_story_5071_50711201_114_dialog_content = "Espera.",
  ui_story_5071_50711201_115_dialog_content = "Este botón activa los fuegos artificiales, este es para transmitir, y este es...",
  ui_story_5071_50711201_116_dialog_content = "¡Vergil! ¿Realmente lograste arreglar el panel de control?",
  ui_story_5071_50711201_117_dialog_content = "No realmente. Los controles direccionales están funcionando de nuevo, pero aún no podemos recuperar la altitud.",
  ui_story_5071_50711201_118_dialog_content = "Oh... Eso probablemente es porque uno de los motores explotó...",
  ui_story_5071_50711201_119_dialog_content = "Todavía se estrellará de esta manera...",
  ui_story_5071_50711201_120_dialog_content = "Si apuntamos bien y aterrizamos en el Río Dorado, tal vez el dirigible pueda permanecer intacto.",
  ui_story_5071_50711201_121_dialog_content = "¿Hacia dónde debería volar, Señora Sheol? ¿Hacia el río?",
  ui_story_5071_50711201_122_dialog_content = "Pero, ¿no sufrirán las personas a ambos lados del río?",
  ui_story_5071_50711201_123_dialog_content = "Movámonos hacia el valle. Nadie vive allí.",
  ui_story_5071_50711201_124_dialog_content = "Pero si hago eso, este dirigible se reducirá a un montón de chatarra.",
  ui_story_5071_50711201_125_dialog_content = "Es mi culpa que tu dirigible...",
  ui_story_5071_50711201_126_dialog_content = "¿Qué estás diciendo, Señor de las Sombras? Haces que parezca que eres el cerebro detrás de todo esto.",
  ui_story_5071_50711201_127_dialog_content = "...",
  ui_story_5071_50711201_128_dialog_content = "Explícame cómo volarlo y ustedes pueden irse.",
  ui_story_5071_50711201_129_dialog_content = "¿Señorita Sheol?",
  ui_story_5071_50711201_130_dialog_content = "Alguien tiene que volar esta cosa, ¿verdad? Sin mencionar que es mía.",
  ui_story_5071_50711201_131_dialog_content = "Entonces ustedes deberían—",
  ui_story_5071_50711201_132_dialog_content = "Vete y déjame volarlo.",
  ui_story_5071_50711201_133_dialog_content = "¿Señor Sombrío?",
  ui_story_5071_50711201_134_dialog_content = "¿Qué estás haciendo—",
  ui_story_5071_50711201_135_dialog_content = "Deja de intentar hacer el trabajo de otras personas, Señora Sheol.",
  ui_story_5071_50711201_136_dialog_content = "Por no mencionar que ya tengo experiencia con esto.",
  ui_story_5071_50711201_137_dialog_content = "Vete. Aquellos que anhelaban volar no deberían ver sus sueños destrozados en el cielo.",
  ui_story_5071_50711201_138_dialog_content = "Señor de las Sombras...",
  ui_story_5071_50711201_139_dialog_content = "Toma a los dos niños y regresa a un lugar seguro.",
  ui_story_5071_50711201_140_dialog_content = "... ¿Aún recuerdas el favor que me debes?",
  ui_story_5071_50711201_141_dialog_content = "No olvido mis promesas.",
  ui_story_5071_50711201_142_dialog_content = "Bueno. Los mantendré a salvo.",
  ui_story_5071_50711201_143_dialog_content = "A cambio, espero que cumplas tu promesa y satisfagas mi solicitud.",
  ui_story_5071_50711201_144_dialog_content = "Mi deseo es seguir con vida, tan simple como eso.",
  ui_story_5071_50711201_145_dialog_content = "... Lo prometo.",
  ui_story_5071_50711201_146_dialog_content = "No perdamos más tiempo. ¡Vamos!",
  ui_story_5071_50711201_147_dialog_content = "May la Sombra te vigile.",
  ui_story_5071_50711201_148_dialog_content = "<color=#FFB400>Valon</color>, vieja amiga... Pongamos más en este sueño...",
  ui_story_5071_50711202_1_dialog_content = "¡Por fin has vuelto, Sr. Borriman!",
  ui_story_5071_50711202_2_dialog_content = "No creo que sea necesario una presentación.",
  ui_story_5071_50711202_3_dialog_content = "¿L-Lady Bethel? Ah, ¿por qué has venido de repente?",
  ui_story_5071_50711202_4_dialog_content = "Ni siquiera nos notificaste—",
  ui_story_5071_50711202_5_dialog_content = "Atrapé a una banda de mercenarios armados fuera de la ciudad. Estaban intentando invadir Umbraton.",
  ui_story_5071_50711202_6_dialog_content = "Juzgando por sus vehículos, personal de apoyo y este testimonio...",
  ui_story_5071_50711202_7_dialog_content = "Sospechamos de tu Gremio del Pantera Roja, el Gremio del Loro Gris, y la Banda del Halcón Oxidado...",
  ui_story_5071_50711202_8_dialog_content = "... están entre los tres cómplices mínimos en este incidente.",
  ui_story_5071_50711202_9_dialog_content = "Aquí está la prueba fotográfica de que estás traficando armas ilegalmente.",
  ui_story_5071_50711202_10_dialog_content = "Me gustaría que vinieras con nosotros bajo el Reglamento de Seguridad de Umbraton.",
  ui_story_5071_50711202_11_dialog_content = "E-Espera un segundo. Debe haber habido algún tipo de malentendido.",
  ui_story_5071_50711202_12_dialog_content = "¡No puedes llevarme así!",
  ui_story_5071_50711202_13_dialog_content = "Solo una hora más. ¡No! Tal vez incluso otra media hora más o algo así...",
  ui_story_5071_50711202_14_dialog_content = "¿A qué te refieres con eso?",
  ui_story_5071_50711202_15_dialog_content = "Es como si tuvieras algo planeado...",
  ui_story_5071_50711202_16_dialog_content = "<size=45>=¡Ah</size=45>!",
  ui_story_5071_50711202_17_dialog_content = "¿Qué está pasando ahí fuera?",
  ui_story_5071_50711202_18_dialog_content = "¿Por qué hay caos por todas partes?",
  ui_story_5071_50711202_19_dialog_content = "Llévelo bajo custodia.",
  ui_story_5071_50711202_20_dialog_content = "¡Sí, señora!",
  ui_story_5071_50711202_21_dialog_content = "Bethel al gremio. ¿Qué está pasando?",
  ui_story_5071_50711202_22_dialog_content = "¡Señora Bethel, has vuelto!",
  ui_story_5071_50711202_23_dialog_content = "El Señor Sombrío es...",
  ui_story_5071_50711202_24_dialog_content = "Cálmate. ¿Qué le pasó a mi padre? ¡Dime!",
  ui_story_5071_50711202_25_dialog_content = "¡El dirigible en el que están Lady Sheol y él está a punto de estrellarse!",
  ui_story_5071_50711202_26_dialog_content = "¿Qué?",
  ui_story_5071_50711202_27_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5071_50711202_28_dialog_content = "¿Es eso... el sonido de la aeronave estrellándose?",
  ui_story_5071_50711202_29_dialog_content = "Señora Bethel, ¿qué debemos hacer?",
  ui_story_5071_50711202_30_dialog_content = "La cosa que cayó del dirigible parecía haber aterrizado en el pueblo.",
  ui_story_5071_50711202_31_dialog_content = "Alguien se está escondiendo entre la gente en la ciudad e incitando un motín. Mientras tanto, muchos mercenarios fuera de la ciudad están...",
  ui_story_5071_50711202_32_dialog_content = "Seleucid quisiera que ayudemos al Señor Sombrío, pero sin tu aprobación—",
  ui_story_5071_50711202_33_dialog_content = "Padre...",
  ui_story_5071_50711202_34_dialog_content = "Comprendo.",
  ui_story_5071_50711202_35_dialog_content = "Me envió lejos porque sintió un peligro inminente.",
  ui_story_5071_50711202_36_dialog_content = "¿Señora Betel?",
  ui_story_5071_50711202_37_dialog_content = "Cálmate, creo que no le pasará nada al Señor Sombrío.",
  ui_story_5071_50711202_38_dialog_content = "Además, da mi orden a todos en el gremio.",
  ui_story_5071_50711202_39_dialog_content = "¡Sí, señora!",
  ui_story_5071_50711202_40_dialog_content = "Alguien está poniendo sus ojos en Umbraton. No podemos entrar en pánico y darles una oportunidad.",
  ui_story_5071_50711202_41_dialog_content = "Entregaré la lista y la prueba a los Guardianos. Envía a Kleken a su sede central—",
  ui_story_5071_50711202_42_dialog_content = "Dígale que asista a los Guardianes en la captura de los culpables, y esté alerta ya que aprovecharán la oportunidad para escapar o resistir.",
  ui_story_5071_50711202_43_dialog_content = "¡Sí, señora!",
  ui_story_5071_50711202_44_dialog_content = "Dile a Seleucid que reúna las unidades de combate de los Guardianes y envíe la mitad a defender las afueras.",
  ui_story_5071_50711202_45_dialog_content = "Convoca a Patty y Patsy. Envíalas a ayudarme con el caos en la ciudad.",
  ui_story_5071_50711202_46_dialog_content = "Además, envía el refuerzo principal para ayudar a los residentes. ¡Luego envía dos unidades para buscar al Señor de las Sombras!",
  ui_story_5071_50711202_47_dialog_content = "Antes de que regrese, debemos mantener el orden y defender este lugar en su nombre, ¿entiendes?",
  ui_story_5071_50711202_48_dialog_content = "¡Sí, Lady Bethel!",
  ui_story_5071_50711202_49_dialog_content = "Creo en ti, padre, para que seas tu mismo como siempre...",
  ui_story_5071_50711202_50_dialog_content = "¡Y haz otro <color=#FFB400>regreso dorado</color>!",
  ui_story_5071_50711301_1_dialog_content = "Un dirigible tan hermoso... se fue así como así...",
  ui_story_5071_50711301_2_dialog_content = "¡El Señor de las Sombras lo logró! Aterrizó forzosamente en una parte deshabitada de la selva—",
  ui_story_5071_50711301_3_dialog_content = "Acércate antes de aterrizar, querido.",
  ui_story_5071_50711301_4_dialog_content = "Acabamos de estar en el aire, pero ahora...",
  ui_story_5071_50711301_5_dialog_content = "Los sueños de la gente en Umbraton nunca duran. No hay nada que puedas hacer al respecto.",
  ui_story_5071_50711301_6_dialog_content = "El fuego es tan feroz... No queda nada excepto restos quemados...",
  ui_story_5071_50711301_7_dialog_content = "Nada se salva, ni siquiera las preciosas obras de arte... ¿Q-Qué haremos ahora, Señorita Sheol?",
  ui_story_5071_50711301_8_dialog_content = "No me importa tanto mi colección personal como los artículos de subasta de los clientes, algunos de los cuales ni siquiera se pueden reproducir... Tendré que pagarlos de mi propio bolsillo.",
  ui_story_5071_50711301_9_dialog_content = "Señorita Sheol...",
  ui_story_5071_50711301_10_dialog_content = "Estoy bien, cariño. En los negocios, a veces se gana y a veces se pierde.",
  ui_story_5071_50711301_11_dialog_content = "Y aún no estoy totalmente en rojo. Vamos a buscar al Señor de las Sombras.",
  ui_story_5071_50711301_12_dialog_content = "H-Hace tanto calor... ¿Realmente podría el Señor Sombrío haber sobrevivido a algo así?",
  ui_story_5071_50711301_13_dialog_content = "Acechar en lugares invisibles es lo que la Sombra hace mejor. Debe estar vivo.",
  ui_story_5071_50711301_14_dialog_content = "¡Cuidado, Señora Sheol! ¡Las llamas son demasiado fuertes allí!",
  ui_story_5071_50711301_15_dialog_content = "(Todavía nada... No puedo sentir la presencia del Señor de las Sombras en ninguna parte.)",
  ui_story_5071_50711301_16_dialog_content = "¿Señor de las sombras? ¿Señor de las sombras?",
  ui_story_5071_50711301_17_dialog_content = "¿Estás duro de oído debido a la vejez? Deja de jugar juegos.",
  ui_story_5071_50711301_18_dialog_content = "(¿Qué va a pasar con Umbraton? Y Bethel... ¿Qué se supone que debo decirle...)",
  ui_story_5071_50711301_19_dialog_content = "Esto no va a funcionar, Señora Sheol! Por favor, salga antes de que todo se queme...",
  ui_story_5071_50711301_20_dialog_content = "Todavía tiene deudas pendientes conmigo. ¡Su crédito es demasiado bueno para salir corriendo!",
  ui_story_5071_50711301_21_dialog_content = "Pero Señora Sheol...",
  ui_story_5071_50711301_22_dialog_content = "No entiendo... ¿El Señor de las Sombras es una buena persona o una mala?",
  ui_story_5071_50711301_23_dialog_content = "Virgilio...",
  ui_story_5071_50711301_24_dialog_content = "Nunca es solo blanco o negro para los adultos.",
  ui_story_5071_50711301_25_dialog_content = "Pero él se arriesgó para salvarnos, eso es un hecho indiscutible.",
  ui_story_5071_50711301_26_dialog_content = "Pero el incendio... Tenemos que conseguir a alguien para apagar el fuego.",
  ui_story_5071_50711301_27_dialog_content = "¿Deberíamos decirle a Bethel?",
  ui_story_5071_50711301_28_dialog_content = "*suspiro* Bethel debe ser informado de esto.",
  ui_story_5071_50711301_29_dialog_content = "Especialmente cuando olí conspiración por todas partes.",
  ui_story_5071_50711301_30_dialog_content = "Es probable que la señorita Yvonne murió por envenenamiento, y los Guardias Lumo nos atacaron en el barco...",
  ui_story_5071_50711301_31_dialog_content = "El cerebro no me estaba apuntando a mí sino a Umbraton, o más específicamente, al Señor de las Sombras.",
  ui_story_5071_50711301_32_dialog_content = "El Señor de las Sombras mencionó \"Sombras del pasado\". ¿Quizás descubrió quién está detrás de esto?",
  ui_story_5071_50711301_33_dialog_content = "¿Sombra del pasado? Entonces creo que la señorita Hanstie tiene algo que decir al respecto.",
  ui_story_5071_50711301_34_dialog_content = "¡Espera, viene alguien!",
  ui_story_5071_50711301_35_dialog_content = "Bul—Bul—",
  ui_story_5071_50711301_36_dialog_content = "¿Es eso... un búho?",
  ui_story_5071_50711301_37_dialog_content = "Bien, los encontraste. Vuelve a mí ahora.",
  ui_story_5071_50711301_38_dialog_content = "Bul—Bul—",
  ui_story_5071_50711301_39_dialog_content = "¿Eres tú... Sra. Hanstie?",
  ui_story_5071_50711301_40_dialog_content = "(Ese búho... Algo parece muy familiar sobre él...)",
  ui_story_5071_50711301_41_dialog_content = "No puedo creer que este sea el lugar... Hace años había un Pozo impresionante aquí.",
  ui_story_5071_50711301_42_dialog_content = "También es el lugar donde ese traidor mató a su hermano.",
  ui_story_5071_50711301_43_dialog_content = "!",
  ui_story_5071_50711301_44_dialog_content = "¿Podría ser esto el destino? Estoy a tu lado una vez más, Valon.",
  ui_story_5071_50711301_45_dialog_content = "¡Y ese traidor logró aterrizar de emergencia también en este lugar!",
  ui_story_5071_50711301_46_dialog_content = "¡Parece que ni siquiera Umbraton lo salvará de esta última retribución que se merece!",
  ui_story_5071_50711301_47_dialog_content = "Ya no tendré que ensuciarme las manos más...",
  ui_story_5071_50711301_48_dialog_content = "Je... Jejejeje.",
  ui_story_5071_50711301_49_dialog_content = "Lo sabía. Eres la \"sombra del pasado\" del Señor de las Sombras, ¿verdad, Sra. Hanstie?",
  ui_story_5071_50711301_50_dialog_content = "¿Qué demonios pasó en ese entonces? Este lugar...",
  ui_story_5071_50711301_51_dialog_content = "¿No fue lo suficientemente clara la cuenta de ese escritor para ti?",
  ui_story_5071_50711301_52_dialog_content = "\"Con sangre fría, el traidor conocido como Kade asesinó a Valon, su querido hermano. Al hacerlo, le robó todo lo que era y traicionó a Umbraton.\"",
  ui_story_5071_50711301_53_dialog_content = "Como parte del pasado que buscaba erradicar, me han obligado a vivir fuera de la ciudad todos estos años.",
  ui_story_5071_50711301_54_dialog_content = "Sufrí una humillación indescriptible mientras me abría camino hasta la cima del mundo empresarial, todo para poder regresar a mi ciudad natal algún día—",
  ui_story_5071_50711301_55_dialog_content = "¡Y arrancaré la máscara de ese traidor con mis propias dos manos!",
  ui_story_5071_50711301_56_dialog_content = "¡No es digno del apellido de Valon! ¡No merece llamarse \"Istvan\"!",
  ui_story_5071_50711301_57_dialog_content = "Perdón por interrumpir—",
  ui_story_5071_50711301_58_dialog_content = "Las cosas estaban tan locas antes que no tuve la oportunidad de hablar...",
  ui_story_5071_50711301_59_dialog_content = "Me he estado preguntando algo todo este tiempo. ¿La Sra. Yvonne realmente escribió esos manuscritos que vimos con su propia mano?",
  ui_story_5071_50711301_60_dialog_content = "¿Qué estás diciendo, Virgilio?",
  ui_story_5071_50711301_61_dialog_content = "La Sra. Yvonne era muy apasionada por la escritura, y su caligrafía refleja eso. Su letra es generalmente muy libre, y cada palabra está escrita con muy poca preocupación por la estética.",
  ui_story_5071_50711301_62_dialog_content = "Pero esos últimos manuscritos fueron escritos meticulosamente, y la tinta era mucho más oscura. No solo eso, la forma y la intención detrás de las palabras eran completamente diferentes.",
  ui_story_5071_50711301_63_dialog_content = "Había... un cierto nivel de artesanía en ellos.",
  ui_story_5071_50711301_64_dialog_content = "También había un ligero aroma persistente en las páginas de esos manuscritos.",
  ui_story_5071_50711301_65_dialog_content = "... Esas pistas me dicen que fueron obra de \"A\", el maestro falsificador.",
  ui_story_5071_50711301_66_dialog_content = "Un aroma...",
  ui_story_5071_50711301_67_dialog_content = "¡Huele a <color=#FFB400>lirios</color>!",
  ui_story_5071_50711301_68_dialog_content = "\"Me encanta cómo la retratas: misteriosa, fuerte, desinhibida.\"",
  ui_story_5071_50711301_69_dialog_content = "\"Mi admiración por su silencioso papel de guardiana es la razón por la que amo tanto los lirios.\"",
  ui_story_5071_50711301_70_dialog_content = "\"Recuerdos eternos, amor insuperable y bendiciones profundas. Eso es lo que simbolizan los lirios.\"",
  ui_story_5071_50711301_71_dialog_content = "Sra. Hanstie...",
  ui_story_5071_50711301_72_dialog_content = "<color=#e8d9bb>La Sra. Hanstie sonríe ligeramente, sin negar ni reconocer nada.</color>",
  ui_story_5071_50711301_73_dialog_content = "<color=#e8d9bb>La verdad yace empapada en la tinta. A estas alturas, ¿importa si Yvonne o Hanstie lo escribieron?</color>",
  ui_story_5071_50711301_74_dialog_content = "Todos usamos máscaras diferentes. Si soy o no \"A\" no tiene efecto en el resultado.",
  ui_story_5071_50711301_75_dialog_content = "*sollozando* Pero ¿por qué harías esto? Yo... Yo siempre te he admirado...",
  ui_story_5071_50711301_76_dialog_content = "Bueno, la Sra. Yvonne mencionó que obtuvo la inspiración de un \"amigo artista\".",
  ui_story_5071_50711301_77_dialog_content = "Veo que ese amigo eres tú.",
  ui_story_5071_50711301_78_dialog_content = "Realmente eres del tipo práctico, haciendo todo por un viejo rencor.",
  ui_story_5071_50711301_79_dialog_content = "Como el daño colateral en tu plan, me gustaría saber si me compensarías por el dirigible y mis enormes pérdidas.",
  ui_story_5071_50711301_80_dialog_content = "Si tu sueño robado muere aquí, no tengo ningún remordimiento al respecto.",
  ui_story_5071_50711301_81_dialog_content = "Oh, mi querida Sra. Hanstie, eso en realidad fue mi sueño.",
  ui_story_5071_50711301_82_dialog_content = "No tiene nada que ver con las historias exageradas que te inventaste—",
  ui_story_5071_50711301_83_dialog_content = "Has estado tomando libertades empezando por cómo murió mi madre, ¿no es así?",
  ui_story_5071_50711301_84_dialog_content = "Quizás sea cierto—",
  ui_story_5071_50711301_85_dialog_content = "O quizás no es más que un rumor.",
  ui_story_5071_50711301_86_dialog_content = "De cualquier manera, tales rumores no se habrían difundido en primer lugar si no hubiera habido ninguna prueba.",
  ui_story_5071_50711301_87_dialog_content = "No tengo absolutamente ningún interés en la verdad sobre Lady Melissa. Estoy satisfecho siempre y cuando pueda seguir utilizando los rumores sobre ella.",
  ui_story_5071_50711301_88_dialog_content = "Sí, todos deberían poder ver ahora el verdadero rostro de Kade.",
  ui_story_5071_50711301_89_dialog_content = "No—",
  ui_story_5071_50711301_90_dialog_content = "¡Esto... Esto no tiene sentido!",
  ui_story_5071_50711301_91_dialog_content = "¿Y qué sabrías tú, niño?",
  ui_story_5071_50711301_92_dialog_content = "Hablas constantemente de mostrar a la gente la verdad sobre el pasado. ¿Por qué el pasado de Lady Mercury debería ser diferente?",
  ui_story_5071_50711301_93_dialog_content = "Sabes lo importante que es para la Señora Sheol aprender sobre su mamá...",
  ui_story_5071_50711301_94_dialog_content = "Pero solo estás usando ese conocimiento como una moneda de cambio para lastimar a otras personas—",
  ui_story_5071_50711301_95_dialog_content = "¡Cómo puedes ser tan egoísta!",
  ui_story_5071_50711301_96_dialog_content = "PlayerName...",
  ui_story_5071_50711301_97_dialog_content = "¡Basta!",
  ui_story_5071_50711301_98_dialog_content = "Ganas tu sustento haciendo productos falsificados, pero simplemente no puedes resistirte a dejar tu propia marca en ellos.",
  ui_story_5071_50711301_99_dialog_content = "Para obtener tu venganza, recurres a los medios más crueles y despreciables—",
  ui_story_5071_50711301_100_dialog_content = "Puede que quieras exponer el pasado del Señor de las Sombras, pero no hay ni un ápice de verdad detrás de tus acciones.",
  ui_story_5071_50711301_101_dialog_content = "Alguien tan egoísta y arrogante como tú solo apuntaría al Señor Sombrío para servir a sus propios intereses...",
  ui_story_5071_50711301_102_dialog_content = "¡He dicho suficiente, mocoso inútil!",
  ui_story_5071_50711301_103_dialog_content = "Ven ahora, eso está por debajo de ti, Lady Hanstie.",
  ui_story_5071_50711301_104_dialog_content = "Ves, incluso asustaste a Vergil.",
  ui_story_5071_50711301_105_dialog_content = "La señora Yvonne fue envenenada hasta morir.",
  ui_story_5071_50711301_106_dialog_content = "He visto un tipo similar de veneno antes...",
  ui_story_5071_50711301_107_dialog_content = "Me he cansado de escuchar tus palabras.",
  ui_story_5071_50711301_108_dialog_content = "Parece que no hay forma de disuadir a ustedes, tercos tontos, de este camino erróneo.",
  ui_story_5071_50711301_109_dialog_content = "No tengo más opción que enterrar a algunos subordinados más de Kade en el lugar de descanso de Valon.",
  ui_story_5071_50711301_110_dialog_content = "¡Salgan, hombres!",
  ui_story_5071_50711301_111_dialog_content = "Poniéndote serio ahora, ya veo.",
  ui_story_5071_50711301_112_dialog_content = "Hemos sido rodeados...",
  ui_story_5071_50711301_113_dialog_content = "Creo que es hora de que hagas lo que mejor haces, cariño.",
  ui_story_5071_50711301_114_dialog_content = "Solo te he visto navegar a otros antes. ¡Permíteme experimentarlo en persona hoy!",
  ui_story_5071_50711301_115_dialog_content = "¡Consigue a Virgilio y párate detrás de mí!",
  ui_story_5071_50711301_116_dialog_content = "No puedo permitirme perder a mi mejor cliente y empleado.",
  ui_story_5071_50711302_1_dialog_content = "Están consiguiendo más refuerzos. Eso no es bueno.",
  ui_story_5071_50711302_2_dialog_content = "No vamos a durar incluso con tu presencia, querida.",
  ui_story_5071_50711302_3_dialog_content = "Bethel y los demás deben haber notado un alboroto tan grande. Estoy seguro de que ya están en camino...",
  ui_story_5071_50711302_4_dialog_content = "Me temo que no podemos aguantar hasta entonces.",
  ui_story_5071_50711302_5_dialog_content = "Soy una empresaria, no una luchadora, pero nos hemos quedado sin opciones...",
  ui_story_5071_50711302_6_dialog_content = "PlayerName, Vergil, ustedes dos vayan a buscar al Señor de las Sombras. Yo me encargaré de ellos.",
  ui_story_5071_50711302_7_dialog_content = "Pero-",
  ui_story_5071_50711302_8_dialog_content = "¡Ten fe en él! Nunca he visto a nadie más comprometido con sus promesas que él en todos mis años de negocio.",
  ui_story_5071_50711302_9_dialog_content = "Por favor, cree en él y en ti mismo, PlayerName.",
  ui_story_5071_50711302_10_dialog_content = "Solo tú puedes encontrarlo en este caos. ¡No te rindas!",
  ui_story_5071_50711302_11_dialog_content = "... Entiendo.",
  ui_story_5071_50711302_12_dialog_content = "Vamos, Virgilio.",
  ui_story_5071_50711302_13_dialog_content = "¿Se van tan pronto?",
  ui_story_5071_50711302_14_dialog_content = "¿Cuál es la prisa, Sra. Hanstie? Todavía tenemos asuntos pendientes.",
  ui_story_5071_50711302_15_dialog_content = "Es bajo mentir sobre la madre de alguien, sabes.",
  ui_story_5071_50711302_16_dialog_content = "Como era de esperar de la hija de la Sra. Mercurio Rojo, tu temperamento no es diferente al de ella.",
  ui_story_5071_50711302_17_dialog_content = "Aunque la admiraba mucho, nunca me he preocupado por ti en mi vida.",
  ui_story_5071_50711302_18_dialog_content = "Entonces, ¿qué hice mal y debería disculparme?",
  ui_story_5071_50711302_19_dialog_content = "Realmente eres un tonto descarado.",
  ui_story_5071_50711302_20_dialog_content = "Puedes saber un poco de negocios ahora, pero tu vista sigue siendo tan pobre como siempre.",
  ui_story_5071_50711302_21_dialog_content = "Desde la última vez, no has hecho nada más que interponerte en mi camino.",
  ui_story_5071_50711302_22_dialog_content = "¿Última vez? Ahora tengo que preguntar cuándo fue eso.",
  ui_story_5071_50711302_23_dialog_content = "... Esos fueron desprecios triviales, pero tu mayor pecado fue pensar que podrías robar descaradamente el sueño de otra persona.",
  ui_story_5071_50711302_24_dialog_content = "¡Soy la única persona que puede continuar con el sueño de Valon!",
  ui_story_5071_50711302_25_dialog_content = "¡No eres digno!",
  ui_story_5071_50711302_26_dialog_content = "PlayerName tiene razón. Ya eres líder de una guild, pero aún eres más egocéntrico que un niño.",
  ui_story_5071_50711302_27_dialog_content = "Tú y Kade realmente no son diferentes el uno del otro, no me contendré contra ti sin importar cuánto te parezcas a tu madre.",
  ui_story_5071_50711302_28_dialog_content = "Te destruiré, junto con Kade y tu preciado Gremio de Explorador Nublar—",
  ui_story_5071_50711302_29_dialog_content = "¡Haré que todos ustedes se estrellen contra el <color=#FFB400>suelo</color>!",
  ui_story_5071_50711302_30_dialog_content = "Está bien... Ya que ya me has destrozado, ¿qué más daño podría hacerle a mi imagen?",
  ui_story_5071_50711302_31_dialog_content = "(Señor de las Sombras... ¿Realmente estás vivo ahí fuera? Si es así, ¿dónde estás?)",
  ui_story_5071_50711302_32_dialog_content = "(¿O la Señorita Sheol solo estaba tratando de ganarnos tiempo para escapar?)",
  ui_story_5071_50711302_33_dialog_content = "(Por favor, déjame escuchar tu voz... o si no—)",
  ui_story_5071_50711302_34_dialog_content = "*tosiendo* El-El humo—se está volviendo demasiado espeso—",
  ui_story_5071_50711302_35_dialog_content = "Lo siento, Vergil... Pero tengo que seguir buscando al Señor de las Sombras. Deberías volver a Umbraton y pedir refuerzos.",
  ui_story_5071_50711302_36_dialog_content = "No puedo hacer eso. La señorita Sheol nos pidió a ambos que lo buscáramos.",
  ui_story_5071_50711302_37_dialog_content = "Ella dijo que el Señor de las Sombras siempre cumple sus promesas, ¡así que también creería en él!",
  ui_story_5071_50711302_38_dialog_content = "Virgilio... ¿Eh?",
  ui_story_5071_50711302_39_dialog_content = "¡(Siento una mezcla de emociones poderosas y caóticas, y viene desde lo más profundo de las llamas!)",
  ui_story_5071_50711302_40_dialog_content = "Virgilio, necesitamos atravesar estas llamas—",
  ui_story_5071_50711302_41_dialog_content = "¡Ay—E-Espérame!",
  ui_story_5071_50711302_42_dialog_content = "(Señor Sombrío... Si realmente estás ahí, por favor di algo—)",
  ui_story_5071_50711302_43_dialog_content = "¡Señor de las sombras... Señor de las sombras!",
  ui_story_5071_50711302_44_dialog_content = "Señor Sombrío—",
  ui_story_5071_50711302_45_dialog_content = "¿PlayerName?",
  ui_story_5071_50711302_46_dialog_content = "¡Realmente eres tú! Gracias a Dios que estás... ¿Eh?",
  ui_story_5071_50711302_47_dialog_content = "¡Cuidado atrás de ti!",
  ui_story_5071_50711302_48_dialog_content = "No—",
  ui_story_5071_50711302_49_dialog_content = "No te preocupes, están fuera.",
  ui_story_5071_50711302_50_dialog_content = "Esos tipos eran realmente persistentes. ¿Se estaban escondiendo aquí todo el tiempo?",
  ui_story_5071_50711302_51_dialog_content = "No puedo creer que incluso te encontraron antes que a nosotros.",
  ui_story_5071_50711302_52_dialog_content = "El deseo de la Sra. Hanstie de erradicar todo es aterrador. Está yendo con todo contra nosotros.",
  ui_story_5071_50711302_53_dialog_content = "Deja que haga lo suyo...",
  ui_story_5071_50711302_54_dialog_content = "¿Señor Sombrío?",
  ui_story_5071_50711302_55_dialog_content = "Me siento... un poco cansado—",
  ui_story_5071_50711302_56_dialog_content = "Parece que estás sufriendo mucho. ¿Estás herido?",
  ui_story_5071_50711302_57_dialog_content = "*tose*",
  ui_story_5071_50711302_58_dialog_content = "¡Ven con nosotros! ¡El humo se está volviendo demasiado denso por aquí!",
  ui_story_5071_50711302_59_dialog_content = "No es humo.",
  ui_story_5071_50711302_60_dialog_content = "¿No es humo? ¿Entonces qué son estos vapores negros?",
  ui_story_5071_50711302_61_dialog_content = "(Espera, esta niebla negra... ¿Es la misma que el <color=#FFB400>veneno de Arte</color> de antes?)",
  ui_story_5071_50711302_62_dialog_content = "Jeje, ¿así que finalmente lo descubriste?",
  ui_story_5071_50711302_63_dialog_content = "Te dejé vivo para poder escucharte confesar eventualmente—",
  ui_story_5071_50711302_64_dialog_content = "Así que olvídate de la charla.",
  ui_story_5071_50711302_65_dialog_content = "Esto es solo... la forma de la señorita Hanstie de tocar la puerta.",
  ui_story_5071_50711302_66_dialog_content = "Los vapores han estado persistiendo desde que empezamos a pelear entre nosotros.",
  ui_story_5071_50711302_67_dialog_content = "Cuanto más luchaste, más inhalaste.",
  ui_story_5071_50711302_68_dialog_content = "Aunque la mayoría fue quemada por el fuego, no hay forma de saber cuánto ya has respirado...",
  ui_story_5071_50711302_69_dialog_content = "¡Entrégate el antídoto!",
  ui_story_5071_50711302_70_dialog_content = "¿Pensé que los Lobos Negros habían sido exterminados? ¿Cómo siguen produciendo este veneno?",
  ui_story_5071_50711302_71_dialog_content = "\"¿Veneno\"? Jajaja—creo que estás equivocado, amigo.",
  ui_story_5071_50711302_72_dialog_content = "Además, los Lobos Negros no eran más que una pandilla de cachorros inútiles.",
  ui_story_5071_50711302_73_dialog_content = "¿Cuál es tu conexión con los Lobos Negros? Y Arte y Hanstie...",
  ui_story_5071_50711302_74_dialog_content = "No importa, solo danos el antídoto—",
  ui_story_5071_50711302_75_dialog_content = "No te preocupes, PlayerName... Ellos también inhalaron la niebla.",
  ui_story_5071_50711302_76_dialog_content = "Si fuera tóxico, morirían más rápido dada su debilidad.",
  ui_story_5071_50711302_77_dialog_content = "Je, como era de esperar del famoso Señor Sombrío. Incluso en esta condición, sigues perfectamente tranquilo.",
  ui_story_5071_50711302_78_dialog_content = "Creo que estás a punto de llegar a la parte del soliloquio donde revelas la trama.",
  ui_story_5071_50711302_79_dialog_content = "No dejes que tu oportunidad de ser escuchado se escape, payaso torpe.",
  ui_story_5071_50711302_80_dialog_content = "Humph—Solo estábamos siguiendo las órdenes de la Sra. Hanstie, pero esto es exactamente lo que todos queremos.",
  ui_story_5071_50711302_81_dialog_content = "Puedes sentirlo ahora, ¿verdad? Una sensación de inquietud que viene desde lo más profundo, una sensación de violencia.",
  ui_story_5071_50711302_82_dialog_content = "Ese es el efecto de nuestra niebla negra modificada. Ya no te mata, simplemente te llena de ira y te hace ceder a tus impulsos más salvajes.",
  ui_story_5071_50711302_83_dialog_content = "En esa condición, nadie puede posiblemente reprimir sus deseos más profundos.",
  ui_story_5071_50711302_84_dialog_content = "No me digas que ustedes—",
  ui_story_5071_50711302_85_dialog_content = "¡Es cierto! Nuestro objetivo es usarlo para liberar a la bestia que se esconde debajo de la máscara de Istvan!",
  ui_story_5071_50711302_86_dialog_content = "<size=50>¡El demonio del Pozo—Kade!</size>",
  ui_story_5071_50711302_87_dialog_content = "¡Vamos a sacar al monstruo enterrado profundamente en tu corazón!",
  ui_story_5071_50711302_88_dialog_content = "¡Todos aquellos que acudan en tu rescate sabrán exactamente lo que eres!",
  ui_story_5071_50711302_89_dialog_content = "¡Ahora muéstrales! ¡Muéstrale a la gente que dices amar la horrenda locura de tu alma!",
  ui_story_5071_50711302_90_dialog_content = "¡Vosotros...! Sois los únicos locos por aquí.",
  ui_story_5071_50711302_91_dialog_content = "Entrégame el antídoto, no importa, simplemente lo tomaré de ti mismo...",
  ui_story_5071_50711302_92_dialog_content = "Con mi poder, no tendré ningún problema en encontrar el antídoto en tu persona—",
  ui_story_5071_50711302_93_dialog_content = "¿Ah?",
  ui_story_5071_50711302_94_dialog_content = "!(Su presencia... ¡Desapareció completamente!)",
  ui_story_5071_50711302_95_dialog_content = "¡Oye! ¡Despierta! Tú—",
  ui_story_5071_50711302_96_dialog_content = "...",
  ui_story_5071_50711302_97_dialog_content = "Puedes parar ahora, PlayerName.",
  ui_story_5071_50711302_98_dialog_content = "Terminó su vida.",
  ui_story_5071_50711302_99_dialog_content = "No llevaban antídoto consigo porque estaban listos para morir.",
  ui_story_5071_50711302_100_dialog_content = "¡Todavía hay otros! Necesitamos detenerlos de...",
  ui_story_5071_50711302_101_dialog_content = "(¿Qué está pasando? Aunque estamos rodeados por un infierno furioso... las llamas de la vida se están apagando, una por una...)",
  ui_story_5071_50711302_102_dialog_content = "¡Deténgase! No hagas esto más, o todos ustedes—",
  ui_story_5071_50711302_103_dialog_content = "Waaah—",
  ui_story_5071_50711302_104_dialog_content = "PlayerName, estoy muy feliz de que—",
  ui_story_5071_50711302_105_dialog_content = "Un joven como tú lamentaría al enemigo.",
  ui_story_5071_50711302_106_dialog_content = "Pero también lamento decir que probablemente la mayoría de las personas aquí son...",
  ui_story_5071_50711302_107_dialog_content = "¿Cómo... Cómo pudieron hacerse esto a sí mismos sin dudarlo? Y de una manera tan horrible—",
  ui_story_5071_50711302_108_dialog_content = "Creo que ya sabías la respuesta.",
  ui_story_5071_50711302_109_dialog_content = "Esto es-!",
  ui_story_5071_50711302_110_dialog_content = "El escudo de la familia Gambi... de aquel entonces...",
  ui_story_5071_50711302_111_dialog_content = "Una familia que destruí—",
  ui_story_5071_50711302_112_dialog_content = "Todos llevan algo similar.",
  ui_story_5071_50711302_113_dialog_content = "Este es Colo, ese es Luka, y ese pertenece a los Bonas...",
  ui_story_5071_50711302_114_dialog_content = "Veo que los líderes que se ahogaron en el Pozo dejaron todas sus sombras atrás—",
  ui_story_5071_50711302_115_dialog_content = "Aquí es donde finalmente llegan las sombras del pasado.",
  ui_story_5071_50711302_116_dialog_content = "Urgh... Hay una sensación de ardor en mi pecho...",
  ui_story_5071_50711302_117_dialog_content = "Un impulso que me impulsa a quemar... a destruir todo...",
  ui_story_5071_50711302_118_dialog_content = "Tu cara...",
  ui_story_5071_50711302_119_dialog_content = "Imagino que no parezco agradable. Entonces, ¿parezco bárbaro?",
  ui_story_5071_50711302_120_dialog_content = "(Qué expresión tan aterradora... Incluso sus venas son completamente visibles. No se parece en nada al Señor Sombrío de antes...)",
  ui_story_5071_50711302_121_dialog_content = "Deberíamos irnos, Señor Sombrío—",
  ui_story_5071_50711302_122_dialog_content = "Si no podemos encontrar el antídoto aquí, estoy seguro de que podemos encontrar algo en Umbraton...",
  ui_story_5071_50711302_123_dialog_content = "¡De cualquier manera, necesitamos alejarnos de estas llamas!",
  ui_story_5071_50711302_124_dialog_content = "Tienes razón, pero... Urgh—",
  ui_story_5071_50711302_125_dialog_content = "¡Solo apóyate en mí! ¡Nos sacaré de aquí!",
  ui_story_5071_50711302_126_dialog_content = "El fuego en mí arde más caliente que el incendio aquí.",
  ui_story_5071_50711302_127_dialog_content = "Yo... no creo que pueda aguantar mucho más.",
  ui_story_5071_50711302_128_dialog_content = "Esto está destinado. Mi pasado me está alcanzando—",
  ui_story_5071_50711302_129_dialog_content = "Déjame y sal de aquí. No puedo permitir que te lastimen...",
  ui_story_5071_50711302_130_dialog_content = "¡Deja de decir algo así!",
  ui_story_5071_50711302_131_dialog_content = "¡Así es! ¡Todavía necesitamos que rescates a la Señora Sheol!",
  ui_story_5071_50711302_132_dialog_content = "También me gustaría cumplir mi promesa, pero... Urgh—",
  ui_story_5071_50711302_133_dialog_content = "Tienen razón. Siento que quiero destruir algo...",
  ui_story_5071_50711302_134_dialog_content = "¡Rápido! No estoy bromeando sobre esto. Yo...",
  ui_story_5071_50711302_135_dialog_content = "¡De ninguna manera, no te dejaré atrás! Estoy seguro de que hay otra manera—",
  ui_story_5071_50711302_136_dialog_content = "Dije, ¡sal de aquí! ¡Ahora!",
  ui_story_5071_50711302_137_dialog_content = "¡Déjame en paz!",
  ui_story_5071_50711302_138_dialog_content = "Esto es todo... Me conozco mejor de lo que tú me conoces.",
  ui_story_5071_50711302_139_dialog_content = "No...",
  ui_story_5071_50711302_140_dialog_content = "Tiene que haber otra manera.",
  ui_story_5071_50711302_141_dialog_content = "(¡Tiene que haber! Incluso si—)",
  ui_story_5071_50711302_142_dialog_content = "Lo siento. Sé que probablemente me culparás por esto más tarde, pero ahora no tengo otra opción.",
  ui_story_5071_50711302_143_dialog_content = "PlayerName...",
  ui_story_5071_50711302_144_dialog_content = "¡Vigílanos, Vergil! ¡Contamos contigo!",
  ui_story_5071_50711302_145_option_content = "¡Potencia de fuerza!",
  ui_story_5071_50711401_1_dialog_content = "¿Así que este es el mundo interior del Señor Sombrío? Hay tantas emociones conflictivas aquí...",
  ui_story_5071_50711401_2_dialog_content = "Recuerdo aquí, esto es—",
  ui_story_5071_50711401_3_dialog_content = "¿Esa era la voz del Señor de las Sombras?",
  ui_story_5071_50711401_4_dialog_content = "Cuando llegó la crisis de Darkover, representé a papá y a la asociación interina de gremios para negociar refuerzos de Lumopolis. Entonces...",
  ui_story_5071_50711401_5_dialog_content = "¿Dónde estás, Señor de las Sombras?",
  ui_story_5071_50711401_6_dialog_content = "Nunca imaginé que vería ese día de nuevo.",
  ui_story_5071_50711401_7_dialog_content = "No puede oírme... Si no puedo alcanzarlo así, entonces no tengo más opción que encontrar una ruptura en sus emociones.",
  ui_story_5071_50711401_8_dialog_content = "Pero, ¿a dónde se fue él...?",
  ui_story_5071_50711401_9_dialog_content = "Este lugar... ¿Es algún tipo de arena?",
  ui_story_5071_50711401_10_dialog_content = "... ¿Por qué hay tanta gente reunida aquí?",
  ui_story_5071_50711401_11_dialog_content = "También me asusté mucho... ¿Puedes recordar la última vez que se reunieron tantos jefes?",
  ui_story_5071_50711401_12_dialog_content = "¿Son... Son todos estos personas miembros de una pandilla?",
  ui_story_5071_50711401_13_dialog_content = "Ya que todos están dispuestos a venir y hablar individualmente, quiero escuchar lo que todos tienen que decir.",
  ui_story_5071_50711401_14_dialog_content = "Escuché que el viejo Istvan y varias gremios han conspirado para traicionar a Umbraton, y <color=#FFB400>su hijo adoptivo pasará con ese bastón como prueba</color>.",
  ui_story_5071_50711401_15_dialog_content = "Quiero conseguir ese bastón y ordenar a la asociación de gremios que distribuya suministros y arme a todos para luchar contra los Eclipsites.",
  ui_story_5071_50711401_16_dialog_content = "¿Así que ellos son los que llamaron a todos esos nobles de Lumopolis? Esos chicos están completamente armados y estacionados afuera en una emergencia así. Creo que quieren mantenernos aquí.",
  ui_story_5071_50711401_17_dialog_content = "Esos chicos de Lumopolis siempre han estado buscando una oportunidad para ocupar Umbraton. Simplemente démosles lo que quieren y abandonemos este lugar.",
  ui_story_5071_50711401_18_dialog_content = "¡Pero esta es nuestra casa!",
  ui_story_5071_50711401_19_dialog_content = "No digas eso. No considero estas alcantarillas apestosas como mi hogar.",
  ui_story_5071_50711401_20_dialog_content = "¿Quieres pelear conmigo en el Pozo?",
  ui_story_5071_50711401_21_dialog_content = "¡No estoy de acuerdo con que esos chicos de Lumopolis se paseen por nuestro territorio así como así! ¿No abandonaron ya Umbraton y se fueron a casa porque tenían miedo del ejército Eclipsite? ¿Por qué han regresado?",
  ui_story_5071_50711401_22_dialog_content = "Ya los despedimos una vez, ¿y ahora quieren acuartelar sus fuerzas aquí? ¿Es eso justo?",
  ui_story_5071_50711401_23_dialog_content = "¡Dejemos de discutir! Si me preguntas, deberíamos trabajar juntos para sacar dinero de esto. Esas personas pobres en el pueblo no tienen nada que ver con nosotros, así que exprimamos tanto dinero como podamos de ellos y usemos ese dinero para halagar a esos tipos de Lumopolis.",
  ui_story_5071_50711401_24_dialog_content = "Tienes razón. Ya que todos estamos aquí, deberíamos simplemente robar esos gremios—",
  ui_story_5071_50711401_25_dialog_content = "¡Mi patrocinador está entre ellos!",
  ui_story_5071_50711401_26_dialog_content = "Este es el Pit. Propongo que usemos las reglas más antiguas para decidir quién se queda con el bastón.",
  ui_story_5071_50711401_27_dialog_content = "¿No podemos trabajar todos juntos? Todavía no sabemos cuántas personas escoltarán al personal.",
  ui_story_5071_50711401_28_dialog_content = "Quien sobreviva hasta el final puede liderar a nuestros hombres para tomarlo. Es tan simple como eso.",
  ui_story_5071_50711401_29_dialog_content = "En tus ojos, ¿es ese personal más importante que Umbraton?",
  ui_story_5071_50711401_30_dialog_content = "¡Por supuesto! El Bastón de Shepherd representa al antiguo clan de Istvan e incluso se convierte en el símbolo de la asociación de gremios...",
  ui_story_5071_50711401_31_dialog_content = "<size=45>¡Eso es suficiente!</size>",
  ui_story_5071_50711401_32_dialog_content = "Lo más importante en este momento es el paradero de ese mocoso Kade y el personal. ¿Qué le está tomando tanto tiempo?",
  ui_story_5071_50711401_33_dialog_content = "¿Estas personas estaban a cargo de Umbraton en aquel entonces? Qué lugar tan horrible para estar...",
  ui_story_5071_50711401_34_dialog_content = "Necesito usar mis poderes para encontrar al Señor de las Sombras, y rápidamente...",
  ui_story_5071_50711401_35_dialog_content = "Escuché que el hijo de Istvan, Valon, lo está haciendo bastante bien y ya está administrando varios gremios.",
  ui_story_5071_50711401_36_dialog_content = "Incluso nos ha dado muchos beneficios. Me pregunto qué piensa sobre este ataque de Eclipsite.",
  ui_story_5071_50711401_37_dialog_content = "¡Ahí! Una versión más joven del Señor Sombrío se esconde en esa esquina—",
  ui_story_5071_50711401_38_dialog_content = "¿Eh? ¿Quién es esa persona delante de él?",
  ui_story_5071_50711401_39_dialog_content = "¿Lo escuchaste, Kade?",
  ui_story_5071_50711401_40_dialog_content = "Estos son los jefes de Umbraton que deseas salvar.",
  ui_story_5071_50711401_41_dialog_content = "No tengo tiempo para hablar de eso, Valon. Tenemos que irnos, ¡el tiempo no espera a nadie!",
  ui_story_5071_50711401_X41_dialog_content = "¿Valon? ¿Por qué solo hay un vago recuerdo de Valon en la memoria del Señor Sombrío?",
  ui_story_5071_50711401_42_dialog_content = "¡Ese joven Señor de la Ciudad me dijo que nos ayudaría a superar la crisis!",
  ui_story_5071_50711401_43_dialog_content = "El refuerzo está fuera de la puerta pero aún no ha hecho ningún movimiento, así que nos están dando más respeto de lo habitual.",
  ui_story_5071_50711401_44_dialog_content = "¡Solo tengo que ir a firmar el pacto, y lucharán junto a Umbraton contra el ejército de Eclipsite!",
  ui_story_5071_50711401_45_dialog_content = "Si te muestras ahora mismo, solo te atacarán. Quédate y habla conmigo un rato, y te ayudaré a idear un plan.",
  ui_story_5071_50711401_46_dialog_content = "No te preocupes, estamos a salvo aquí. Nadie nos escuchará.",
  ui_story_5071_50711401_47_dialog_content = "¿Cuáles son los términos de este pacto, Kade? ¿Qué estás dispuesto a dar a Lumopolis a cambio de su ayuda?",
  ui_story_5071_50711401_48_dialog_content = "¿Gente de Umbraton? ¿Comercio libre? ¿O son incluso más impuestos? ¡Ya han dejado atrás a Umbraton y solo empeorará si vuelven!",
  ui_story_5071_50711401_49_dialog_content = "¿Por qué traicionarías a Umbraton solo para arrastrarte ante Lumopolis? ¿Realmente has renunciado a nuestro sueño?",
  ui_story_5071_50711401_50_dialog_content = "Fue aprobado por nuestro padre así como por la asociación de gremios. Este bastón en mi mano y la carta firmada son la prueba.",
  ui_story_5071_50711401_51_dialog_content = "Esto representa su consentimiento unánime.",
  ui_story_5071_50711401_52_dialog_content = "¿Alguna vez preguntaste cómo se sienten las personas en el fondo de la sociedad de Umbraton, las que han sido oprimidas tanto por Lumopolis como por los gremios más grandes?",
  ui_story_5071_50711401_53_dialog_content = "Nuestra inteligencia dice que la horda de Eclipsites estará aquí en un día, pero las fuerzas independientes de Umbraton tienen cada una sus propias agendas.",
  ui_story_5071_50711401_54_dialog_content = "A pesar de todo, papá y la asociación fueron los primeros en acudir a Lumopolis en busca de protección. Mientras tanto, la familia Gambi y sus aliados comenzaron a aumentar el precio del boleto para el transporte fuera de la ciudad...",
  ui_story_5071_50711401_55_dialog_content = "Las personas más pobres de esta ciudad no tienen forma de defenderse o escapar. Todo lo que pueden hacer es sentarse y esperar a que llegue la muerte.",
  ui_story_5071_50711401_56_dialog_content = "¡Lo defenderemos juntos!",
  ui_story_5071_50711401_57_dialog_content = "Eso no es más que un pensamiento ilusorio de tu parte. La mayoría de las personas quieren abandonar Umbraton, pero me han informado que varias pandillas han comenzado a robarles mientras intentan escapar.",
  ui_story_5071_50711401_58_dialog_content = "Cualquiera con incluso un atisbo de fuerza continúa haciendo la vista gorda a los débiles y los que sufren. No sé por qué Umbraton tiene que ser así, pero esto es lo que es nuestro pueblo natal...",
  ui_story_5071_50711401_59_dialog_content = "Afortunadamente, estos matones son gente de Umbraton de principio a fin. Todo lo que se necesita es un poco de provocación para hacer hervir su sangre.",
  ui_story_5071_50711401_60_dialog_content = "Por eso he estado empujándolos desde las sombras, solo para que pudieran encontrar este lugar. Con unas pocas palabras bien elegidas y la promesa de recompensas, deberían volverse lo suficientemente cooperativos.",
  ui_story_5071_50711401_61_dialog_content = "¿Qué es exactamente lo que quieres?",
  ui_story_5071_50711401_62_dialog_content = "Te lo dije antes, Kade. He estado trabajando duro para aumentar mi fuerza.",
  ui_story_5071_50711401_63_dialog_content = "Voy a utilizar la invasión de Eclipsite para librar a Umbraton de su plaga, de una vez por todas.",
  ui_story_5071_50711401_64_dialog_content = "Todo lo que tenemos que hacer es sacrificar a estas personas, y podremos llevar a los inocentes a salvo fuera de la ciudad.",
  ui_story_5071_50711401_65_dialog_content = "Deberías estar a mi lado, purgando su pus podrido de la ciudad en lugar de pedir ayuda a la inmundicia de Lumopolis. Esto es lo que Umbraton realmente necesita ahora mismo.",
  ui_story_5071_50711401_66_dialog_content = "¿Por qué, Valon? Has cambiado...",
  ui_story_5071_50711401_67_dialog_content = "¿Por qué no pudiste unirlos contra los Eclipsites en lugar de dividirlos con luchas internas?",
  ui_story_5071_50711401_68_dialog_content = "¿Cuál es la diferencia entre tú y esos nobles sedientos de sangre que estaban aquí?",
  ui_story_5071_50711401_69_dialog_content = "Estos hombres son la escoria de Umbraton, los líderes de los criminales más repugnantes que corrompieron nuestra ciudad. Dejarlos vivir solo traerá daño a otras personas.",
  ui_story_5071_50711401_70_dialog_content = "Esta es nuestra única oportunidad, Kade. Ayúdame a deshacernos de ellos para que podamos llevar a los inocentes a un lugar seguro...",
  ui_story_5071_50711401_71_dialog_content = "¡Sus muertes son necesarias para la supervivencia de las personas más vulnerables de Umbraton!",
  ui_story_5071_50711401_72_dialog_content = "... ¿Y qué si huyeron?",
  ui_story_5071_50711401_73_dialog_content = "Lumopolis gobernaría Umbraton, y la gente aquí en el futuro se encontraría con los mismos problemas que nosotros.",
  ui_story_5071_50711401_74_dialog_content = "Y habría otro hijo demoníaco como yo, nacido en la sombra y rechazado por todos.",
  ui_story_5071_50711401_75_dialog_content = "Luego el ciclo comenzaría de nuevo.",
  ui_story_5071_50711401_76_dialog_content = "No ha sido fácil llegar a un acuerdo con Lumopolis, y debo aprovechar esta oportunidad para un diálogo igualitario...",
  ui_story_5071_50711401_77_dialog_content = "Parece que ya no hay forma de cambiar tu opinión...",
  ui_story_5071_50711401_78_dialog_content = "<size=45><color=#FFB400>¡Escuchen todos, Kade está aquí!</color></size>",
  ui_story_5071_50711401_79_dialog_content = "*silencio repentino*",
  ui_story_5071_50711401_80_dialog_content = "¡Valon! ¡Cómo pudiste!",
  ui_story_5071_50711401_81_dialog_content = "¿Oyes el sonido de todos esos pasos? ¡Ahora no tienes más opción que luchar contra todos ellos y ayudarme a liberar esta ciudad de su suciedad!",
  ui_story_5071_50711401_82_dialog_content = "Pero no te preocupes. Mis hombres y yo lucharemos a tu lado, como verdaderos aliados.",
  ui_story_5071_50711401_83_dialog_content = "No seamos impulsivos. Todavía podemos trabajar juntos. Haremos que ese niño entregue el bastón, ¡luego transferiremos algunos suministros para la defensa!",
  ui_story_5071_50711401_84_dialog_content = "¡Urgh! ¿Q-Quién—",
  ui_story_5071_50711401_85_dialog_content = "¡Alguien ha sido atacado! ¡Rayos, ustedes tienen segundas intenciones y no quieren trabajar juntos, lo sabía!",
  ui_story_5071_50711401_86_dialog_content = "¡Matemos a ese niño demonio primero y luchemos por el bastón después!",
  ui_story_5071_50711401_87_dialog_content = "Fuera del camino, no tengo tiempo para ti.",
  ui_story_5071_50711401_88_dialog_content = "¡Manos fuera de mi marca!",
  ui_story_5071_50711401_89_dialog_content = "Digo, fuera de mi camino-",
  ui_story_5071_50711401_90_dialog_content = "Morirás si no te defiendes, Kade. Si eso sucede, todos nuestros sueños morirán contigo.",
  ui_story_5071_50711401_91_dialog_content = "¡Rayos! ¡Fuera de mi camino!",
  ui_story_5071_50711401_92_dialog_content = "¡No intenten detenerme, gente miope!",
  ui_story_5071_50711401_93_dialog_content = "Lo apuñalé. ¡Rápido! Ayúdame—",
  ui_story_5071_50711401_94_dialog_content = "¡Urgh!",
  ui_story_5071_50711401_95_dialog_content = "¿Esto es lo que quieres, plagas? ¡Bueno, lo tienes!",
  ui_story_5071_50711401_96_dialog_content = "¡No, para! Esta pelea no tiene sentido—",
  ui_story_5071_50711401_97_dialog_content = "¡Conviértanse en cenizas, todos ustedes!",
  ui_story_5071_50711401_98_dialog_content = "Nadie puede oírme...",
  ui_story_5071_50711401_99_dialog_content = "Es una masacre... No sabía que el Señor de las Sombras tenía un lado tan brutal... ¿Ha perdido completamente el control?",
  ui_story_5071_50711401_100_dialog_content = "¿Así es como terminó matando a su mejor amigo?",
  ui_story_5071_50711401_101_dialog_content = "Espera un segundo, ¿qué estoy pensando? ¡La ruptura en las emociones del Señor de las Sombras debería estar justo aquí!",
  ui_story_5071_50711401_102_dialog_content = "¡Por favor, escúchame! Tienes que recuperar el sentido—",
  ui_story_5071_50711402_1_dialog_content = "Los jefes están todos...",
  ui_story_5071_50711402_2_dialog_content = "¡Mira! Creo que el ejército de Lumopolis se está moviendo. Parece que vienen en esta dirección... ¿verdad?",
  ui_story_5071_50711402_3_dialog_content = "Tú y yo somos los únicos que quedan ahora...",
  ui_story_5071_50711402_4_dialog_content = "Felicidades por sobrevivir al Pozo por segunda vez, Kade.",
  ui_story_5071_50711402_5_dialog_content = "*rugidos*",
  ui_story_5071_50711402_6_dialog_content = "¡Aparta, Valon! Tengo que ir a sellar el pacto con pruebas...",
  ui_story_5071_50711402_7_dialog_content = "¿Incluso después de todo esto, todavía crees en las mentiras de Lumopolis?",
  ui_story_5071_50711402_8_dialog_content = "¿Recuerdas el <color=#FFB400>sueño</color> del que te hablé una vez, Kade?",
  ui_story_5071_50711402_9_dialog_content = "La fundación ya ha sido establecida. Ven conmigo, y con el poder del Bastón del Pastor, podemos unir la asociación de gremios y la gente débil de Umbraton bajo nosotros.",
  ui_story_5071_50711402_10_dialog_content = "Crearemos un nuevo hogar para nosotros, un refugio seguro para almas perdidas como nosotros.",
  ui_story_5071_50711402_11_dialog_content = "Un lugar donde podemos vivir en felicidad e igualdad, donde podemos viajar a cualquier parte y hacer negocios con cualquiera en la <color=#FFB400>tierra</color>—",
  ui_story_5071_50711402_12_dialog_content = "(Un gremio de viajeros... ¿Podría ser así como comenzó el <color=#FFB400>Gremio Continental</color>? ¡Y la idea del libre comercio suena justo como el <color=#FFB400>Gremio de Explorador Nublar</color>!)",
  ui_story_5071_50711402_13_dialog_content = "(El sueño del Sr. Valon... ¡No es diferente al de Lady Sheol! Por eso la Sra. Hanstie seguía diciendo que ella robó el sueño de alguien más!)",
  ui_story_5071_50711402_14_dialog_content = "¿Pero qué pasa con papá? ¿Qué pasa con los trabajadores del gremio que no quieren irse?",
  ui_story_5071_50711402_15_dialog_content = "¿Y qué pasa con esos niños engañados para unirse a una pandilla? Si tampoco quieren irse—",
  ui_story_5071_50711402_16_dialog_content = "... Papá y esas personas no están dispuestas a irse. Puede que tenga más que ver con no querer renunciar a sus perspectivas, no algún tipo de amor.",
  ui_story_5071_50711402_17_dialog_content = "Tantas personas han sido privadas de una buena vida aquí, y no desean nada más que irse. ¿Realmente los obligarías a quedarse aquí y morir por este pueblo podrido?",
  ui_story_5071_50711402_18_dialog_content = "Lloras por los niños en la calle, ¡pero aquellos que trabajan para las gremios podrían ser sus padres o hermanos!",
  ui_story_5071_50711402_19_dialog_content = "La conexión entre nosotros y nuestro lugar de origen es más fuerte de lo que piensas, y nadie puede romper ese vínculo.",
  ui_story_5071_50711402_20_dialog_content = "Las personas pueden amar u odiar su hogar, pero nunca deberían abandonarlo—",
  ui_story_5071_50711402_21_dialog_content = "Me estoy quedando con papá y defendiendo nuestra casa a nuestra manera.",
  ui_story_5071_50711402_22_dialog_content = "La horda de Eclipsites llegará pronto, y el ejército de Lumopolis también se está preparando para la batalla. En poco tiempo, este lugar se sumergirá en un caos total.",
  ui_story_5071_50711402_23_dialog_content = "¡A la gente de Lumopolis no le importará si te quedas aquí para morir!",
  ui_story_5071_50711402_24_dialog_content = "Al menos morimos por nuestro hogar.",
  ui_story_5071_50711402_25_dialog_content = "Padre y yo nunca hemos estado de acuerdo...",
  ui_story_5071_50711402_26_dialog_content = "Nunca he tenido su aprobación, a diferencia de ti. Al final, parece que realmente eres el mejor hijo de Istvan.",
  ui_story_5071_50711402_27_dialog_content = "Pero tú eres diferente a él. Desde que empezaste a animarme a perseguir mi sueño, supe que eras la única persona que realmente podía entenderme.",
  ui_story_5071_50711402_28_dialog_content = "Así que por favor, por el bien de nuestro sueño, solo ven conmigo—",
  ui_story_5071_50711402_29_dialog_content = "¡Nuestro sueño es cambiar este lugar! Si no podemos resistir, el sueño se convierte en una mentira.",
  ui_story_5071_50711402_30_dialog_content = "Fue difícil finalmente convencerlos de unirse. No puedo rendirme ahora...",
  ui_story_5071_50711402_31_dialog_content = "¡Todo es una mentira, Kade! ¡Estas personas solo están interesadas en beneficiarse a sí mismas! ¡Pronto comenzarán a pelear entre sí!",
  ui_story_5071_50711402_32_dialog_content = "Entiendo que las pandillas decepcionan a la gente. Pero no necesariamente están más allá de la ayuda.",
  ui_story_5071_50711402_33_dialog_content = "Muchos de ellos no tenían opción. ¡Pero si incluso yo pudiera tener una aspiración justa, otras personas también podrían!",
  ui_story_5071_50711402_34_dialog_content = "Mientras persistamos, dejaremos la semilla.",
  ui_story_5071_50711402_35_dialog_content = "Incluso si no somos nosotros, algún día de alguna manera, alguien cumplirá nuestro sueño.",
  ui_story_5071_50711402_36_dialog_content = "Kade... Has estado luchando en el presente todo este tiempo. Estás siendo imprudente y solo te enfocas en el ataque, justo como cuando jugamos al ajedrez.",
  ui_story_5071_50711402_37_dialog_content = "Castigar el mal de esta manera solo destruirá todo lo que tenemos ante nosotros. ¿Desde cuándo tú... ves más allá de eso?",
  ui_story_5071_50711402_38_dialog_content = "Umbraton dependerá de sí mismo en el futuro, pero eso no significa que no podamos hacer aliados. No podemos luchar solos sino pedir ayuda a Lumopolis.",
  ui_story_5071_50711402_39_dialog_content = "Eres el que me hizo entender el significado de la amistad, Valon. ¿Por qué has cambiado?",
  ui_story_5071_50711402_40_dialog_content = "Lumopolis es la fuente de la oscuridad de Umbraton... Mientras se bañan arrogantes en la luz, nos dejan al resto atrapados en las sombras.",
  ui_story_5071_50711402_41_dialog_content = "Te envidio por dejar ir tu odio y seguir adelante tan fácilmente.",
  ui_story_5071_50711402_42_dialog_content = "Pero nunca puedo perdonar a esas personas. Comprometerme con escoria como ellos no es diferente a hacer la vista gorda a sus injusticias, y me niego a hacer eso.",
  ui_story_5071_50711402_43_dialog_content = "Proteger a las personas que me importan... ya requiere toda mi fuerza.",
  ui_story_5071_50711402_44_dialog_content = "Valon...",
  ui_story_5071_50711402_45_dialog_content = "Nunca me has ganado en ajedrez, Kade. ¿Qué te hace pensar que puedes superar a todo Lumopolis?",
  ui_story_5071_50711402_46_dialog_content = "Cuando se trata de engaño, nadie es mejor que ellos—",
  ui_story_5071_50711402_47_dialog_content = "Por favor, Kade, te lo suplico. Dame el Bastón del Pastor y ven conmigo...",
  ui_story_5071_50711402_48_dialog_content = "Yo... me niego.",
  ui_story_5071_50711402_49_dialog_content = "¿Es así como tiene que terminar entre nosotros? ¿Realmente solo puede haber un vencedor en el Pit?",
  ui_story_5071_50711402_50_dialog_content = "Nunca pensé que nuestras espadas se cruzarían algún día... Pero yo...",
  ui_story_5071_50711402_51_dialog_content = "¿Qué está pasando aquí? ¿Dónde está nuestro enlace, Sr. Kade?",
  ui_story_5071_50711402_52_dialog_content = "!",
  ui_story_5071_50711402_53_dialog_content = "¡No tienes permitido entrar!",
  ui_story_5071_50711402_54_dialog_content = "No tengo tiempo para lidiar con ustedes. ¿Dónde está el Sr. Kade?",
  ui_story_5071_50711402_55_dialog_content = "¡Escoria de Lumopolis! ¡Cómo te atreves a arrastrar a tu ejército a nuestro hogar!",
  ui_story_5071_50711402_56_dialog_content = "¡Expúlsalos de aquí!",
  ui_story_5071_50711402_57_dialog_content = "No actúes tan engreído, tú, desgraciado que vives en las zanjas de Umbraton.",
  ui_story_5071_50711402_58_dialog_content = "Derrota a estos y averigua dónde está Kade. No permitas que estos escoria lo maten.",
  ui_story_5071_50711402_59_dialog_content = "¡Malditos sean estos habitantes de Lumopolis! ¡Urgh!",
  ui_story_5071_50711402_60_dialog_content = "¿Estás ahí, Sr. Kade? Porque ha pasado un tiempo desde nuestra hora de reunión acordada, nosotros...",
  ui_story_5071_50711402_61_dialog_content = "¿Es este verdaderamente tu plan, Kade?",
  ui_story_5071_50711402_62_dialog_content = "¿Realmente estás dispuesto a caer tan bajo? ¡Qué desgracia!",
  ui_story_5071_50711402_63_dialog_content = "Retrocede. No puedes entrar a Umbraton así.",
  ui_story_5071_50711402_64_dialog_content = "Sr. Kade, no creo que tenga una comprensión suficiente de lo que es un compromiso. Un acuerdo es más importante que cualquier cosa.",
  ui_story_5071_50711402_65_dialog_content = "¡Retrocede!",
  ui_story_5071_50711402_66_dialog_content = "¡Traicionaste a todo Umbraton al dejar entrar a estos perros en nuestro hogar!",
  ui_story_5071_50711402_67_dialog_content = "¡Habitante de Umbratón! ¡Cuida tu lenguaje!",
  ui_story_5071_50711402_68_dialog_content = "¡No permitiré que profanes mi hogar!",
  ui_story_5071_50711402_69_dialog_content = "No ataques. ¡Baja el arma, Valon!",
  ui_story_5071_50711402_70_dialog_content = "¡Retrocede! ¡Retrocede! Malditas, los Luminatics de ese tipo—",
  ui_story_5071_50711402_71_dialog_content = "¡El comandante ha sido herido! ¡Contraataquen! ¡Devuélvanles el golpe!",
  ui_story_5071_50711402_72_dialog_content = "¡Vosotros, arrogantes tontos, no escaparéis tan fácilmente! Yo—",
  ui_story_5071_50711402_73_dialog_content = "(Oh, no, los soldados de Lumopolis están disparando indiscriminadamente... ¡Tengo que detenerlos!)",
  ui_story_5071_50711402_74_dialog_content = "(Ratas, simplemente no puedo detener todo esto...)",
  ui_story_5071_50711402_75_dialog_content = "<color=#e8d9bb>¡Bang—!</color>",
  ui_story_5071_50711402_76_dialog_content = "T-Tú canalla... Kade—",
  ui_story_5071_50711402_77_dialog_content = "<size=40>¡Valon!</size>",
  ui_story_5071_50711402_78_dialog_content = "<size=50>¡Ahhhh!</size>",
  ui_story_5071_50711402_79_dialog_content = "¡Fuera! Todos ustedes, ¡fuera!",
  ui_story_5071_50711402_80_dialog_content = "¡Retirémonos ahora! Este tipo se ha vuelto loco y ya no le importa el acuerdo. ¡Retiro!",
  ui_story_5071_50711402_81_dialog_content = "¡Retiro! ¡Regresa, ahora!",
  ui_story_5071_50711402_82_dialog_content = "Valon...",
  ui_story_5071_50711402_83_dialog_content = "Kade... Las cosas siempre parecen ir de mal en peor aquí en Umbraton. ¿Cómo se supone que vamos a salvar este lugar ahora?",
  ui_story_5071_50711402_84_dialog_content = "La sombra de Lumopolis... apagará las llamas... Y Umbraton nunca será purificado...",
  ui_story_5071_50711402_85_dialog_content = "¿Ahora quién será... el salvador de los oprimidos...",
  ui_story_5071_50711402_86_dialog_content = "¡Es posible! Es posible, Valon. Solo dame más tiempo. Solo tenemos que superar la crisis...",
  ui_story_5071_50711402_87_dialog_content = "¡Tu sueño aún puede hacerse realidad, y este lugar prosperará!",
  ui_story_5071_50711402_88_dialog_content = "Jejeje... Realmente eres... demasiado ingenuo...",
  ui_story_5071_50711402_89_dialog_content = "No le digas a papá lo que hice... no porque me avergüence... sino porque no quiero que sufra...",
  ui_story_5071_50711402_90_dialog_content = "... Lo prometo.",
  ui_story_5071_50711402_91_dialog_content = "Acércate, hermano... Todavía tengo algo que decirte...",
  ui_story_5071_50711402_92_dialog_content = "*tosiendo* ... Somos hombres de Umbraton, de principio a fin. La violencia nunca desaparecerá de nuestros corazones...",
  ui_story_5071_50711402_93_dialog_content = "Ya que no puedo detenerte de hacer todo esto, al menos cumple tu promesa conmigo...",
  ui_story_5071_50711402_94_dialog_content = "A partir de ahora, tendrás que hacer lo que sea necesario para mantener a Umbraton vivo...",
  ui_story_5071_50711402_95_dialog_content = "Yo... prometo.",
  ui_story_5071_50711402_96_dialog_content = "Mi hermano.",
  ui_story_5071_50711402_97_dialog_content = "...",
  ui_story_5071_50711402_98_dialog_content = "No... No... No lo hiciste en absoluto, ¿verdad, Señor de las Sombras?",
  ui_story_5071_50711402_99_dialog_content = "... Esas personas fueron atraídas por el alboroto y solo entraron en Umbraton para asegurar que se llevara a cabo el pacto.",
  ui_story_5071_50711402_100_dialog_content = "Eran demasiado distantes para mostrarnos respeto, pero nosotros éramos un poco demasiado sensibles. No aprendimos a cooperar hasta que pagamos el precio.",
  ui_story_5071_50711402_101_dialog_content = "¿Pero eso me absuelve de mis pecados?",
  ui_story_5071_50711402_102_dialog_content = "Una persona sabia dijo una vez, \"El poder de las palabras puede atar el alma.\"",
  ui_story_5071_50711402_103_dialog_content = "Así que simplemente no puedo liberarme de las palabras de Valon.",
  ui_story_5071_50711501_1_dialog_content = "Para preservar nuestra alianza con Lumopolis, nunca expliqué la muerte de Valon a nadie. Sin embargo, todo fue mi culpa.",
  ui_story_5071_50711501_2_dialog_content = "Pero eso claramente no es la verdad...",
  ui_story_5071_50711501_3_dialog_content = "Cuando me convertí en un Niño de Istvan, juré nunca matar a los míos ni dañar los intereses de nuestra familia...",
  ui_story_5071_50711501_4_dialog_content = "Pero al final, rompí ese voto. No importa cómo lo viera nadie, no tenía derecho a enfrentar a nuestro Padre.",
  ui_story_5071_50711501_5_dialog_content = "Y sin embargo, justo antes de morir, nuestro Padre decidió dejar todo en mis manos. Y así, \"Istvan\" se convirtió en mi nuevo nombre.",
  ui_story_5071_50711501_6_dialog_content = "Señor de las Sombras...",
  ui_story_5071_50711501_7_dialog_content = "Decidí convertirme en una Sombra...",
  ui_story_5071_50711501_8_dialog_content = "Viviré en la oscuridad como una sombra y recurriré a cualquier cosa para asegurarme de que Umbraton sobreviva.",
  ui_story_5071_50711501_9_dialog_content = "He ocultado el pasado de mí mismo durante tanto tiempo que apenas puedo recordarlo... Pero los pecados de mi pasado aún me persiguen en forma de pesadillas.",
  ui_story_5071_50711501_10_dialog_content = "Un precio justo a cambio de mi supervivencia.",
  ui_story_5071_50711501_11_dialog_content = "No... No es justo en absoluto.",
  ui_story_5071_50711501_12_dialog_content = "Por el futuro de Umbraton, estoy dispuesto a sacrificarlo todo. Así es como siempre he hecho las cosas.",
  ui_story_5071_50711501_13_dialog_content = "Como el hombre arrogante que soy, sacrificaré todo y asumiré la responsabilidad de todo. Valon... Fue el primer \"precio\" que tuve que pagar.",
  ui_story_5071_50711501_14_dialog_content = "No hiciste nada malo... Lo sabes, ¿verdad? Pero aún así eliges castigarte de esta manera.",
  ui_story_5071_50711501_15_dialog_content = "... Tomé esta decisión por el bien de Umbraton, y las consecuencias son mías para asumir. Independientemente de lo correcto o incorrecto, solo deseo proteger esta ciudad.",
  ui_story_5071_50711501_16_dialog_content = "Siempre he creído que algún día alguien se alzará en este lugar de oscuridad, una persona que finalmente me sucederá.",
  ui_story_5071_50711501_17_dialog_content = "Me alegra decir que puedo ver que ese deseo se hará realidad pronto.",
  ui_story_5071_50711501_18_dialog_content = "Si realmente te sientes así, ¿por qué sigues atrapado en estos recuerdos...?",
  ui_story_5071_50711501_19_dialog_content = "En efecto, ¿por qué...? Cuando me despierto en medio de la noche, a veces me hago la misma pregunta.",
  ui_story_5071_50711501_20_option_content = "Es por tu culpa.",
  ui_story_5071_50711501_21_dialog_content = "¿Estás diciendo que todavía me culpo a mí mismo?",
  ui_story_5071_50711501_22_option_content = "Es por tu arrepentimiento.",
  ui_story_5071_50711501_23_dialog_content = "Arrepentimiento... ¿Crees que eso es lo que siento?",
  ui_story_5071_50711501_24_dialog_content = "Creo que, en algún lugar profundo de tu corazón, siempre has sentido remordimiento por estas cosas.",
  ui_story_5071_50711501_X24_dialog_content = "Por eso no podías recordar cómo se veía Valon.",
  ui_story_5071_50711501_X25_dialog_content = "...",
  ui_story_5071_50711501_25_dialog_content = "¿De verdad no has considerado decirle la verdad a la gente?",
  ui_story_5071_50711501_26_dialog_content = "La verdad puede cortar más profundo que cualquier cuchilla a veces. Por el bien de la paz, debo continuar con esta farsa sin importar cuán superficial pueda ser.",
  ui_story_5071_50711501_27_dialog_content = "No me arrepiento de nada—",
  ui_story_5071_50711501_28_dialog_content = "Deberías haberlo comprendido ya... Pero has estado viviendo con culpa y remordimiento todo este tiempo.",
  ui_story_5071_50711501_29_dialog_content = "Remordimiento por no decirle la verdad al Sr. Valon y al viejo Istvan.",
  ui_story_5071_50711501_30_dialog_content = "Sagaz como siempre, pero esas viejas sombras ya se han ido. Nunca tendré la oportunidad de reconciliarme con ellas de nuevo.",
  ui_story_5071_50711501_31_dialog_content = "Es por eso que comenzaste a castigarte a ti mismo... Y a atraparte en esta pesadilla...",
  ui_story_5071_50711501_32_dialog_content = "He interpretado mi papel durante tanto tiempo que apenas puedo distinguir la diferencia. ¿Me he convertido en uno con las sombras, o son las sombras las que simplemente están interpretando mi papel?",
  ui_story_5071_50711501_33_dialog_content = "Todo lo que he hecho... ¿Es realmente suficiente?",
  ui_story_5071_50711501_34_dialog_content = "Ya has renunciado a tanto por Umbraton...",
  ui_story_5071_50711501_35_dialog_content = "Si tan solo no hubiera dudado, si tan solo hubiera detenido a Valon cuando tuve la oportunidad, tal vez las cosas habrían sido diferentes—",
  ui_story_5071_50711501_36_dialog_content = "Nunca quise pagar el precio con su vida.",
  ui_story_5071_50711501_37_dialog_content = "Heh... Si aún puedo sentirme así, entonces parece que el viejo Kade aún existe dentro de mí. Después de todo este tiempo, sigo desesperado por tu perdón, mi querido amigo...",
  ui_story_5071_50711501_38_dialog_content = "Je—",
  ui_story_5071_50711501_39_dialog_content = "Jajajajaja—",
  ui_story_5071_50711501_40_dialog_content = "¿Señor Sombrío?",
  ui_story_5071_50711501_41_dialog_content = "Quizás realmente he envejecido. ¿He perdido realmente la pasión de mi juventud ya?",
  ui_story_5071_50711501_42_dialog_content = "¿Cómo pude permitirme tener tales pensamientos?",
  ui_story_5071_50711501_43_dialog_content = "¡Finalmente has vuelto en sí, Señor de las Sombras!",
  ui_story_5071_50711501_44_dialog_content = "¡No es suficiente, todavía no es suficiente!",
  ui_story_5071_50711501_45_dialog_content = "¡Hay más furia ardiente por desatar!",
  ui_story_5071_50711501_46_dialog_content = "(Las emociones del Señor Sombrío están comenzando a estabilizarse, pero siento algo más en su corazón. Algo tenue...)",
  ui_story_5071_50711501_47_dialog_content = "Si no fuera por tu ayuda justo ahora, habría olvidado las lecciones del pasado. Sus sombras existen para recordarme que no debo cometer los mismos errores nuevamente.",
  ui_story_5071_50711501_48_dialog_content = "¡No más divagaciones!",
  ui_story_5071_50711501_49_dialog_content = "¡Si quieren brutalidad, entonces brutalidad es lo que recibirán! ¡Ya no me voy a contener más!",
  ui_story_5071_50711501_50_dialog_content = "¡Ya casi llegas, Señor de las Sombras! ¡Despierta!",
  ui_story_5071_50711501_51_dialog_content = "(¿Funcionó? Mi cuerpo... Mi conciencia se está volviendo borrosa... Como si me estuvieran sacando de aquí...)",
  ui_story_5071_50711501_52_dialog_content = "Señor Sombrío... Te estaré esperando afuera...",
  ui_story_5071_50711501_53_dialog_content = "Gracias, amable Caelestita.",
  ui_story_5071_50711501_54_dialog_content = "También debería...",
  ui_story_5071_50711501_55_dialog_content = "Kade.",
  ui_story_5071_50711501_56_dialog_content = "¡¿?!",
  ui_story_5071_50711501_57_dialog_content = "Honestamente... ha pasado mucho tiempo.",
  ui_story_5071_50711501_58_dialog_content = "¿Valon...?",
  ui_story_5071_50711501_59_dialog_content = "Kade... Tengo una pregunta que quiero que respondas de nuevo.",
  ui_story_5071_50711501_60_dialog_content = "¿Puedes mirarme a los ojos y responder sinceramente?",
  ui_story_5071_50711501_61_dialog_content = "...",
  ui_story_5071_50711501_62_dialog_content = "¿Qué precio estás dispuesto a pagar para salvar Umbraton?",
  ui_story_5071_50711501_63_dialog_content = "... ¿De verdad tienes que preguntar?",
  ui_story_5071_50711501_64_dialog_content = "¡Todo! ¡Pagaré todo!",
  ui_story_5071_50711501_65_dialog_content = "Es tan típico de ti... decir eso, Kade...",
  ui_story_5071_50711501_66_dialog_content = "¡Ahora ve, mi hermano! ¡Muestra a todos los enemigos de Umbraton tu determinación!",
  ui_story_5071_50711501_67_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5071_50711501_68_dialog_content = "Jeje, no pensé que podría durar tanto tiempo.",
  ui_story_5071_50711501_69_dialog_content = "El dirigible está a punto de explotar. ¿Realmente crees que Kade volverá?",
  ui_story_5071_50711501_70_dialog_content = "Sí. Y PlayerName también me prometió volver con el Señor de las Sombras.",
  ui_story_5071_50711501_71_dialog_content = "Kade no es más que una existencia vacía... Incluso si sobrevive, no podría salvarte ahora.",
  ui_story_5071_50711501_72_dialog_content = "Su verdadero rostro solo os llenará a todos de desesperación.",
  ui_story_5071_50711501_73_dialog_content = "Lady Hanstie, estamos aquí...",
  ui_story_5071_50711501_74_dialog_content = "¿Más refuerzos incluso ahora?",
  ui_story_5071_50711501_75_dialog_content = "¿Y hasta consiguió que los Eclipsites lucharan por ella? Esto ha empeorado.",
  ui_story_5071_50711501_76_dialog_content = "¡Concentra tus ataques! ¡No le des la oportunidad de recuperar el aliento!",
  ui_story_5071_50711501_77_dialog_content = "Señor de las Sombras...",
  ui_story_5071_50711501_78_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5071_50711501_79_dialog_content = "¿Lo que está sucediendo?",
  ui_story_5071_50711501_80_dialog_content = "Hubo una repentina gran explosión...",
  ui_story_5071_50711501_81_dialog_content = "¡E-Espera! ¿Qué es eso?",
  ui_story_5071_50711501_82_dialog_content = "Hay alguien en el fuego... P-Podría ser...",
  ui_story_5071_50711501_83_dialog_content = "¡¡¡Señor Sombrío!!!",
  ui_story_5071_50711501_84_dialog_content = "Miles de cicatrices... y feroces llamas azules. Ese es él...",
  ui_story_5071_50711501_85_dialog_content = "<size=45>¡Ese es el demonio de The Pit!!!</size>",
  ui_story_5071_50711501_86_dialog_content = "No puede ser derrotado... Es una leyenda invencible... ¿Cómo podríamos posiblemente...",
  ui_story_5071_50711501_87_dialog_content = "¡No corran, cobardes! ¡Nuestro objetivo es vengarnos de ese hombre!",
  ui_story_5071_50711501_88_dialog_content = "Por muy viejo que sea ahora, no hay forma de que pueda derrotar a tantos oponentes...",
  ui_story_5071_50711501_89_dialog_content = "¿Incluso después de todo esto, todavía quieres huir?",
  ui_story_5071_50711501_90_dialog_content = "¡N-No te dejaremos!",
  ui_story_5071_50711501_91_dialog_content = "Llegas tarde, Señor de las Sombras. ¿La vejez te está afectando?",
  ui_story_5071_50711501_92_dialog_content = "Perdóname, Sheol. Tenías razón, he estado atrapado detrás de una triste máscara todo este tiempo.",
  ui_story_5071_50711501_93_dialog_content = "Pero ahora, creo que es hora de dejar que mi vieja sombra regrese.",
  ui_story_5071_50711501_94_dialog_content = "Ava... Mi vacilación es lo que me hizo perder a Valon.",
  ui_story_5071_50711501_95_dialog_content = "Pero ya no dudaré más, incluso si eres mi enemigo.",
  ui_story_5071_50711501_96_dialog_content = "¡Silencio! No tienes derecho a pronunciar el nombre de Valon!",
  ui_story_5071_50711501_97_dialog_content = "Cuando comenzó este incidente, sabía que tú tenías algo que ver en todo esto desde el principio—",
  ui_story_5071_50711501_98_dialog_content = "Eres libre de buscar venganza contra mí, pero deberías haber dejado en paz a los inocentes.",
  ui_story_5071_50711501_99_dialog_content = "¡Cállate! ¡Cierra la boca! ¡No tienes idea de cuánto he sufrido!",
  ui_story_5071_50711501_100_dialog_content = "¡He hecho tantas cosas inconfesables, todo por este momento!",
  ui_story_5071_50711501_101_dialog_content = "Pinté tantas falsificaciones repugnantes por dinero... Y para exponerte, realicé tantos experimentos asquerosos...",
  ui_story_5071_50711501_102_dialog_content = "¡Toda la fuerza y la gente que he reunido a lo largo de los años, solo para que pudiéramos tener nuestra venganza!",
  ui_story_5071_50711501_103_dialog_content = "Tu plan ha fallado. La mente del Señor de las Sombras es perfectamente estable ahora; ¡él nunca volverá a perder el control!",
  ui_story_5071_50711501_104_dialog_content = "¿Es eso cierto? Muy bien entonces... Si insistes en mantener tu disfraz sin sentido...",
  ui_story_5071_50711501_105_dialog_content = "¡Entonces apaciguaré el espíritu de Valon matándote yo mismo!",
  ui_story_5071_50711501_106_dialog_content = "¡Todos ustedes, ataquen!",
  ui_story_5071_50711501_107_dialog_content = "¿Son estos patéticos vendidos toda la ayuda que pudiste conseguir?",
  ui_story_5071_50711501_108_dialog_content = "Urgh—",
  ui_story_5071_50711501_109_dialog_content = "¡No nos subestimes, Ava!",
  ui_story_5071_50711501_110_dialog_content = "N-No somos rival para él. ¡Corre!",
  ui_story_5071_50711501_111_dialog_content = "¡La oscuridad que Valon y yo conquistamos en el pasado es mucho mayor que cualquier cosa que hayas visto jamás!",
  ui_story_5071_50711501_112_dialog_content = "T-Tú monstruo...",
  ui_story_5071_50711501_113_dialog_content = "El-El Señor Sombrío se está descontrolando—",
  ui_story_5071_50711501_114_dialog_content = "¡Ahora que toda gracia ha sido descartada, prepárate para suplicar piedad!",
  ui_story_5071_50711501_115_dialog_content = "¡¿C-Cómo puede ser esto?! Su cuerpo está cubierto de heridas, entonces ¿por qué él...?",
  ui_story_5071_50711501_116_dialog_content = "¡Sigue atacando! ¡Debe estar perdiendo fuerza ahora mismo!",
  ui_story_5071_50711501_117_dialog_content = "¿Perdiendo fuerza? ¡Solo estoy calentando!",
  ui_story_5071_50711501_118_dialog_content = "Todo ha sido quemado hasta convertirse en cenizas... Este tipo es inmortal...",
  ui_story_5071_50711501_119_dialog_content = "¡Graaaaaaaaagh!",
  ui_story_5071_50711501_120_dialog_content = "Esto es lo que ha estado escondiendo, una apariencia ardiendo en caos...",
  ui_story_5071_50711501_121_dialog_content = "¿Estás feliz ahora?",
  ui_story_5071_50711501_122_dialog_content = "Felicidades, esta es la bestia que querías, ¿no es así?",
  ui_story_5071_50711501_123_dialog_content = "¡A-Apúrate! ¡Saca esa cosa ahora mismo!!!",
  ui_story_5071_50711501_124_dialog_content = "Pagaré cualquier costo, así que solo tráelo...",
  ui_story_5071_50711501_125_dialog_content = "<size=50>¡Ava—!!!</size>",
  ui_story_5071_50711502_1_dialog_content = "¿Vieron todos eso? Incluso ese Eclipsite no pudo detenerlo. ¡Istvan es el verdadero monstruo!",
  ui_story_5071_50711502_2_dialog_content = "¿Huyendo, verdad?",
  ui_story_5071_50711502_3_dialog_content = "No te acerques—",
  ui_story_5071_50711502_4_dialog_content = "!",
  ui_story_5071_50711502_5_dialog_content = "Valon...",
  ui_story_5071_50711502_6_dialog_content = "¿Quieres que la perdone?",
  ui_story_5071_50711502_7_dialog_content = "Ayuda—",
  ui_story_5071_50711502_8_dialog_content = "¡Eres patética, Ava!",
  ui_story_5071_50711502_9_dialog_content = "No...",
  ui_story_5071_50711502_10_dialog_content = "Ríndete. No te haré daño, pero recibirás la justicia que mereces.",
  ui_story_5071_50711502_11_dialog_content = "Continuaré el sueño de Valon, nuestro sueño.",
  ui_story_5071_50711502_12_dialog_content = "Ese sueño... obviamente destrozado...",
  ui_story_5071_50711502_13_dialog_content = "Es una lástima, Ava, nunca pensé que caerías tan bajo.",
  ui_story_5071_50711502_14_dialog_content = "Especialmente cuando eras de Valon...",
  ui_story_5071_50711502_15_dialog_content = "No me digas eso. ¡No necesito tu simpatía!",
  ui_story_5071_50711502_16_dialog_content = "No puedes llegar tan lejos sin mucha ayuda.",
  ui_story_5071_50711502_17_dialog_content = "Aquellos que me odian se aprovecharon de ti... ¡Qué imperdonable!",
  ui_story_5071_50711502_18_dialog_content = "...",
  ui_story_5071_50711502_19_dialog_content = "Si no estás dispuesto a revelar, averiguaré quiénes son por mi cuenta.",
  ui_story_5071_50711502_20_dialog_content = "Pero te prometo, tendrás un juicio justo.",
  ui_story_5071_50711502_21_dialog_content = "Deja de derramar lágrimas de cocodrilo. ¡Es asqueroso!",
  ui_story_5071_50711502_22_dialog_content = "Mataste a Valon y le quitaste todo, sin embargo, no fuiste juzgado.",
  ui_story_5071_50711502_23_dialog_content = "¿Por qué deberíamos ser tu cordero sacrificial?",
  ui_story_5071_50711502_24_dialog_content = "¡Te maldigo! May ¡Que tu corazón quede atrapado para siempre en el abismo!",
  ui_story_5071_50711502_25_dialog_content = "... Hace mucho tiempo, Valon y yo albergábamos esperanzas para las leyes y reglas en Umbraton.",
  ui_story_5071_50711502_26_dialog_content = "Anhelaba un nuevo orden y confió ese sueño en mí.",
  ui_story_5071_50711502_27_dialog_content = "Si es posible, preferiría no tenerlo sobre ti.",
  ui_story_5071_50711502_28_dialog_content = "Valon...",
  ui_story_5071_50711502_29_dialog_content = "Fundaste el Gremio Continental para Valon, ¿no es así?",
  ui_story_5071_50711502_30_dialog_content = "Incluso cuando estás lleno de odio, por amor aún conservas esa pureza...",
  ui_story_5071_50711502_31_dialog_content = "Basta, detente...",
  ui_story_5071_50711502_32_dialog_content = "He estado escondido en las sombras el tiempo suficiente para saber qué tipo de persona está más allá de la ayuda.",
  ui_story_5071_50711502_33_dialog_content = "Ava, aún hay pureza en tu corazón.",
  ui_story_5071_50711502_34_dialog_content = "Esa es la sombra de tu pasado.",
  ui_story_5071_50711502_35_dialog_content = "Por lo tanto, te prometo aquí y ahora—",
  ui_story_5071_50711502_36_dialog_content = "Un día, cuando hayas expiado tus crímenes y yo haya terminado de reformar Umbraton...",
  ui_story_5071_50711502_37_dialog_content = "Eres bienvenido a tomar mi vida.",
  ui_story_5071_50711502_38_dialog_content = "Tú...",
  ui_story_5071_50711502_39_dialog_content = "Tranquilo, veo que los Guardianes vienen con equipos de rescate.",
  ui_story_5071_50711502_40_dialog_content = "Diles lo que te quede por decir.",
  ui_story_5071_50711502_41_dialog_content = "... ¡Déjame ir!",
  ui_story_5071_50711502_42_dialog_content = "¿Por qué yo?",
  ui_story_5071_50711502_43_dialog_content = "¡El verdadero carnicero está justo frente a ti!",
  ui_story_5071_50711502_44_dialog_content = "Míralo, ¡mira esas feas cicatrices! ¿No lo entiendes?",
  ui_story_5071_50711502_45_dialog_content = "¡Él es el mayor pecador y enemigo de Umbraton!",
  ui_story_5071_50711502_46_dialog_content = "¿Has olvidado cómo murió tu madre?",
  ui_story_5071_50711502_47_dialog_content = "...",
  ui_story_5071_50711502_48_dialog_content = "Realmente no estoy hecho para esto. ¡Apúrense, Guardianes!",
  ui_story_5071_50711502_49_dialog_content = "Todos ustedes vieron a través de él, ¿verdad?",
  ui_story_5071_50711502_50_dialog_content = "¡Tiemblen de miedo, todos y todos aquellos que deseen permanecer junto a él!",
  ui_story_5071_50711502_51_dialog_content = "¡La verdad saldrá a la luz un día!",
  ui_story_5071_50711502_52_dialog_content = "<color=#FFB400>¡Te maldigo, Kade!</color>",
  ui_story_5071_50711601_1_dialog_content = "La causa de la muerte de Yvonne finalmente se hace pública y es veneno. Ella todavía estaba en su apogeo cuando Hanstie la asesinó.",
  ui_story_5071_50711601_2_dialog_content = "Lamento no haber tenido más conversaciones con ella.",
  ui_story_5071_50711601_3_dialog_content = "Ella era una persona tan buena...",
  ui_story_5071_50711601_4_dialog_content = "Vergil también lo ha tomado muy mal y no ha dormido ni comido durante días. Tendré que asignarle más trabajo para que se distraiga.",
  ui_story_5071_50711601_5_dialog_content = "No creo que debas hacerle trabajar tanto, Lady Sheol...",
  ui_story_5071_50711601_6_dialog_content = "En memoria de la Sra. Yvonne, estamos lanzando sus libros. Esta es la primera tanda.",
  ui_story_5071_50711601_7_dialog_content = "Por favor, entrega unas copias al Señor Sombrío.",
  ui_story_5071_50711601_8_dialog_content = "Estoy seguro de que eso haría muy feliz al Señor de las Sombras... ¿Eh? ¿Qué son todos esos libros detrás de ti?",
  ui_story_5071_50711601_9_dialog_content = "¡Oh, eso! Esa es la nueva impresión de la Sra. Red Mercury, mi serie favorita.",
  ui_story_5071_50711601_X9_dialog_content = "Los lirios en la portada son tan simples y hermosos... Qué apropiado para la Sra. Mercurio Rojo... y también para tu madre...",
  ui_story_5071_50711601_X10_dialog_content = "Recuerdos eternos, amor insuperable y bendiciones profundas. Eso es lo que simbolizan los lirios.",
  ui_story_5071_50711601_X11_dialog_content = "... ¿No hay preguntas?",
  ui_story_5071_50711601_X12_dialog_content = "Ya me hablaste de mi madre, ¿verdad?",
  ui_story_5071_50711601_X13_dialog_content = "Sí.",
  ui_story_5071_50711601_X14_dialog_content = "Entonces, ¿qué hay que preguntar?",
  ui_story_5071_50711601_X15_dialog_content = "... La verdad es una espada de doble filo. A veces, opté por mentiras piadosas.",
  ui_story_5071_50711601_X16_dialog_content = "Tu madre sí murió de enfermedad, debido a la depresión en la que cayó intentando encontrarte.",
  ui_story_5071_50711601_X17_dialog_content = "La visité en su lecho de muerte y escuché su última petición.",
  ui_story_5071_50711601_X18_dialog_content = "Fue el gran amor que una madre tenía por su hija. No quería que te sintieras culpable, así que...",
  ui_story_5071_50711601_X19_dialog_content = "¿Puedo contar eso como otro favor que me debes?",
  ui_story_5071_50711601_X20_dialog_content = "... Solo bromeaba. Gracias, tío.",
  ui_story_5071_50711601_X21_dialog_content = "Simplemente no hagas eso más.",
  ui_story_5071_50711601_X22_dialog_content = "La honestidad debería ser la política para hacer negocios en Umbraton.",
  ui_story_5071_50711601_X23_dialog_content = "Jaja, tendré en cuenta ese consejo, Lady Sheol.",
  ui_story_5071_50711601_X24_dialog_content = "¡Mamá estará feliz de saber que los lirios también son perfectos para mí!",
  ui_story_5071_50711601_10_dialog_content = "Lástima que esté demasiado ocupado para leerlo en paz.",
  ui_story_5071_50711601_11_dialog_content = "Es una lástima lo que le sucedió al dirigible...",
  ui_story_5071_50711601_12_dialog_content = "Está bien, no es la primera vez que me pasa. Algunas se ganan, otras se pierden. Así es como va el negocio.",
  ui_story_5071_50711601_13_dialog_content = "De todas formas, soy libre de hacer negocios en cualquier lugar sin un dirigible.",
  ui_story_5071_50711601_14_dialog_content = "Me alivia escuchar eso y ver lo optimista que eres acerca de todo, Lady Sheol! ¡Cuídate!",
  ui_story_5071_50711601_15_dialog_content = "Me alegra que mi querido PlayerName me consuele, pero hacerlo con tu Colossus a cuestas me molesta un poco.",
  ui_story_5071_50711601_16_dialog_content = "Lo siento—",
  ui_story_5071_50711601_17_dialog_content = "Está bien.",
  ui_story_5071_50711601_18_dialog_content = "Ve y vuela orgullosamente con nuestros sueños a cuestas...",
  ui_story_5071_50711601_19_dialog_content = "<color=#e8d9bb>Toc, toc.</color>",
  ui_story_5071_50711601_20_dialog_content = "Ingresar.",
  ui_story_5071_50711601_21_dialog_content = "Soy yo, Señor Sombrío. Vine a entregar algunos libros— ¿Eh?",
  ui_story_5071_50711601_22_dialog_content = "¿Qué es? ¿Te asustó mi apariencia?",
  ui_story_5071_50711601_23_dialog_content = "¿Qué está pasando?",
  ui_story_5071_50711601_24_dialog_content = "El humo en las sombras aún no ha disipado— Algo me dice que la pelea aún no ha terminado.",
  ui_story_5071_50711601_25_dialog_content = "... Simplemente dejaré estos libros aquí.",
  ui_story_5071_50711601_26_dialog_content = "A Sheol realmente le gusta enviarte a hacer recados así... Gracias.",
  ui_story_5071_50711601_27_dialog_content = "¿Sigues teniendo pesadillas hoy en día?",
  ui_story_5071_50711601_28_dialog_content = "Jaja, todo depende de cómo definas \"pesadillas\". Solía ser prisionero de mi culpa, y mis sueños estaban llenos de recuerdos distorsionados del pasado.",
  ui_story_5071_50711601_29_dialog_content = "Pero ahora solo sueño con la verdad sin adornos. ¿Llamarías a mis sueños \"pesadillas\" ahora?",
  ui_story_5071_50711601_30_dialog_content = "<color=#e8d9bb>¡Toc, toc, toc. </color>",
  ui_story_5071_50711601_31_dialog_content = "Por favor, quédate aquí. No hay necesidad de irte.",
  ui_story_5071_50711601_32_dialog_content = "Entrar—",
  ui_story_5071_50711601_33_dialog_content = "¡Señor Istvan! ¡Señor Istvan!",
  ui_story_5071_50711601_34_dialog_content = "Mi querido Señor Istvan... Por favor acepta mi respeto. Deberías recordarme. Éramos socios.",
  ui_story_5071_50711601_35_dialog_content = "Si recuerdas nuestra amistad, por favor escucha mi sincera confesión...",
  ui_story_5071_50711601_36_dialog_content = "Habla.",
  ui_story_5071_50711601_37_dialog_content = "Vacilé en la Aeronave de Explorador Nublar y actué de manera inapropiada con algunos malos amigos...",
  ui_story_5071_50711601_38_dialog_content = "Cuando el Gremio los cierre, nuestro gremio también será... ¡Por favor, créeme! ¡Estoy arrepintiéndome sinceramente!",
  ui_story_5071_50711601_39_dialog_content = "Entonces... Por favor, muestra misericordia y permíteme regresar al Gremio.",
  ui_story_5071_50711601_40_dialog_content = "Dices que somos socios.",
  ui_story_5071_50711601_41_dialog_content = "Pero cuando comenzaron las reformas, te escondiste de las sombras por miedo a involucrarte conmigo.",
  ui_story_5071_50711601_42_dialog_content = "No, eso no es lo que pasó.",
  ui_story_5071_50711601_43_dialog_content = "A mis espaldas, tú y tus asociados hicieron una fortuna a través de vuestro negocio clandestino...",
  ui_story_5071_50711601_44_dialog_content = "En tus momentos más gloriosos, nunca tomaste en cuenta mi consejo.",
  ui_story_5071_50711601_45_dialog_content = "Solo después de que el Gremio sancionó tu negocio, viniste a mí buscando perdón.",
  ui_story_5071_50711601_46_dialog_content = "Yo-Yo es porque...",
  ui_story_5071_50711601_47_dialog_content = "Ahorra tus excusas— Ni una sola vez me has respetado o me has visto como un socio comercial.",
  ui_story_5071_50711601_48_dialog_content = "En tus ojos, el Señor Sombrío no es más que un obstáculo a superar.",
  ui_story_5071_50711601_49_dialog_content = "No... eso no es. ¡Por favor, escúchame!",
  ui_story_5071_50711601_50_dialog_content = "¡Voy a cambiar! No voy a conspirar con esas personas de nuevo. ¡Renunciaré a mi negocio clandestino!",
  ui_story_5071_50711601_51_dialog_content = "¡Por favor, pide al Gremio que sea indulgente con nosotros! Déjanos una salida. ¡Te lo suplico, Shadowlord!",
  ui_story_5071_50711601_52_dialog_content = "Salir.",
  ui_story_5071_50711601_53_dialog_content = "Entonces... ¿qué pasa con mi gremio... Señor de las Sombras?",
  ui_story_5071_50711601_54_dialog_content = "...",
  ui_story_5071_50711601_55_dialog_content = "¡Sí! ¡Sí! ¡Me perderé ahora! Me voy ahora...",
  ui_story_5071_50711601_56_dialog_content = "Lamento que hayas tenido que presenciar eso.",
  ui_story_5071_50711601_57_dialog_content = "<color=#FFB400>(¡¡¡Es incluso más amenazador que antes!!!)</color>",
  ui_story_5071_50711601_58_dialog_content = "Para ser honesto, incluso yo siento un poco de miedo al verte así...",
  ui_story_5071_50711601_59_dialog_content = "¡Jajaja! Por favor, quítatelo de la cabeza, amigo mío, solo deseo jugar una partida de ajedrez contigo.",
  ui_story_5071_50711601_60_dialog_content = "<color=#e8d9bb>Toc, toc.</color>",
  ui_story_5071_50711601_61_dialog_content = "Padre...",
  ui_story_5071_50711601_62_dialog_content = "...Adelante.",
  ui_story_5071_50711601_63_dialog_content = "Los resultados de la encuesta están disponibles. Nadie se opuso al proyecto de reforma.",
  ui_story_5071_50711601_64_dialog_content = "¿Realmente estoy dando una apariencia tan tiránica?",
  ui_story_5071_50711601_65_dialog_content = "No fue mi intención hacerlo, pero no negaré su utilidad en las negociaciones.",
  ui_story_5071_50711601_66_dialog_content = "Jaja, supongo que hace que los asuntos complicados sean mucho más simples.",
  ui_story_5071_50711601_67_dialog_content = "Además, Padre, tenemos hallazgos preliminares sobre quién está detrás de Hanstie.",
  ui_story_5071_50711601_68_dialog_content = "Parece que van a hacer más travesuras. Aquí están los archivos.",
  ui_story_5071_50711601_69_dialog_content = "Deja que vengan.",
  ui_story_5071_50711601_70_dialog_content = "Estoy preparado para cualquier batalla que nos presenten. No me esconderé más.",
  ui_story_5071_50711601_71_dialog_content = "Umbraton ya no es tan débil como antes. Nuestra ciudad está lista para recibir a invitados como ellos en cualquier momento.",
  ui_story_5071_50711601_72_dialog_content = "Kleken.",
  ui_story_5071_50711601_73_dialog_content = "¿Si, mi señor?",
  ui_story_5071_50711601_74_dialog_content = "Diles que comiencen los preparativos. Tenemos mucho trabajo por delante.",
  ui_story_5071_50711601_75_dialog_content = "Entendido. Comenzaré a preparar el banquete—",
  ui_story_5071_50711601_76_dialog_content = "Por favor, tómalo con calma, padre.",
  ui_story_5071_50711601_77_dialog_content = "Estás herido y envenenado. Debes descansar todo lo que puedas.",
  ui_story_5071_50711601_78_dialog_content = "(¿Eh? Incluso la actitud de Bethel parece un poco más relajada ahora. Casi parecen una padre e hija normales...)",
  ui_story_5071_50711601_79_dialog_content = "Todavía no soy tan viejo, Bethel. Permíteme continuar con mi trabajo.",
  ui_story_5071_50711601_80_dialog_content = "Lo siento, pero debería irme—",
  ui_story_5071_50711601_81_dialog_content = "Estoy seguro de que ustedes tienen mucho trabajo que hacer, así que me veré afuera.",
  ui_story_5071_50711601_82_dialog_content = "Por favor, perdóname, solo quería jugar un partido contigo hoy.",
  ui_story_5071_50711601_83_dialog_content = "Hasta la próxima, mi amigo.",
  ui_story_5071_50711601_84_dialog_content = "Adiós—",
  ui_story_5071_50711601_85_dialog_content = "¿Qué le hiciste a mi padre?",
  ui_story_5071_50711601_86_dialog_content = "Todos estamos asombrados por los cambios en él.",
  ui_story_5071_50711601_87_dialog_content = "¡N-No hice nada! El Señor de las Sombras simplemente llegó a algunas conclusiones por sí mismo, ¡lo prometo!",
  ui_story_5071_50711601_88_dialog_content = "¿En serio?",
  ui_story_5071_50711601_89_dialog_content = "Vale. Parece más sincero y agradable ahora. Me gusta mucho eso.",
  ui_story_5071_50711601_90_dialog_content = "Señora Bethel, hay más comunicaciones entrantes y nuevas reuniones que necesita organizar.",
  ui_story_5071_50711601_91_dialog_content = "Voy en camino. Gracias, PlayerName, y hasta la próxima vez.",
  ui_story_5071_50711601_92_dialog_content = "No hay de qué. ¡Nos vemos pronto!",
  ui_story_5071_50711601_93_dialog_content = "¡Apresúrate, ponle empeño! ¡El jefe nos está esperando!",
  ui_story_5071_50711601_94_dialog_content = "¡Vamos, vamos, vamos—!",
  ui_story_5071_50711601_95_dialog_content = "(Parecen bastante llenos de energía...)",
  ui_story_5071_50711601_96_dialog_content = "Todavía no tenemos idea de a quién buscamos, ¡pero a la carga!",
  ui_story_5071_50711601_97_dialog_content = "(El sol es tan brillante hoy. ¿Alguna vez ha sido tan brillante en Umbraton?)",
  ui_story_5071_50711601_98_dialog_content = "¡Ten cuidado! Por favor, presta atención al tráfico incluso si estás transportando materiales de construcción escolar!",
  ui_story_5071_50711601_99_dialog_content = "(Umbraton se ve hermoso a la luz del sol—)",
  ui_story_5071_50711601_100_dialog_content = "¡Date prisa y lleva las cosas que los invitados quieren al vehículo de entrega...",
  ui_story_5071_50711601_101_dialog_content = "¡No des la impresión de que el Gremio Umbraton es lento!",
  ui_story_5071_50711601_102_dialog_content = "Parece que todos quieren disfrutar del buen tiempo hoy.",
  ui_story_5071_50711601_103_dialog_content = "Tal vez debería ir a ver una película con Vice? Espero que todavía queden algunas entradas...",
  ui_story_5071_50711601_104_dialog_content = "Este libro...",
  ui_story_5071_50711601_105_dialog_content = "Sí... Esto es perfecto para leer a la luz del sol.",
  ui_story_5071_50711601_106_dialog_content = "Je, y resulta que el sol brilla especialmente brillante hoy. Nuestra ciudad también...",
  ui_story_5071_50711601_107_dialog_content = "Justo como siempre soñamos—",
  ui_story_5071_50711601_108_dialog_content = "¿No es así, mi viejo amigo?",
  ui_story_5071_50711601_109_dialog_content = "Parece que todo ha sido manejado bien. Finalmente, las cosas están en orden ahora.",
  ui_story_5071_50711601_110_dialog_content = "He aprendido mucho después de todos estos años—",
  ui_story_5071_50711601_111_dialog_content = "Parece que soy un buen profesor.",
  ui_story_5071_50711601_112_dialog_content = "Tan hermoso... Nunca me di cuenta de que nuestra ciudad natal podría ser tan brillante...",
  ui_story_5071_50711601_113_dialog_content = "Después de hoy, nuestros sueños para Umbraton solo se harán más fuertes, y...",
  ui_story_5071_50711601_114_dialog_content = "Definitivamente podrán extender las alas y volar algún día...",
  ui_story_5071_50711601_115_dialog_content = "Espero ese día."
}
return config
